(1, '杂种猪(肉色)', 1, 1, '虽然自己没能成为特别的猪，但是或许会做出特别的事情。', 1, 1, 1, 123.9, 160, 300, 500, 3, 0, 0, 'normal', '{"hunt":{"sites":[2]},"fail":[609,543]}', NULL, NULL, NULL, 1788143395110, NULL),
(2, '杂种猪(灰色)', 1, 2, '虽然自己没能成为特别的猪，但是它父母或许是特别的。', 2, 1, 1, 123.9, 160, 300, 500, 3, 0, 0, 'normal', '{"hunt":{"sites":[2]},"fail":[50,522]}', NULL, NULL, NULL, 1788143395110, NULL),
(3, '杂种猪(米色)', 1, 3, '虽然自己没能成为特别的猪，但是或许已经成为了特别的存在。', 3, 1, 1, 123.9, 160, 300, 500, 3, 0, 0, 'normal', '{"hunt":{"sites":[2]},"fail":[590,514]}', NULL, NULL, NULL, 1788143395110, NULL),
(4, '杂种猪(粉红)', 1, 4, '虽然自己没能成为特别的猪，但是或许存在特别的可能性。', 4, 1, 1, 123.9, 160, 300, 500, 3, 0, 0, 'normal', '{"hunt":{"sites":[2]},"fail":[535,547]}', NULL, NULL, NULL, 1788143395110, NULL),
(5, '杂种猪(白色)', 1, 5, '虽然自己没能成为特别的猪，不特别歧视也是很好的。', 5, 1, 1, 123.9, 160, 300, 500, 3, 0, 0, 'normal', '{"hunt":{"sites":[2]},"fail":[528]}', NULL, NULL, NULL, 1788143395110, NULL),
(6, '兰德莱斯猪', 1, 4, '生下很多小猪，而且发育很早，很常见。猪猪小屋的其他母猪都追求着这种卓越的母性。', 4, 2, 1, 124.4, 153.2, 800, 1000, 3, 0, 0, 'normal', '{"shop":[0,0,0.034848484848485],"hunt":{"sites":[1,4,11],"prob":{"any":{"4":0.052631578947368,"11":0.035714285714286},"same":{"4":0.5,"11":0.14285714285714}}},"specialFeeding":true}', '{"interval":1,"times":1,"picky":[4]}', NULL, NULL, 1788143395110, NULL),
(7, '伊比利亚猪/(橡子喂食)', 5, 2, '最高等级的西班牙猪。只有通过一些严格条件，才能以此自称的猪。', 2, 2, 1, 175, 200, 8000, 10000, 40, 1, 0, 'normal', '{"shop":[0.003030303030303,0,0],"hunt":{"sites":[1,2,5,12],"prob":{"any":{"5":0.018867924528302,"12":0.028571428571429},"same":{"5":0.052631578947368,"12":0.066666666666667}}},"specialFeeding":true}', '{"interval":2,"times":10,"picky":[6]}', '{"requirements":"成猪前体重限制 ≥128.0 kg","tips":null}', NULL, 1788143395110, NULL),
(8, '伊比利亚猪/(放牧喂食)', 4, 2, '虽然有最高等级的潜力，但是没有实现。如果是橡子喂食的话，可能会实现。', 2, 3, 1, 134.2, 162.4, 6000, 8000, 40, 1, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,2,5,12],"prob":{"any":{"5":0.018867924528302,"12":0.028571428571429},"same":{"5":0.052631578947368,"12":0.066666666666667}}},"fail":[7],"specialFeeding":true}', '{"interval":3,"times":8,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(9, '伊比利亚猪/(混合喂食)', 4, 2, '虽然做梦梦到像其他的伊比利亚猪一样吃着橡子，最终还是没吃到就被卖掉了。', 2, 4, 1, 139.6, 165.3, 5000, 6000, 24, 1, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,2,6,12],"prob":{"any":{"6":0.037037037037037,"12":0.028571428571429},"same":{"6":0.11111111111111,"12":0.066666666666667}}},"specialFeeding":true}', '{"interval":2,"times":8,"picky":[7]}', NULL, NULL, 1788143395110, NULL),
(10, '杜洛克猪', 1, 3, '能够食用的肉量多。为了交配和其他种类的猪相亲的次数很多，很想恋爱结婚。', 3, 2, 1, 125.7, 160.6, 1000, 1500, 4, 0, 0, 'normal', '{"shop":[0,0,0.034848484848485],"hunt":{"sites":[1,3,13],"prob":{"any":{"3":0.014084507042254,"13":0.052631578947368},"same":{"3":0.1,"13":0.14285714285714}}},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(11, '汉普夏猪', 2, 2, '虽然在美国是较大的猪，不过最近被比自己优秀的杜洛克猪夺去了宝座，有一点自卑。', 2, 5, 1, 124.8, 168.4, 800, 1000, 3, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,3,13],"prob":{"any":{"3":0.014084507042254,"13":0.052631578947368},"same":{"3":0.066666666666667,"13":0.33333333333333}}},"specialFeeding":true}', '{"interval":1,"times":2,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(12, '巴克夏猪', 1, 2, '英国原产的黑猪。曾经一时被白猪压制，但在不断顽强的挣扎之后迎来了新的机会。成功被改良成各种猪的典型。', 2, 6, 1, 125.7, 139.6, 1000, 1500, 16, 0, 0, 'normal', '{"shop":[0,0,0.034848484848485],"hunt":{"sites":[1,4,11],"prob":{"any":{"4":0.052631578947368,"11":0.035714285714286},"same":{"4":0.25,"11":0.16666666666667}}},"specialFeeding":true}', '{"interval":2,"times":3,"picky":[2,3]}', NULL, NULL, 1788143395110, NULL),
(13, '黑猪', 3, 2, '只有拥有巴克夏猪的纯粹血统的猪，才能自称为黑猪。猪界的世家贵族。', 2, 7, 1, 128.4, 151.6, 3000, 5000, 24, 0, 0, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":2,"times":6,"picky":[2,3]}', NULL, NULL, 1788143395110, NULL),
(14, '大约克夏猪/(美国)', 1, 1, '所谓白猪。肉型。据记录，在美国的饲养数是最多的。母猪到处都很受欢迎。', 1, 2, 1, 123.9, 160.6, 800, 1000, 4, 0, 0, 'normal', '{"shop":[0,0,0.034848484848485],"hunt":{"sites":[1,3,13],"prob":{"any":{"3":0.014084507042254,"13":0.052631578947368},"same":{"3":0.047619047619048,"13":0.16666666666667}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(15, '大约克夏猪/(英国)', 1, 1, '所谓白猪。作为培根等的加工原料得到了很高的评价。躯干长的体型，腰腿强壮有分量。', 1, 3, 1, 123.9, 160.6, 800, 1000, 4, 0, 0, 'normal', '{"shop":[0,0,0.034848484848485],"hunt":{"sites":[1,3,11],"prob":{"any":{"3":0.014084507042254,"11":0.035714285714286},"same":{"3":0.047619047619048,"11":0.16666666666667}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(16, '草本猪', 1, 5, '在健康方面，比其他的猪营养价值高，而且没有异味，是智力高等的天然猪。', 5, 2, 1, 127.1, 155.8, 1000, 2000, 8, 0, 0, 'normal', '{"shop":[0,0,0.034848484848485],"hunt":{"sites":[1,2,4,7],"prob":{"any":{"4":0.052631578947368,"7":0.041666666666667},"same":{"4":0.25,"7":0.25}}},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[5]}', NULL, NULL, 1788143395110, NULL),
(17, '扑满', 4, 4, '所谓扑满，是指徒有其名的高级志向的暴发户猪，所以食物费增多，钱也减少。', 4, 3, 1, 132.2, 164.8, 800, 2000, 16, 0, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,2,6,8],"prob":{"any":{"6":0.037037037037037,"8":0.0625},"same":{"6":0.25,"8":0.33333333333333}}},"specialFeeding":true}', '{"interval":2,"times":3,"picky":[8]}', NULL, NULL, 1788143395110, NULL),
(18, '金华猪', 2, 2, '特征是只有脸和臀部是黑色的。通过火腿才能将自己的魅力最大限度地展示出来！火腿广告到处可见。', 2, 8, 1, 128.5, 172.3, 1500, 3000, 24, 0, 0, 'normal', '{"hunt":{"sites":[4],"prob":{"any":{"4":0.052631578947368},"same":{"4":0.25}}},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[4]}', NULL, NULL, 1788143395110, NULL),
(19, '下颚突猪', 3, 5, '真正的名字是约克夏猪。某天突然变成了奇怪的猪。不断在努力生存，难饲养和体弱是致命伤啊。', 5, 3, 1, 130.2, 162.9, 2000, 3000, 16, 0, 0, 'normal', '{"hunt":{"sites":[6],"prob":{"any":{"6":0.037037037037037},"same":{"6":0.2}}},"specialFeeding":true}', '{"interval":1,"times":8,"picky":[2,3]}', NULL, NULL, 1788143395110, NULL),
(20, '无法违抗重力', 3, 2, '日本没有太多的奇怪的猪。在原产国中国几乎也没有人见过。传说是猪八戒的原型。', 2, 9, 1, 126.6, 151.6, 1500, 2500, 24, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,4,6,9,10],"prob":{"any":{"4":0.052631578947368,"6":0.037037037037037,"9":0.083333333333333,"10":0.090909090909091},"same":{"4":0.25,"6":0.11111111111111,"9":0.2,"10":0.2}}},"specialFeeding":true}', '{"interval":2,"times":4,"picky":[2,3]}', NULL, NULL, 1788143395110, NULL),
(21, '猪八戒', 4, 3, '什么食物都能吃得一干二净的贪吃猪。手上的武器从仓库借来的。', 3, 3, 1, 132.4, 189.1, 3000, 4000, 12, 0, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,2,5,10],"prob":{"any":{"5":0.018867924528302,"10":0.090909090909091},"same":{"5":0.083333333333333,"10":0.5}}},"specialFeeding":true}', '{"interval":1,"times":6,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(22, '牧羊猪', 2, 5, '羡慕牧羊犬，决心要成为牧羊猪，但是这里没有羊，所以打算牧猪…？不太明白。', 5, 4, 1, 123.9, 169.1, 2000, 2500, 4, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,2,3,15],"prob":{"any":{"3":0.014084507042254,"15":0.11111111111111},"same":{"3":0.066666666666667,"15":0.33333333333333}}},"specialFeeding":true}', '{"interval":1,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(23, '红猪', 4, 4, '普通的红猪。', 4, 4, 1, 129.7, 164.8, 1000, 1500, 16, 0, 0, 'normal', '{"hunt":{"sites":[5],"prob":{"any":{"5":0.018867924528302},"same":{"5":0.33333333333333}}},"specialFeeding":true}', '{"interval":2,"times":3,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(24, '东京Z', 2, 3, '守护猪猪小屋和平与秩序的英雄。主要的活动是巡视小屋。因为太和平，内心一直想要刺激。', 3, 4, 1, 125.7, 163.6, 1500, 2000, 8, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,2,4,7],"prob":{"any":{"4":0.052631578947368,"7":0.041666666666667},"same":{"4":0.16666666666667,"7":0.2}}},"specialFeeding":true}', '{"interval":1,"times":2,"picky":[4]}', NULL, NULL, 1788143395110, NULL),
(25, '东京Y', 2, 3, '守护猪猪小屋爱与希望的英雄。主要的活动内容是猪猪们的烦恼咨询。但是自己的烦恼和谁说呢。', 3, 5, 1, 125.7, 163.6, 1500, 2000, 8, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,2,4,7],"prob":{"any":{"4":0.052631578947368,"7":0.041666666666667},"same":{"4":0.16666666666667,"7":0.2}}},"specialFeeding":true}', '{"interval":1,"times":2,"picky":[4]}', NULL, NULL, 1788143395110, NULL),
(26, '长子', 1, 1, '三兄弟的长子。听天由命自由奔放地活着。/讨厌的话是“因为是哥哥”。', 1, 4, 1, 123.9, 160.6, 800, 1500, 4, 0, 0, 'normal', '{"shop":[0,0,0.034848484848485],"hunt":{"sites":[1,2,3,15],"prob":{"any":{"3":0.014084507042254,"15":0.11111111111111},"same":{"3":0.047619047619048,"15":0.33333333333333}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(27, '次子', 1, 1, '三兄弟的次子。凡事都适可而止不努力到底的性格。讨厌的话是“请冷静”。', 1, 5, 1, 123.9, 160.6, 800, 1500, 4, 0, 0, 'normal', '{"shop":[0,0,0.034848484848485],"hunt":{"sites":[1,2,3,15],"prob":{"any":{"3":0.014084507042254,"15":0.11111111111111},"same":{"3":0.047619047619048,"15":0.33333333333333}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(28, '末子', 3, 1, '三兄弟的末子。把哥哥们当做反面教材，小心谨慎，而且很较真。喜欢的话是“与哥哥们不同”', 1, 6, 1, 124.8, 180.7, 1500, 2000, 8, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,2,3,15,16],"prob":{"any":{"3":0.014084507042254,"15":0.11111111111111,"16":0.2},"same":{"3":0.047619047619048,"15":0.33333333333333,"16":1}}},"specialFeeding":true}', '{"interval":1,"times":2,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(29, '野猪', 4, 1, '从绳文时代开始就有饲养记录。在江户时代被称为“山鲸鱼”，现在被称为“牡丹肉”。', 6, 1, 1, 127.9, 192.5, 2000, 3000, 16, 0, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,5,8],"prob":{"any":{"5":0.018867924528302,"8":0.0625},"same":{"5":0.5,"8":1}}},"fail":[508]}', NULL, NULL, NULL, 1788143395110, NULL),
(30, '玛格丽特猪', 5, 3, '毛茸茸的匈牙利产可以食用的国宝。世界上脂肪率最高，和伊比利亚的肉质相似，很~好吃。', 3, 6, 1, 137, 203.1, 8000, 10000, 40, 1, 0, 'normal', '{"shop":[0.003030303030303,0,0],"hunt":{"sites":[1,6,12],"prob":{"any":{"6":0.037037037037037,"12":0.028571428571429},"same":{"6":0.16666666666667,"12":0.2}}},"specialFeeding":true}', '{"interval":1,"times":10,"picky":[2,6]}', NULL, NULL, 1788143395110, NULL),
(31, '金扑满', 5, 5, '很会花钱。/据说财运会变好，大概。', 5, 5, 1, 132.7, 165.6, 5000, 7000, 12, 0, 0, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":2,"times":3,"picky":[7,8]}', NULL, NULL, 1788143395110, NULL),
(32, '斑点猪', 2, 5, '对自己黑白斑点的比率很有讲究的“美猪”。过去被广泛进口，现在比较少见了。', 5, 6, 1, 123.9, 171.9, 2000, 2500, 8, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,2,3,13],"prob":{"any":{"3":0.014084507042254,"13":0.052631578947368},"same":{"3":0.066666666666667,"13":0.5}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(33, '某只琉球猪', 4, 2, '因为丑闻不断，所以不会透露本来的名字。可公开的只有出身地资讯，谜一样的黑猪。', 2, 10, 1, 131.5, 180.7, 4000, 5000, 16, 0, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,6,8],"prob":{"any":{"6":0.037037037037037,"8":0.0625},"same":{"6":0.11111111111111,"8":0.33333333333333}}},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[3,4]}', NULL, NULL, 1788143395110, NULL),
(34, '大花白猪', 2, 5, '很有历史渊源，有去英国的“出国”经历。小猪时期就容易胖，然后常被拿来烧烤。', 5, 7, 1, 125.7, 171.9, 2000, 3000, 8, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,3,9],"prob":{"any":{"3":0.014084507042254,"9":0.083333333333333},"same":{"3":0.066666666666667,"9":0.25}}},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(35, '三元猪', 1, 3, '3种纯种猪配种而成，继承了各自的优点的第一代杂种超级混合猪。', 3, 7, 1, 123.9, 160.6, 1500, 3000, 4, 0, 0, 'normal', '{"hunt":{"sites":[2,3,7],"prob":{"any":{"3":0.014084507042254,"7":0.041666666666667},"same":{"3":0.1,"7":0.2}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(36, '炸猪排', 1, 1, '提到日式猪肉料理那就是它了。作为能够做出餐馆推荐NO.1的首席猪，期待它今后的活跃。', 1, 7, 1, 123.9, 145.4, 1500, 2000, 4, 0, 0, 'normal', '{"shop":[0,0,0.034848484848485],"hunt":{"sites":[1,2,4,7],"prob":{"any":{"4":0.052631578947368,"7":0.041666666666667},"same":{"4":0.33333333333333,"7":0.076923076923077}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[3]}', NULL, NULL, 1788143395110, NULL),
(37, '恋爱猪', 1, 4, '最喜欢恋爱话题的恋爱脑。基本上掌握了猪猪小屋里的全部八卦资讯。/正在暗恋藤田叔。', 4, 5, 1, 123.9, 160.6, 500, 1000, 4, 0, 0, 'normal', '{"shop":[0,0,0.034848484848485],"hunt":{"sites":[1,2,3,15],"prob":{"any":{"3":0.014084507042254,"15":0.11111111111111},"same":{"3":0.1,"15":0.5}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(38, '很man的猪', 4, 3, '对自己非常严格，只是一味的持续锻炼肌肉。但是从猪肉的角度来看，卖价就不高了。', 3, 8, 1, 130.6, 189.1, 1000, 1500, 12, 1, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,2,5,14],"prob":{"any":{"5":0.018867924528302,"14":0.066666666666667},"same":{"5":0.083333333333333,"14":0.125}}},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(39, '珍猪', 4, 1, '珍猪或许不知道自己的价值。出货之后珍珠会被没收。', 1, 8, 1, 127.9, 182.1, 3000, 4000, 4, 0, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,2,5,8],"prob":{"any":{"5":0.018867924528302,"8":0.0625},"same":{"5":0.14285714285714,"8":0.33333333333333}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(40, '丘比猪', 2, 1, '作为爱情顾问出去做生意，但是只会多管闲事，很不顺利。/所谓恋爱猪，就是爱谈恋爱话题的朋友。', 1, 9, 1, 123.9, 171.9, 1500, 2500, 8, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,2,3,11],"prob":{"any":{"3":0.014084507042254,"11":0.035714285714286},"same":{"3":0.047619047619048,"11":0.16666666666667}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(41, '迷你猪', 3, 1, '和其他的猪比没有那么大，所以大家都很关注它的成长。经常作为宠物饲养，所以会比大家长寿，大概。', 1, 10, 1, 123.9, 193.2, 2000, 3000, 24, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,3,5,9,10],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"9":0.083333333333333,"10":0.090909090909091},"same":{"3":0.047619047619048,"5":0.14285714285714,"9":1,"10":0.5}}},"fail":[527],"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(42, '中二猪', 1, 1, '多愁善感的全盛时期。/明明喜欢的是粗粮，但是经常逞能去吃橡子！', 1, 11, 1, 124.4, 153.4, 300, 500, 3, 0, 0, 'normal', '{"shop":[0,0,0.034848484848485],"hunt":{"sites":[1,2,7],"prob":{"any":{"7":0.041666666666667},"same":{"7":0.076923076923077}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[6]}', NULL, NULL, 1788143395110, NULL),
(43, '佛猪', 4, 5, '为了人类而牺牲自己，有自我牺牲觉悟精神的猪中豪杰。真正的猪在被卖出的时候，也是心情愉悦的。', 5, 8, 1, 130.6, 161.6, 4000, 5000, 24, 0, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,6,8],"prob":{"any":{"6":0.037037037037037,"8":0.0625},"same":{"6":0.2,"8":0.2}}},"specialFeeding":true}', '{"interval":2,"times":4,"picky":[2,5]}', NULL, NULL, 1788143395110, NULL),
(44, '野家混合猪', 4, 1, '不知是不是继承了野猪的血统的缘故，比一般的猪性情暴躁。', 6, 2, 1, 129.7, 169.4, 3000, 4000, 24, 1, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[2]}', NULL, NULL, 1788143395110, NULL),
(45, '麦当猪', 3, 5, '把异性作为媚惑的俘虏，充满魅力的猪。因为没有合适的伴侣，所以想快点从猪猪小屋里出去。', 5, 9, 1, 123.9, 187, 2000, 3000, 16, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,2,3,5,11,12],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"11":0.035714285714286,"12":0.028571428571429},"same":{"3":0.066666666666667,"5":0.1,"11":0.16666666666667,"12":0.125}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(46, '古铜猪', 3, 3, '皮肤被晒得恰到好处的猪。人们说它很花心，其实是一心一意的猪。', 3, 9, 1, 123.9, 180.7, 1000, 1500, 8, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,2,3,5,13,14],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"13":0.052631578947368,"14":0.066666666666667},"same":{"3":0.1,"5":0.083333333333333,"13":0.14285714285714,"14":0.125}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(47, '朋子(假名)', 4, 4, '不懂世故的公主猪。偷偷潜入了的猪猪小屋，觉得这里的生活新鲜充实，非常满足。', 4, 6, 1, 130.1, 181, 3500, 4000, 8, 0, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,6,12],"prob":{"any":{"6":0.037037037037037,"12":0.028571428571429},"same":{"6":0.25,"12":0.33333333333333}}},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[7]}', NULL, NULL, 1788143395110, NULL),
(48, '塞巴斯猪', 3, 2, '想要把公主猪带回家的管家猪。经常很绅士，在母猪中猪气很高。', 2, 11, 1, 123.9, 180.7, 1500, 2500, 8, 0, 0, 'normal', '{"hunt":{"sites":[2,3,5,11,12],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"11":0.035714285714286,"12":0.028571428571429},"same":{"3":0.066666666666667,"5":0.052631578947368,"11":0.16666666666667,"12":0.066666666666667}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(49, '海南猪', 1, 2, '从头部到尾部都是黑色的，在黑色和白色的交界处有灰色的部分。在温和的气候里成长。肚子很松弛。', 2, 12, 1, 123.9, 145.4, 1000, 1500, 4, 0, 0, 'normal', '{"hunt":{"sites":[4],"prob":{"any":{"4":0.052631578947368},"same":{"4":0.25}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[2]}', NULL, NULL, 1788143395110, NULL),
(50, '大黑猪', 5, 2, '英国原产的很有历史的猪，具有压倒性存在感的稀有种。下垂的大耳朵遮住了眼睛，看不到自己的前面。', 2, 13, 1, 360, 401, 6000, 7000, 40, 1, 0, 'normal', '{"shop":[0.003030303030303,0,0],"hunt":{"sites":[1,5,12],"prob":{"any":{"5":0.018867924528302,"12":0.028571428571429},"same":{"5":0.052631578947368,"12":0.066666666666667}}},"specialFeeding":true}', '{"interval":0,"times":13,"picky":[]}', '{"requirements":"成猪前体重限制 ≥128.0 kg","tips":null}', NULL, 1788143395110, NULL),
(51, '武士猪', 1, 1, '本来是普通的猪，但被武士的地缚灵抓住。经常会怀念因为战斗而分别的妹妹。', 1, 12, 1, 123.9, 163, 1000, 1500, 8, 0, 0, 'normal', '{"shop":[0,0,0.034848484848485],"hunt":{"sites":[1,2,3,7],"prob":{"any":{"3":0.014084507042254,"7":0.041666666666667},"same":{"3":0.047619047619048,"7":0.076923076923077}}},"fail":[161],"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(52, '巴赫猪', 2, 5, '被称为音乐之父的天才作曲猪。/想和其他作曲猪一起构想音乐。', 5, 10, 1, 123.9, 171.9, 1500, 2000, 8, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,3,11],"prob":{"any":{"3":0.014084507042254,"11":0.035714285714286},"same":{"3":0.066666666666667,"11":0.16666666666667}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(53, '猪猪船长', 4, 3, '自称为船长，但是没有其他船员，正在募集中。眼罩只是时尚。打架很强。', 3, 10, 1, 130.6, 189.1, 4500, 5000, 12, 0, 0, 'normal', '{"hunt":{"sites":[2,5,14],"prob":{"any":{"5":0.018867924528302,"14":0.066666666666667},"same":{"5":0.083333333333333,"14":0.125}}},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(54, '迷彩猪', 2, 3, '虽然能用迷彩来掩盖自己的身体，但是喘息声让它立马暴露，由于这种致命失误就要被卖出了。', 3, 11, 1, 123.9, 174.6, 2000, 2500, 12, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,2,3,13],"prob":{"any":{"3":0.014084507042254,"13":0.052631578947368},"same":{"3":0.1,"13":0.14285714285714}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(55, '感谢猪', 3, 3, '在311地震中存活的猪。充满很强的幸运与生命力，以复兴震灾为目标，充满希望的猪。', 3, 12, 1, 125.6, 179.4, 3500, 4000, 12, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,2,4,6,7,8],"prob":{"any":{"4":0.052631578947368,"6":0.037037037037037,"7":0.041666666666667,"8":0.0625},"same":{"4":0.16666666666667,"6":0.16666666666667,"7":0.2,"8":1}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[7]}', NULL, NULL, 1788143395110, NULL),
(56, '琴塔猪', 5, 2, '面临灭绝的危机但是成功存活的历经波折的高级猪。比通常的猪饲养时间长。', 2, 33, 1, 138.9, 203.1, 7000, 8000, 40, 1, 0, 'normal', '{"shop":[0.003030303030303,0,0],"hunt":{"sites":[1,6,12],"prob":{"any":{"6":0.037037037037037,"12":0.028571428571429},"same":{"6":0.11111111111111,"12":0.066666666666667}}},"specialFeeding":true}', '{"interval":0,"times":8,"picky":[6]}', NULL, NULL, 1788143395110, NULL),
(57, '比格尔猪', 4, 2, '法国原产的最古老的品种，伊比利亚猪的远房亲戚。和蔼可亲，以及对食物的执著是其魅力所在。', 2, 14, 1, 135.2, 186.1, 4500, 5000, 24, 1, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,6,12],"prob":{"any":{"6":0.037037037037037,"12":0.028571428571429},"same":{"6":0.11111111111111,"12":0.066666666666667}}},"specialFeeding":true}', '{"interval":0,"times":6,"picky":[6]}', NULL, NULL, 1788143395110, NULL),
(58, '海猪', 3, 1, '擅长游泳。回到巴哈马，在美丽的海中，享受阳光，一辈子优雅地游泳是它的梦想。', 1, 13, 1, 123.9, 180.7, 2000, 2500, 8, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,2,3,5,13,14],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"13":0.052631578947368,"14":0.066666666666667},"same":{"3":0.047619047619048,"5":0.14285714285714,"13":0.16666666666667,"14":0.33333333333333}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(59, '新草本猪', 3, 4, '和草本猪其实没有什么不一样。有点怪怪的猪，审美意识很高。', 4, 7, 1, 124.4, 171.4, 1500, 2000, 8, 0, 0, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[5]}', NULL, NULL, 1788143395110, NULL),
(60, '受伤猪', 1, 5, '每天受伤不断，所以不能没有急救箱。偶尔会自豪地说伤口是勋章。', 5, 11, 1, 123.9, 161.8, 600, 1000, 6, 0, 0, 'normal', '{"shop":[0,0,0.034848484848485],"hunt":{"sites":[1,2,3,7],"prob":{"any":{"3":0.014084507042254,"7":0.041666666666667},"same":{"3":0.066666666666667,"7":0.25}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(61, '波特贝利达猪', 3, 2, '稳重的体型。一点不像和迷你猪是同类。/难道是变异了？', 2, 15, 1, 126.6, 187, 2000, 3000, 16, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,3,5,9,10],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"9":0.083333333333333,"10":0.090909090909091},"same":{"3":0.066666666666667,"5":0.052631578947368,"9":0.2,"10":0.2}}},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(62, '骨头猪', 1, 2, '其实并不是透明的模样。/对骨头特别有自信，将来希望成为美味的猪骨头汤。', 2, 16, 1, 123.9, 161.8, 1000, 1500, 6, 0, 0, 'normal', '{"hunt":{"sites":[3],"prob":{"any":{"3":0.014084507042254},"same":{"3":0.066666666666667}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(63, '竞速猪', 2, 1, '小猪赛跑的原冠军。无法忘怀过去的光辉成绩。只有速度是优点的猪。', 1, 14, 1, 123.9, 170.5, 1000, 1500, 6, 0, 0, 'normal', '{"hunt":{"sites":[2,3,7],"prob":{"any":{"3":0.014084507042254,"7":0.041666666666667},"same":{"3":0.047619047619048,"7":0.076923076923077}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(64, '内江猪', 2, 2, '中国的原有品种，从1800年前就存在了。身体很大，总是伸出舌头的有趣面孔。', 2, 17, 1, 123.9, 174.6, 1500, 2000, 12, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,3,9],"prob":{"any":{"3":0.014084507042254,"9":0.083333333333333},"same":{"3":0.066666666666667,"9":0.2}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(65, '料理猪', 2, 5, '虽然擅长料理，但容易忘记自己也是作为食物的原料。/累积修行，梦想是想要开自己的料亭。', 5, 12, 1, 123.9, 171.9, 1000, 1500, 8, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,2,3,7],"prob":{"any":{"3":0.014084507042254,"7":0.041666666666667},"same":{"3":0.066666666666667,"7":0.25}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(66, '相扑猪', 3, 1, '猪相扑界的横纲。通称为“猪乃鼻”。梦想退役后成为相扑老师。', 1, 15, 1, 128.4, 193.2, 3500, 4000, 24, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,2,3,5,7,8],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"7":0.041666666666667,"8":0.0625},"same":{"3":0.047619047619048,"5":0.14285714285714,"7":0.076923076923077,"8":0.33333333333333}}},"specialFeeding":true}', '{"interval":0,"times":6,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(67, '酷你酷你猪', 4, 3, '只吃草就能存活，作为和蔼可亲的宠物被饲养。某海外动画电影角色的原型。', 3, 13, 1, 129.7, 165.8, 3000, 3500, 16, 1, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,6,16],"prob":{"any":{"6":0.037037037037037,"16":0.2},"same":{"6":0.16666666666667,"16":0.25}}},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[2]}', NULL, NULL, 1788143395110, NULL),
(68, '老斑点猪', 1, 4, '来自叫做格洛斯特的古老地方。在英国自古就熟识的品种。现在濒临灭绝，使人担忧。', 4, 8, 1, 125.7, 167.9, 1500, 2000, 16, 0, 0, 'normal', '{"shop":[0,0,0.034848484848485],"hunt":{"sites":[1,3,11],"prob":{"any":{"3":0.014084507042254,"11":0.035714285714286},"same":{"3":0.1,"11":0.14285714285714}}},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(69, '巴斯克猪', 5, 2, '从前普遍流通，近年来数量急剧减少。味道丰富，肉质柔软，可作为加工肉。', 2, 18, 1, 134.8, 246.2, 8000, 8500, 32, 1, 0, 'normal', '{"hunt":{"sites":[6],"prob":{"any":{"6":0.037037037037037},"same":{"6":0.11111111111111}}},"specialFeeding":true}', '{"interval":1,"times":5,"picky":[6]}', NULL, NULL, 1788143395110, NULL),
(70, '切斯特猪/白色', 3, 5, '白猪版的杜洛克的感觉。在群体中不会打架，性格温顺。对阳光敏感，喜欢宅著不出去。', 5, 13, 1, 123.9, 187, 2500, 3000, 16, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,2,3,5,13,14],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"13":0.052631578947368,"14":0.066666666666667},"same":{"3":0.066666666666667,"5":0.1,"13":0.5,"14":0.5}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(71, '爱迪生猪', 3, 1, '总是减少睡眠时间在开发什么东西，所以忘记了主人的面容，“谁来着？”总是这样说。', 1, 16, 1, 123.9, 187, 2000, 2500, 16, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,2,3,5,13,14],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"13":0.052631578947368,"14":0.066666666666667},"same":{"3":0.047619047619048,"5":0.14285714285714,"13":0.16666666666667,"14":0.33333333333333}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(72, '波兰猪/中国种', 2, 2, '为了拥有更具有良好特性的猪，和各国各式各样的猪进行交配的多国籍。其实不会说外语。', 2, 19, 1, 123.9, 171.9, 2000, 2500, 8, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,2,3,13],"prob":{"any":{"3":0.014084507042254,"13":0.052631578947368},"same":{"3":0.066666666666667,"13":0.33333333333333}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(73, '双眼皮猪', 1, 4, '和其他的混合种不一样，眼睛是双重的。看上去好像快要睡着了，实际上只是很困。', 4, 9, 1, 123.9, 160.6, 500, 800, 4, 0, 0, 'normal', '{"shop":[0,0,0.034848484848485],"hunt":{"sites":[1,2,3,11],"prob":{"any":{"3":0.014084507042254,"11":0.035714285714286},"same":{"3":0.1,"11":0.14285714285714}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(74, '谭沃思猪', 4, 3, '很结实的猪。适合作为培根。在小屋的10天里都在展开逃跑大戏的傻猪。', 3, 14, 1, 130.6, 199.5, 2500, 3500, 24, 1, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,2,5,12],"prob":{"any":{"5":0.018867924528302,"12":0.028571428571429},"same":{"5":0.083333333333333,"12":0.2}}},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(75, '英国/马鞍猪', 4, 2, '原产英国。适合做培根，据说以前是很受欢迎的，但由于脂肪太厚的原因渐渐衰败。如今是稀有种。', 2, 20, 1, 129.7, 199.8, 5000, 5500, 32, 0, 0, 'normal', '{"hunt":{"sites":[2,6,12],"prob":{"any":{"6":0.037037037037037,"12":0.028571428571429},"same":{"6":0.11111111111111,"12":0.066666666666667}}},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[3,7]}', NULL, NULL, 1788143395110, NULL),
(76, '莫札猪', 3, 5, '在音乐方面有天赋，但是喜欢说有关便便的话题。', 5, 14, 1, 123.9, 187, 2500, 3000, 16, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,2,3,5,11,12],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"11":0.035714285714286,"12":0.028571428571429},"same":{"3":0.066666666666667,"5":0.1,"11":0.16666666666667,"12":0.125}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(77, '安特瓦内特猪', 4, 4, '有过“要是没有粗粮就吃松露好了”这种惹起众怒的发言。被卖掉前踩了主人脚，但好像不是故意的。', 4, 10, 1, 133.9, 192.5, 5000, 6000, 16, 0, 0, 'normal', '{"hunt":{"sites":[2,6,12],"prob":{"any":{"6":0.037037037037037,"12":0.028571428571429},"same":{"6":0.25,"12":0.33333333333333}}},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[8]}', NULL, NULL, 1788143395110, NULL),
(78, '皮特兰猪', 2, 4, '特征是黑白不规则的斑驳图案。身体的脂肪薄，肌肉量多。禁不住压力的堆积会猝死。', 4, 11, 1, 123.9, 171.9, 1000, 1500, 8, 0, 0, 'normal', '{"hunt":{"sites":[3],"prob":{"any":{"3":0.014084507042254},"same":{"3":0.1}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(79, '威尔夏猪', 4, 5, '原产于威尔士，稀有猪。适合作腊肉。在意被说成梨形体型。', 5, 15, 1, 127.9, 187.3, 5000, 6000, 10, 0, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,5,12],"prob":{"any":{"5":0.018867924528302,"12":0.028571428571429},"same":{"5":0.1,"12":0.125}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(80, '牛津/珊迪黑猪', 4, 3, '原产英国。抗日晒能力强的户外派的猪。体验了2次濒临灭绝危机的波澜万丈的猪。', 3, 15, 1, 127.9, 163.1, 4000, 5000, 10, 1, 0, 'normal', '{"hunt":{"sites":[2,6,12],"prob":{"any":{"6":0.037037037037037,"12":0.028571428571429},"same":{"6":0.16666666666667,"12":0.2}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[2]}', NULL, NULL, 1788143395110, NULL),
(81, '嬉皮猪', 2, 1, '与外貌相反的懂礼貌，尊敬主人。/被卖掉的时候非常痛苦。', 1, 17, 1, 123.9, 171.9, 1000, 2000, 8, 0, 0, 'normal', '{"hunt":{"sites":[2,3,7],"prob":{"any":{"3":0.014084507042254,"7":0.041666666666667},"same":{"3":0.047619047619048,"7":0.076923076923077}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(82, '机器猪', 2, 2, '好像想成为超越众猪的存在。/制作出了喂食机器。', 2, 21, 1, 123.9, 173.3, 800, 1000, 10, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,2,3,13],"prob":{"any":{"3":0.014084507042254,"13":0.052631578947368},"same":{"3":0.066666666666667,"13":0.33333333333333}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(83, '奥克兰岛猪', 4, 3, '原本是外来种。明明是被人类放逐的，但是破坏了岛的生态结果成为被谴责的对象。', 3, 16, 1, 127.9, 199.5, 3000, 3500, 24, 1, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,5,16],"prob":{"any":{"5":0.018867924528302,"16":0.2},"same":{"5":0.083333333333333,"16":0.25}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(84, '服部忍者猪', 2, 1, '不仅作为忍者被卖出，甚至被刊登在图鉴上。感叹著这是一族的耻辱。', 1, 18, 1, 123.9, 154.6, 2000, 3000, 12, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,2,4,7],"prob":{"any":{"4":0.052631578947368,"7":0.041666666666667},"same":{"4":0.33333333333333,"7":0.076923076923077}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[2]}', NULL, NULL, 1788143395110, NULL),
(85, '海伦福特猪', 3, 3, '有相同名字的牛。特别想要拥有自己独一无二的名字。', 3, 17, 1, 123.9, 173.9, 3000, 4500, 12, 0, 0, 'normal', '{"hunt":{"sites":[2,4,6,13,14],"prob":{"any":{"4":0.052631578947368,"6":0.037037037037037,"13":0.052631578947368,"14":0.066666666666667},"same":{"4":0.16666666666667,"6":0.16666666666667,"13":0.14285714285714,"14":0.125}}},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[1,4]}', NULL, NULL, 1788143395110, NULL),
(86, '乔克猪', 5, 2, '从美国来到西班牙。从古至今外形就几乎没有变化。在自然界最开始自由行走生活的猪。', 2, 22, 1, 137, 217.2, 6000, 7500, 36, 1, 0, 'normal', '{"hunt":{"sites":[5],"prob":{"any":{"5":0.018867924528302},"same":{"5":0.052631578947368}}},"specialFeeding":true}', '{"interval":0,"times":10,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(87, '奥萨波岛猪', 4, 3, '据西班牙的探险家所说，是被放逐到岛上的猪的子孙。没有食物的时候，能积蓄身体脂肪，如今不必担心食物。', 3, 18, 1, 132.4, 199.5, 5000, 6500, 24, 1, 0, 'normal', '{"hunt":{"sites":[5],"prob":{"any":{"5":0.018867924528302},"same":{"5":0.083333333333333}}},"specialFeeding":true}', '{"interval":1,"times":6,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(88, '红华特猪', 4, 3, '特征是红色的身体和脖子下方悬著2块垂肉。成长快，适合用作放牧。抗病能力强的强壮猪。', 3, 19, 1, 130.6, 189.1, 3500, 4500, 12, 1, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,5,14],"prob":{"any":{"5":0.018867924528302,"14":0.066666666666667},"same":{"5":0.083333333333333,"14":0.125}}},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(89, '安全猪', 1, 3, '屋里屋外，为了安全，一直拿着安全帽不放手。/但是，是做工程时会偷工减料的类型。', 3, 20, 1, 123.9, 161.8, 700, 1000, 6, 0, 0, 'normal', '{"shop":[0,0,0.034848484848485],"hunt":{"sites":[1,2,3,7],"prob":{"any":{"3":0.014084507042254,"7":0.041666666666667},"same":{"3":0.1,"7":0.2}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(90, '彼得潘猪', 2, 1, '不想长大！但是时间是残酷的，变成成年猪之后，就被卖掉了。', 1, 19, 1, 123.9, 178.8, 1000, 1500, 18, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,2,3,11],"prob":{"any":{"3":0.014084507042254,"11":0.035714285714286},"same":{"3":0.047619047619048,"11":0.16666666666667}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(91, '鼻血猪', 1, 4, '因为马上会流鼻血，所以为了温柔对待鼻子，用很柔软的纸巾擦鼻子。基本上纸巾的开销很大。', 4, 12, 1, 123.9, 161.8, 600, 800, 6, 0, 0, 'normal', '{"shop":[0,0,0.034848484848485],"hunt":{"sites":[1,2,3,15],"prob":{"any":{"3":0.014084507042254,"15":0.11111111111111},"same":{"3":0.1,"15":0.5}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(92, '牛顿猪', 2, 3, '由于偶然落下的苹果，发现了万物不能违抗重力和食欲的物理学家和美食天才。', 3, 21, 1, 127.5, 174.6, 1500, 2000, 12, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,2,3,11],"prob":{"any":{"3":0.014084507042254,"11":0.035714285714286},"same":{"3":0.1,"11":0.33333333333333}}},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(93, '节食猪', 1, 5, '不能控制食欲，一不小心吃太多，“是猪真好啊……”这样想着就放弃了减肥。', 5, 16, 1, 126.6, 163, 500, 1000, 8, 0, 0, 'normal', '{"hunt":{"sites":[2,3,15],"prob":{"any":{"3":0.014084507042254,"15":0.11111111111111},"same":{"3":0.066666666666667,"15":0.33333333333333}}},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(94, '舒贝尔猪', 3, 1, '非常尊敬贝多芬和莫札特的作曲猪。作曲和吃东西都很早。', 1, 20, 1, 125.7, 187, 2000, 3500, 16, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,2,3,5,11,12],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"11":0.035714285714286,"12":0.028571428571429},"same":{"3":0.047619047619048,"5":0.14285714285714,"11":0.16666666666667,"12":0.25}}},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(95, '西藏猪', 4, 2, '在高高的山上也能存活。登山之类的很擅长。小猪的时候就很好吃，加工肉是琵琶肉，很有名。', 2, 23, 1, 127.9, 190.8, 3000, 4000, 14, 1, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,5,10],"prob":{"any":{"5":0.018867924528302,"10":0.090909090909091},"same":{"5":0.052631578947368,"10":0.2}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(96, '北鼻猪', 3, 1, '有分离的哥哥。天生乐观，刚强。衷心祈祷著哥哥能回来。', 1, 21, 1, 125.7, 163.7, 2500, 3500, 18, 0, 0, 'normal', '{"hunt":{"sites":[2,4,6,7,8],"prob":{"any":{"4":0.052631578947368,"6":0.037037037037037,"7":0.041666666666667,"8":0.0625},"same":{"4":0.33333333333333,"6":0.33333333333333,"7":0.076923076923077,"8":0.33333333333333}}},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[3]}', NULL, NULL, 1788143395110, NULL),
(97, '北海猪', 4, 5, '对北海道的恋爱名胜很了解。梦想成为北海道的旅游大使，并找到伴侣。', 5, 17, 1, 128.4, 176.6, 4000, 4500, 10, 0, 0, 'normal', '{"hunt":{"sites":[8],"prob":{"any":{"8":0.0625},"same":{"8":0.2}}},"specialFeeding":true}', '{"interval":1,"times":1,"picky":[4]}', NULL, NULL, 1788143395110, NULL),
(98, '祭典猪', 4, 4, '节日临近，打算逃跑去参加但是失败。希望能在猪猪小屋内举办祭典。', 4, 13, 1, 129.7, 189.1, 3500, 4000, 12, 0, 0, 'normal', '{"hunt":{"sites":[8],"prob":{"any":{"8":0.0625},"same":{"8":0.33333333333333}}},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(99, '福田猪', 2, 1, '容易迷恋异性，结果经常因爱受伤。/口齿伶俐，试图说服场主不要卖掉自己。', 1, 22, 1, 123.9, 171.9, 800, 1000, 8, 0, 0, 'normal', '{"hunt":{"sites":[2,3,7],"prob":{"any":{"3":0.014084507042254,"7":0.041666666666667},"same":{"3":0.047619047619048,"7":0.076923076923077}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(100, '猪川广重', 2, 1, '梦见了在东海道的风景中驰骋。因为不擅长画画，所以想练习。', 1, 26, 1, 123.9, 171.9, 1500, 2000, 8, 1, 0, 'normal', '{"hunt":{"sites":[7],"prob":{"any":{"7":0.041666666666667},"same":{"7":0.076923076923077}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL);

INSERT INTO pigs (
  p_no, name, rare, color, description,
  atlas_type, atlas_index, atlas_visible,
  weight_small, weight_big,
  rent, price, lifespan, graze, special, status,
  acquisition, feeding, breeding_guide, hints, updated_at, updated_by
) VALUES
(101, '捕蚊猪', 2, 5, '自称是没有抓不到的蚊子，在夏天是猪猪小屋的英雄。', 5, 18, 1, 123.9, 173.3, 800, 1000, 10, 0, 0, 'normal', '{"hunt":{"sites":[3],"prob":{"any":{"3":0.014084507042254},"same":{"3":0.066666666666667}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(102, '河豚', 2, 2, '像河豚那样美丽的外表，但是没有毒，可以放心食用。', 2, 24, 1, 123.9, 174.6, 800, 1000, 12, 0, 0, 'normal', '{"hunt":{"sites":[3],"prob":{"any":{"3":0.014084507042254},"same":{"3":0.066666666666667}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(103, '德岛猪', 2, 1, '总是在猪猪小屋里开心地跳舞。周围的小猪也受到影响，节日时会在猪猪小屋开舞会。来自日本德岛。', 1, 27, 1, 123.9, 173.3, 1000, 1500, 10, 0, 0, 'normal', '{"hunt":{"sites":[7],"prob":{"any":{"7":0.041666666666667},"same":{"7":0.076923076923077}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(104, '西乡猪', 3, 3, '没有实现和爱犬一起去散步的梦想。“现在已经很好啦”怀着这样的想法被卖掉了。', 3, 22, 1, 126.6, 161.3, 2500, 3500, 12, 0, 0, 'normal', '{"hunt":{"sites":[6],"prob":{"any":{"6":0.037037037037037},"same":{"6":0.16666666666667}}},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[3]}', NULL, NULL, 1788143395110, NULL),
(105, '卜沙猪', 2, 3, '不知道是否有驱邪效果。/因为脸很可怕，所以小孩子们确实是会避开它的。', 3, 23, 1, 123.9, 153.2, 800, 1000, 8, 0, 0, 'normal', '{"hunt":{"sites":[4],"prob":{"any":{"4":0.052631578947368},"same":{"4":0.16666666666667}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[3]}', NULL, NULL, 1788143395110, NULL),
(106, '猪猪', 4, 1, '身体上写着让财运提高的招财进宝的文字。/想被卖到礼品店。', 1, 28, 1, 127.9, 190.8, 3500, 4000, 14, 0, 0, 'normal', '{"hunt":{"sites":[10],"prob":{"any":{"10":0.090909090909091},"same":{"10":0.5}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(107, '猪尸', 2, 5, '正在成为僵尸的猪。不会特别袭击别人。脸前贴著的符咒好象封住了暴食。', 5, 25, 1, 123.9, 171.9, 1000, 1500, 8, 0, 0, 'normal', '{"hunt":{"sites":[9],"prob":{"any":{"9":0.083333333333333},"same":{"9":0.25}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(108, '熊猫猪', 3, 5, '因为模仿熊猫而成为受欢迎的猪。/而作为猪的尊严又在哪里。', 5, 19, 1, 123.9, 182.3, 1500, 2500, 10, 0, 0, 'normal', '{"hunt":{"sites":[5],"prob":{"any":{"5":0.018867924528302},"same":{"5":0.1}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(109, '头巾猪', 2, 3, '因为宗教不同，猪对于被忌讳的事也感到有些难办。/被头巾缠着的其实是耳朵。', 3, 29, 1, 125.7, 164.7, 1500, 2000, 10, 0, 0, 'normal', '{"hunt":{"sites":[9],"prob":{"any":{"9":0.083333333333333},"same":{"9":1}}},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[4,5]}', NULL, NULL, 1788143395110, NULL),
(110, '吴哥窟猪', 4, 3, '擅长柬埔寨宫廷舞蹈的阿普撒拉斯舞。想组成一个舞蹈队。', 3, 30, 1, 131.1, 186.1, 4000, 5000, 24, 0, 0, 'normal', '{"hunt":{"sites":[10],"prob":{"any":{"10":0.090909090909091},"same":{"10":0.5}}},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[4]}', NULL, NULL, 1788143395110, NULL),
(111, '贝多芬猪', 3, 1, '猪界的天才作曲猪。/对绝望的事情失去了嗅觉。/被卖出时的背景音乐是“命运”。', 1, 23, 1, 123.9, 180.7, 1500, 2000, 8, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,2,3,5,11,12],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"11":0.035714285714286,"12":0.028571428571429},"same":{"3":0.047619047619048,"5":0.14285714285714,"11":0.16666666666667,"12":0.25}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(112, '真实之猪', 4, 2, '据说不诚实的猪触摸它的话，会被咬住。实际上是因为误认为是饲料才咬住的而已。', 2, 25, 1, 130.6, 199.5, 3500, 4500, 24, 0, 0, 'normal', '{"hunt":{"sites":[2,5,12],"prob":{"any":{"5":0.018867924528302,"12":0.028571428571429},"same":{"5":0.052631578947368,"12":0.066666666666667}}},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(113, '拉丁猪', 3, 3, '擅长用热情丰富的表达力来表演舞蹈的猪，最终要被阉割。/想去发源地西班牙。', 3, 24, 1, 125.7, 187, 1000, 2000, 16, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,2,3,5,11,12],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"11":0.035714285714286,"12":0.028571428571429},"same":{"3":0.1,"5":0.083333333333333,"11":0.33333333333333,"12":0.2}}},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(114, '拿破仑猪', 4, 1, '在猪猪小屋没有成功发起革命，留下了“在我的辞典里没有这样的字”这样的意味深长的话，就被卖出了。', 1, 29, 1, 123.9, 168.2, 5000, 6000, 24, 0, 0, 'normal', '{"hunt":{"sites":[12],"prob":{"any":{"12":0.028571428571429},"same":{"12":0.25}}},"specialFeeding":true}', '{"interval":2,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(115, '伦敦猪', 2, 1, '侍奉王室的大兵猪。不能直立不动，缺乏冷静。经常强势的宣称著自己的时代快来了。', 1, 30, 1, 123.9, 177.4, 800, 1000, 16, 0, 0, 'normal', '{"hunt":{"sites":[11],"prob":{"any":{"11":0.035714285714286},"same":{"11":0.16666666666667}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(116, '红龙猪', 5, 4, '憧憬红龙的猪。经过各式各样的改造之后，渐渐接近龙的身姿，不过应该并不是中二病。', 4, 14, 1, 133.4, 213.3, 6500, 7500, 32, 0, 0, 'normal', '{"hunt":{"sites":[12],"prob":{"any":{"12":0.028571428571429},"same":{"12":0.33333333333333}}},"specialFeeding":true}', '{"interval":0,"times":6,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(117, '妖精猪', 2, 3, '爱尔兰的妖精猪。/在安睡的猪猪小屋里，每天夜里偶尔发出制造鞋子的声音…。', 3, 25, 1, 123.9, 170.5, 700, 1000, 6, 0, 0, 'normal', '{"hunt":{"sites":[2,3,11],"prob":{"any":{"3":0.014084507042254,"11":0.035714285714286},"same":{"3":0.1,"11":0.33333333333333}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(118, '苏格兰猪', 2, 4, '裙子的传统服装是雄性的服装，但是最近雌性也穿起来了。/不吹风笛。', 4, 15, 1, 123.9, 171.9, 800, 1000, 8, 0, 0, 'normal', '{"hunt":{"sites":[11],"prob":{"any":{"11":0.035714285714286},"same":{"11":0.14285714285714}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(119, '自由大猪', 4, 3, '小猪时期是茶色，长大之后变成绿色。火炬与标牌下落不明。如果找到了，请通知我一下。', 3, 32, 1, 132.4, 206.4, 4000, 5000, 32, 0, 0, 'normal', '{"hunt":{"sites":[14],"prob":{"any":{"14":0.066666666666667},"same":{"14":0.125}}},"specialFeeding":true}', '{"interval":1,"times":6,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(120, '橄榄猪', 2, 3, '不输野猪的擒抱和后腿的力量，完全压制住对手。', 3, 26, 1, 126.6, 173.3, 800, 1500, 10, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,2,3,13],"prob":{"any":{"3":0.014084507042254,"13":0.052631578947368},"same":{"3":0.1,"13":0.14285714285714}}},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(121, '印第安猪', 4, 3, '羽毛是勋章，标识著勇敢的战士身份。胸中怀着部族的骄傲等待着出货。', 3, 33, 1, 129.7, 182, 4500, 5000, 18, 0, 0, 'normal', '{"hunt":{"sites":[14],"prob":{"any":{"14":0.066666666666667},"same":{"14":0.125}}},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[1,4]}', NULL, NULL, 1788143395110, NULL),
(122, '牛仔猪', 2, 3, '虽然不能完成枪的射击，但是如果是比谁吃得快就很擅长了。抱怨说卡车不是了不起的马车。', 3, 34, 1, 123.9, 174.6, 800, 1000, 12, 0, 0, 'normal', '{"hunt":{"sites":[13],"prob":{"any":{"13":0.052631578947368},"same":{"13":0.14285714285714}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(123, '名流猪', 4, 1, '因为是名流，所以对美和吃饭很注重的高智慧猪。梦想着走出猪猪小屋，去到好莱坞。', 1, 24, 1, 134.9, 187.2, 4500, 5000, 16, 0, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,2,6,14],"prob":{"any":{"6":0.037037037037037,"14":0.066666666666667},"same":{"6":0.33333333333333,"14":0.33333333333333}}},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[7]}', NULL, NULL, 1788143395110, NULL),
(124, '休斯顿猪', 2, 1, '接受了特别训练的猪。虽然心里期待着现在是去宇宙旅游的时候了吧，但是命运已经定了。', 1, 32, 1, 123.9, 169.1, 800, 1000, 4, 0, 0, 'normal', '{"hunt":{"sites":[13],"prob":{"any":{"13":0.052631578947368},"same":{"13":0.16666666666667}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(125, '美国/龙虾猪', 2, 1, '海产和陆产的结合。/不知道为什么会扛着龙虾。', 1, 25, 1, 123.9, 169.1, 600, 1000, 4, 0, 0, 'normal', '{"hunt":{"sites":[2,3,13],"prob":{"any":{"3":0.014084507042254,"13":0.052631578947368},"same":{"3":0.047619047619048,"13":0.16666666666667}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(126, '卷发猪', 2, 3, '经常在阳光下兴致勃勃，时髦的猪。', 3, 27, 1, 125.7, 164.7, 800, 1000, 10, 0, 0, 'normal', '{"hunt":{"sites":[4],"prob":{"any":{"4":0.052631578947368},"same":{"4":0.16666666666667}}},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[2,5]}', NULL, NULL, 1788143395110, NULL),
(127, '狩猎猪', 4, 3, '飞镖是特技。射的话偶尔会射中自己。/经常忘记自己也是被狩猎的一方。', 3, 35, 1, 128.8, 192.5, 3500, 4500, 16, 0, 0, 'normal', '{"hunt":{"sites":[16],"prob":{"any":{"16":0.2},"same":{"16":0.25}}},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(128, '羊猪', 2, 5, '偶尔也会和绵羊搞错被卖掉。因为毛是假的，所以卖不了那么高价钱。', 5, 28, 1, 125.7, 154.6, 1000, 1500, 12, 1, 0, 'normal', '{"hunt":{"sites":[15],"prob":{"any":{"15":0.11111111111111},"same":{"15":0.33333333333333}}},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[2]}', NULL, NULL, 1788143395110, NULL),
(129, '拉口木猪', 4, 5, '在加拿大原产地很有人气，现在面临着濒临灭绝的危机。骨头很结实。', 5, 20, 1, 123.9, 185.6, 4500, 5000, 8, 0, 0, 'normal', '{"hunt":{"sites":[2,5,14],"prob":{"any":{"5":0.018867924528302,"14":0.066666666666667},"same":{"5":0.1,"14":0.5}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(130, '西班牙短鼻猪', 3, 2, '原产西班牙。面临着濒临灭绝的危机。在城堡里用西班牙语说是“短鼻子”。其实这才是自卑感。', 2, 26, 1, 123.9, 183.8, 1500, 2500, 12, 1, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,2,3,5,11,12],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"11":0.035714285714286,"12":0.028571428571429},"same":{"3":0.066666666666667,"5":0.052631578947368,"11":0.16666666666667,"12":0.066666666666667}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(131, '坎伯兰猪', 5, 5, '借助科学家的力量，灭绝了的猪再次奇迹的复活。以前作为香肠和火腿等对当地做了贡献的猪。', 5, 21, 1, 133.4, 221, 8500, 9000, 40, 0, 0, 'normal', '{"shop":[0.003030303030303,0,0],"hunt":{"sites":[1,2,5,12],"prob":{"any":{"5":0.018867924528302,"12":0.028571428571429},"same":{"5":0.1,"12":0.125}}},"specialFeeding":true}', '{"interval":1,"times":6,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(132, '米尔格兰德猪', 2, 5, '乌克兰原产的猪油型猪。身体结实，发育早。室外和严酷的环境也可以生存。', 5, 22, 1, 123.9, 152.4, 1000, 1800, 6, 1, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,2,4,11],"prob":{"any":{"4":0.052631578947368,"11":0.035714285714286},"same":{"4":0.25,"11":0.16666666666667}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[2]}', NULL, NULL, 1788143395110, NULL),
(133, '爱丽榭/科雷萨', 4, 3, '爱尔兰的古代猪。追寻始祖的话，好像是塔姆沃思猪的祖先。/好奇心旺盛的猪。', 3, 28, 1, 129.7, 199.5, 4000, 5500, 24, 0, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,5,12],"prob":{"any":{"5":0.018867924528302,"12":0.028571428571429},"same":{"5":0.083333333333333,"12":0.2}}},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(134, '林肯榭/凯里寇特', 5, 5, '英国的旧品种。已经濒临了，但是在养猪场又奇迹的复活。毛很深，和卷毛猪相似，但是不同的品种。', 5, 23, 1, 131.6, 171.4, 8000, 10000, 24, 0, 0, 'normal', '{"shop":[0.003030303030303,0,0],"hunt":{"sites":[1,5,12],"prob":{"any":{"5":0.018867924528302,"12":0.028571428571429},"same":{"5":0.1,"12":0.125}}},"specialFeeding":true}', '{"interval":2,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(135, '奥璐德/英国', 3, 2, '英格兰自古就有的猪种。颜色丰富，耳朵前倾，背上长满鬃毛。', 2, 27, 1, 124.8, 188.5, 1500, 2000, 18, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,3,5,11,12],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"11":0.035714285714286,"12":0.028571428571429},"same":{"3":0.066666666666667,"5":0.052631578947368,"11":0.16666666666667,"12":0.066666666666667}}},"specialFeeding":true}', '{"interval":1,"times":2,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(136, '拿坡里猪', 4, 2, '意大利原产的古代猪。因为脸上布满皱纹，下巴笨拙地垂著，所以想去美容。', 2, 28, 1, 131.5, 199.5, 4000, 4500, 24, 0, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,5,12],"prob":{"any":{"5":0.018867924528302,"12":0.028571428571429},"same":{"5":0.052631578947368,"12":0.066666666666667}}},"specialFeeding":true}', '{"interval":1,"times":5,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(137, '埃塞克斯猪', 3, 2, '被公认为很结实。黑色底色，肩上有白色带状。经常被误认为汉普郡猪。', 2, 29, 1, 125.7, 193.2, 1500, 2000, 24, 1, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,3,5,11,12],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"11":0.035714285714286,"12":0.028571428571429},"same":{"3":0.066666666666667,"5":0.052631578947368,"11":0.16666666666667,"12":0.066666666666667}}},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(138, '卫塞克斯猪/鞍背', 4, 2, '和汉普郡猪是亲戚。在英国已经灭绝了，但在其他的国家还残留有少数。和埃塞克斯郡猪经常被搞错。', 2, 30, 1, 131.1, 164.3, 4500, 5500, 32, 1, 0, 'normal', '{"hunt":{"sites":[6],"prob":{"any":{"6":0.037037037037037},"same":{"6":0.11111111111111}}},"specialFeeding":true}', '{"interval":2,"times":3,"picky":[6]}', NULL, NULL, 1788143395110, NULL),
(139, '荣昌猪', 2, 5, '眼睛的四周是黑毛，所以感觉含有熊猫的血统。', 5, 24, 1, 125.7, 146, 1300, 1600, 24, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,4,9],"prob":{"any":{"4":0.052631578947368,"9":0.083333333333333},"same":{"4":0.25,"9":0.25}}},"specialFeeding":true}', '{"interval":2,"times":3,"picky":[2,3]}', NULL, NULL, 1788143395110, NULL),
(140, '桃园猪', 3, 2, '台湾原产猪。大大下垂的耳朵，脸和重量的身体有很多很深的皱纹。', 2, 31, 1, 123.9, 187, 1500, 2000, 16, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,3,5,7,8],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"7":0.041666666666667,"8":0.0625},"same":{"3":0.066666666666667,"5":0.052631578947368,"7":1,"8":0.33333333333333}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(141, '中国杂种猪', 1, 2, '和中国产的猪交配产生的猪。想要有中国的味道，所以戴着帽子。', 2, 32, 1, 123.9, 165.4, 700, 1000, 12, 0, 0, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(142, '社畜猪', 3, 1, '为了成为性价比高的猪肉，什么都吃，但是散发着粗粮的味道，讽刺的命运。', 6, 3, 1, 123.9, 199.5, 2000, 3000, 32, 0, 0, 'normal', '{"hunt":{"sites":[2]},"fail":[143],"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(143, '精英猪', 4, 1, '高档次，高价格，高体重。具备3高的好条件。被期待做成高级饭店的完美汤汁。', 6, 4, 1, 175, 206.4, 4000, 5000, 32, 0, 0, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":10,"picky":[]}', '{"requirements":"成猪前体重限制 ≥128.0 kg","tips":null}', NULL, 1788143395110, NULL),
(144, '堂吉诃德', 4, 1, '总是认为自己是神选之骑士要保护养猪场的正义。有点顽固，不听劝告。', 1, 31, 1, 132.5, 196, 3000, 3500, 24, 1, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,2,6,12],"prob":{"any":{"6":0.037037037037037,"12":0.028571428571429},"same":{"6":0.33333333333333,"12":0.25}}},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[4]}', NULL, NULL, 1788143395110, NULL),
(145, '埃及猪', 5, 5, '来自埃及的黄金色的猪。喜欢在地上写一些神秘的记号，没有人能解读。', 5, 26, 1, 135.9, 212.4, 9000, 10000, 32, 0, 0, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":5,"picky":[7]}', NULL, NULL, 1788143395110, NULL),
(146, '萝莉猪', 3, 4, '怀抱梦想，总是身着洛丽塔风格的猪。因为怕自己最喜欢的洋服被弄脏所以总是想离开养猪场。', 4, 16, 1, 125.7, 186.1, 2500, 3000, 12, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,2,3,5,7,8],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"7":0.041666666666667,"8":0.0625},"same":{"3":0.1,"5":0.33333333333333,"7":1,"8":0.33333333333333}}},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(147, '冲浪猪', 3, 3, '不只是会冲浪，总是引领时尚潮流的猪猪。最喜欢的冲浪板是特别订制的。', 3, 31, 1, 123.9, 186.1, 2000, 2500, 12, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,2,3,5,13,14],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"13":0.052631578947368,"14":0.066666666666667},"same":{"3":0.1,"5":0.083333333333333,"13":0.14285714285714,"14":0.125}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(148, '水桶猪', 1, 5, '喜欢玩水的性格，所以总是湿湿的。听说其实是因为它很爱哭，所以要用水，隐藏眼泪。', 5, 27, 1, 123.9, 173.2, 500, 800, 6, 0, 0, 'normal', '{"shop":[0,0,0.034848484848485],"hunt":{"sites":[1,2,3,9],"prob":{"any":{"3":0.014084507042254,"9":0.083333333333333},"same":{"3":0.066666666666667,"9":0.25}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(149, '竹猪', 2, 4, '因为憧憬东南亚的搬运风格，自己进到了竹笼里。相比卡车，更希望被摩托车带走。', 4, 17, 1, 123.9, 178.9, 800, 1000, 8, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,3,9],"prob":{"any":{"3":0.014084507042254,"9":0.083333333333333},"same":{"3":0.1,"9":1}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(150, '重金属', 3, 2, '喜欢听很吵的音乐。叫声也很吵。帮它卸妆之后好像就不会这么嚣张了。', 2, 34, 1, 125.7, 189.4, 2500, 3000, 16, 0, 0, 'normal', '{"hunt":{"sites":[2,3,5,11,12],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"11":0.035714285714286,"12":0.028571428571429},"same":{"3":0.066666666666667,"5":0.052631578947368,"11":0.16666666666667,"12":0.066666666666667}}},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(151, '鹿猪', 5, 1, '特色是鼻子边上突出的向上的獠牙。虽然濒临绝种了但是因为不是猪，所以肉也不是很好卖。', 6, 7, 1, 128.9, 169.8, 3000, 9000, 32, 0, 0, 'normal', '{"hunt":{"sites":[10],"prob":{"any":{"10":0.090909090909091},"same":{"10":1}}},"specialFeeding":true}', '{"interval":2,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(152, '哥特猪', 3, 5, '非常在意着装和时尚潮流的猪。形象很特别，喜欢开茶会。', 5, 29, 1, 125.7, 186.1, 2500, 3000, 12, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,2,3,5,7,8],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"7":0.041666666666667,"8":0.0625},"same":{"3":0.066666666666667,"5":0.1,"7":0.25,"8":0.2}}},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(153, '甜点猪', 3, 4, '因为太喜欢吃餐后甜点所以每天会进食很多次。为了随时能吃到，身上会一直带着甜点。', 4, 18, 1, 128.4, 186.1, 1500, 2000, 24, 0, 0, 'normal', '{"hunt":{"sites":[5],"prob":{"any":{"5":0.018867924528302},"same":{"5":0.33333333333333}}},"specialFeeding":true}', '{"interval":0,"times":6,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(154, '宝贝猪', 2, 1, '返老还童变成小宝宝的成年猪。可能是太想成为好猪了，压力太大导致的。', 1, 33, 1, 125.7, 173.5, 1300, 1800, 18, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,2,3,7],"prob":{"any":{"3":0.014084507042254,"7":0.041666666666667},"same":{"3":0.047619047619048,"7":0.076923076923077}}},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(155, '怪盗猪', 4, 2, '没人见过真身，神出鬼没的谜之怪盗绅士。对贵族持有的宝贝不感兴趣。平时好像会以另外的身份出现。', 2, 35, 1, 134.9, 198.1, 4000, 5000, 16, 1, 0, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":5,"picky":[7,8]}', NULL, NULL, 1788143395110, NULL),
(156, '特罗普利猪', 5, 5, '可以抵抗气候变化和疾病的强壮的猪。克罗地亚最老的猪种，有灭绝的危险。', 5, 30, 1, 138.9, 202.5, 6500, 7500, 32, 1, 0, 'normal', '{"shop":[0.003030303030303,0,0],"hunt":{"sites":[1,6,12],"prob":{"any":{"6":0.037037037037037,"12":0.028571428571429},"same":{"6":0.2,"12":0.125}}},"specialFeeding":true}', '{"interval":0,"times":8,"picky":[4,6]}', NULL, NULL, 1788143395110, NULL),
(157, '缪福特猪', 4, 2, '名字像是啤酒的时尚的猪。肉质适合做成火腿。', 2, 36, 1, 130.6, 186.5, 4500, 5500, 18, 1, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,2,5,14],"prob":{"any":{"5":0.018867924528302,"14":0.066666666666667},"same":{"5":0.052631578947368,"14":0.5}}},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(158, '阿拉帕瓦猪', 4, 3, '19世纪被捕鲸渔夫和农民带到岛上的猪。野生化后虽然戒心很重但是不会随意攻击人。', 3, 36, 1, 133.3, 197.1, 5000, 6000, 32, 1, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,2,5,16],"prob":{"any":{"5":0.018867924528302,"16":0.2},"same":{"5":0.083333333333333,"16":0.25}}},"specialFeeding":true}', '{"interval":0,"times":7,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(159, '福尔摩猪', 3, 1, '经常调查出轨和饲料冒领，什么事件都能解决的名侦探。最近想要个助手。', 1, 34, 1, 126.6, 183.4, 2500, 3000, 20, 0, 0, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(160, '太空猪', 2, 1, '想要和外星人交流所以会被UFO带走的猪。被带走的时候外星人会给你pt。', 1, 35, 1, 123.9, 168.6, 2000, 2500, 10, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,2,3,13],"prob":{"any":{"3":0.014084507042254,"13":0.052631578947368},"same":{"3":0.047619047619048,"13":0.16666666666667}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(161, '武士猪', 5, 1, '平民出身但是因为战功累累而成为大武将。快要一统猪猪小屋的时候被卖掉了。', 6, 8, 1, 132.5, 202.5, 8000, 9000, 32, 1, 0, 'normal', '{"shop":[0.003030303030303,0,0],"hunt":{"sites":[1]},"specialFeeding":true}', '{"interval":2,"times":5,"picky":[3,6]}', NULL, NULL, 1788143395110, NULL),
(162, '亚佳佳瓦野猪', 4, 1, '白天睡觉，傍晚开始活动的类型。还会吃蛇之类的奇怪生物。', 6, 9, 1, 129.7, 185, 4000, 5000, 16, 1, 0, 'normal', '{"hunt":{"sites":[5],"prob":{"any":{"5":0.018867924528302},"same":{"5":0.5}}},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', '{"requirements":"只有19:00:00-07:59:59(+1)可狩猎","tips":null}', NULL, 1788143395110, NULL),
(163, '纯种猪', 5, 1, '有着精英父母，所以继承了优秀的肉质。母猪之间很有人气，有非官方的粉丝群。', 6, 10, 1, 137.4, 206.1, 8500, 9500, 32, 1, 0, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":2,"times":6,"picky":[7]}', NULL, NULL, 1788143395110, NULL),
(164, '婚礼猪', 4, 1, '因为在放牧场见到了梦中情人而来到了小屋。如果没有见到它的话会去相亲吧？', 6, 11, 1, 132.4, 197.1, 3000, 4000, 32, 1, 0, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":2,"times":6,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(165, '新娘猪', 4, 1, '穿着心心念念的白无垢，美美地出货了。经常练习要怎么给父母告别。', 6, 12, 1, 132.4, 197.1, 3000, 4000, 32, 0, 0, 'normal', '{"hunt":{"sites":[2]},"fail":[164],"specialFeeding":true}', '{"interval":2,"times":6,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(166, '猪猪医生', 1, 1, '大多数的诊断是“睡觉就会好转的”很糟糕的医生。会收诊费，害怕注射器所以很讨厌预防针。', 1, 36, 1, 125.7, 159.6, 700, 800, 8, 0, 0, 'normal', '{"shop":[0,0,0.034848484848485],"hunt":{"sites":[1,2,3,7],"prob":{"any":{"3":0.014084507042254,"7":0.041666666666667},"same":{"3":0.047619047619048,"7":0.076923076923077}}},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(181, '可爱猪', 5, 1, '濒临绝种的日本原种猪。耐得住酷暑严寒和粗食。个性亲人。充满希望的可爱猪。', 2, 37, 1, 133.4, 180.2, 7500, 8000, 32, 1, 0, 'normal', '{"shop":[0.003030303030303,0,0],"hunt":{"sites":[1,6,8],"prob":{"any":{"6":0.037037037037037,"8":0.0625},"same":{"6":0.11111111111111,"8":0.33333333333333}}},"specialFeeding":true}', '{"interval":0,"times":6,"picky":[2,3]}', NULL, NULL, 1788143395110, NULL),
(197, '枫泾猪', 3, 2, '繁殖能力高不容易生病，随便喂也能养大。肉质多汁评价很高。属于中国太湖猪的一个类别。', 2, 38, 1, 128.6, 155.3, 1500, 2500, 24, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,2,3,5,9,10],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"9":0.083333333333333,"10":0.090909090909091},"same":{"3":0.066666666666667,"5":0.052631578947368,"9":0.2,"10":0.2}}},"specialFeeding":true}', '{"interval":2,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(198, '本特海姆黑猪', 5, 5, '德国品种，因为他柔软的霜降肉多汁又美味所以获得很高的评价。在1950年代就几乎灭绝，现在很罕见。', 5, 31, 1, 133.4, 180.2, 7500, 8500, 10, 1, 0, 'normal', '{"shop":[0.003030303030303,0,0],"hunt":{"sites":[1,5,12],"prob":{"any":{"5":0.018867924528302,"12":0.028571428571429},"same":{"5":0.1,"12":0.125}}},"specialFeeding":true}', '{"interval":1,"times":6,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(199, '美国几内亚猪', 4, 2, '他的名字来自于像几内亚牛一样娇小的样子。杂食性连蛇也吃，所以有小孩或家畜在也很安心。美国原产。', 2, 39, 1, 130.6, 180, 4500, 5500, 18, 1, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,5,14],"prob":{"any":{"5":0.018867924528302,"14":0.066666666666667},"same":{"5":0.052631578947368,"14":0.5}}},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(200, '那加本土猪', 3, 2, '印度东北原产。成长速度快照顾也不麻烦。大家也会叫他穿着白袜子的猪。', 2, 40, 1, 125.9, 167.7, 2500, 3500, 8, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,3,5,9,10],"prob":{"any":{"3":0.014084507042254,"5":0.018867924528302,"9":0.083333333333333,"10":0.090909090909091},"same":{"3":0.066666666666667,"5":0.052631578947368,"9":0.2,"10":0.2}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(201, '凯尔特猪', 4, 4, '在加利西亚地区的原始森林中饲养。虽然很健壮，对环境适应力强，但他们的数量却随着农民的减少而下降。', 4, 19, 1, 128.2, 178.6, 4000, 5000, 16, 1, 0, 'normal', '{"hunt":{"sites":[6],"prob":{"any":{"6":0.037037037037037},"same":{"6":0.25}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[6]}', NULL, NULL, 1788143395110, NULL),
(202, '意大利兰德莱斯猪', 2, 5, '饲养用于制作生火腿和意大利香肠的意大利大型品种。跟一般猪比脊椎骨较多，特征是身体很长。', 5, 32, 1, 124.9, 164.4, 1000, 2000, 10, 0, 0, 'normal', '{"hunt":{"sites":[3],"prob":{"any":{"3":0.014084507042254},"same":{"3":0.066666666666667}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(203, '昂格尔恩马鞍猪', 4, 2, '曾在1950年代的德国大量上市。适合户外饲养。近年来由于肉质的脂肪量多而不受喜爱而濒临绝种。', 2, 41, 1, 130.6, 177.3, 4000, 5000, 14, 1, 0, 'normal', '{"shop":[0.011538461538462,0.0025641025641026,0],"hunt":{"sites":[1,2,5,12],"prob":{"any":{"5":0.018867924528302,"12":0.028571428571429},"same":{"5":0.052631578947368,"12":0.066666666666667}}},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(204, '鲨鱼猪', 2, 2, '会神不知鬼不觉游到背后吓你一跳。为了去海边布置隐藏式镜头而上了出货卡车。', 2, 42, 1, 127.6, 165.5, 1500, 2000, 12, 0, 0, 'normal', '{"hunt":{"sites":[2,15],"prob":{"any":{"15":0.11111111111111},"same":{"15":1}}},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(205, '猪尾花魁', 5, 5, '有学识素养又有才艺，气质文雅，公猪们都会被他吸引。要出货这只猪还要考验场主的财力。', 5, 33, 1, 143.5, 223.1, 8500, 9000, 26, 0, 0, 'normal', '{"shop":[0.003030303030303,0,0],"hunt":{"sites":[1,2,6,8],"prob":{"any":{"6":0.037037037037037,"8":0.0625},"same":{"6":0.2,"8":0.2}}},"specialFeeding":true}', '{"interval":1,"times":8,"picky":[8]}', NULL, NULL, 1788143395110, NULL),
(206, '南丁格尔猪', 3, 5, '为了照顾生病或受伤的猪而来到这里。对于常出现病猪的养猪场场主很严厉。', 5, 34, 1, 126.2, 173.9, 3000, 3500, 18, 0, 0, 'normal', '{"shop":[0.026666666666667,0.0066666666666667,0.0026666666666667],"hunt":{"sites":[1,2,4,6,11,12],"prob":{"any":{"4":0.052631578947368,"6":0.037037037037037,"11":0.035714285714286,"12":0.028571428571429},"same":{"4":0.25,"6":0.2,"11":0.16666666666667,"12":0.125}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[5]}', NULL, NULL, 1788143395110, NULL),
(207, '织田信长猪', 4, 5, '拥有超凡魅力的猪，目标是统一养猪场天下。不过还没来得及平定猪猪小屋内的谋反就被出货了。', 5, 35, 1, 136.5, 211.8, 5500, 6000, 24, 1, 0, 'normal', '{"hunt":{"sites":[2,8],"prob":{"any":{"8":0.0625},"same":{"8":0.2}}},"specialFeeding":true}', '{"interval":0,"times":6,"picky":[7,8]}', NULL, NULL, 1788143395110, NULL),
(208, '泡芙猪', 1, 5, '偷吃场主的泡芙后就被深深吸引了。每天都在研究最终完美的泡芙食谱。', 5, 36, 1, 125.7, 157.8, 1000, 1500, 12, 0, 0, 'normal', '{"shop":[0,0,0.034848484848485],"hunt":{"sites":[1,2,3,11],"prob":{"any":{"3":0.014084507042254,"11":0.035714285714286},"same":{"3":0.066666666666667,"11":0.16666666666667}}},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(209, '番茄猪', 1, 4, '偶然听到猪和番茄很合得来，所以参考之后变成这样。他还不知道其实这是一道猪肉料理。', 4, 20, 1, 123.9, 148.2, 1000, 1500, 8, 0, 0, 'normal', '{"shop":[0,0,0.034848484848485],"hunt":{"sites":[1,2,4,11],"prob":{"any":{"4":0.052631578947368,"11":0.035714285714286},"same":{"4":0.5,"11":0.14285714285714}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[2]}', NULL, NULL, 1788143395110, NULL),
(210, '厨师猪', 2, 4, '梦想是开一家专为猪而开的3星餐厅。用剩的饲料做出来的料理堪称极品美味，在猪猪间的评价很高。', 4, 21, 1, 124.9, 167.7, 2000, 2500, 16, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,2,3,11],"prob":{"any":{"3":0.014084507042254,"11":0.035714285714286},"same":{"3":0.1,"11":0.14285714285714}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(211, '郁金香猪', 1, 4, '想要去爱的告白时带着他说不定会成功。正在寻找白色或黄色的伙伴。', 4, 22, 1, 123.9, 155.8, 800, 1000, 8, 0, 0, 'normal', '{"shop":[0,0,0.034848484848485],"hunt":{"sites":[1,2,3,11],"prob":{"any":{"3":0.014084507042254,"11":0.035714285714286},"same":{"3":0.1,"11":0.14285714285714}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(212, '消防员猪', 2, 4, '有猪求救灭火会马上出动。最近因为不适切言论而出现的炎上批判变多，所以他常常去帮忙救火。', 4, 23, 1, 124.9, 165.5, 2000, 2500, 12, 0, 0, 'normal', '{"shop":[0,0.031944444444444,0.0069444444444444],"hunt":{"sites":[1,2,3,13],"prob":{"any":{"3":0.014084507042254,"13":0.052631578947368},"same":{"3":0.1,"13":1}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(213, '关羽猪', 4, 4, '效忠于刘备猪非常英勇的武将。对部下很好，但自尊心高所以有些猪也对他望之生畏。', 4, 24, 1, 132.4, 184.1, 5500, 6000, 24, 1, 0, 'normal', '{"hunt":{"sites":[2,10],"prob":{"any":{"10":0.090909090909091},"same":{"10":1}}},"specialFeeding":true}', '{"interval":0,"times":6,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(400, '埃及猪后', 5, 3, '拥有女王风采的绝世美猪。虽然对自己很有自信但是常常判断错误也有蠢萌的一面。', 7, 39, 1, 148.5, 209.1, NULL, 9000, 20, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":5,"picky":[4,7]}', NULL, NULL, 1788143395110, NULL),
(401, '猪三藏', 4, 5, '以去某个地方为目标有神秘使命的猪。擅长话术，猪猪都很尊敬他并成为他的伙伴。', 7, 40, 1, 128.8, 169.7, NULL, 7000, 18, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[1,2]}', NULL, NULL, 1788143395110, NULL),
(402, '歌剧猪影', 3, 1, '音乐才华洋溢的猪。传言据说被他看上的母猪叫声会变得美妙动听', 7, 41, 1, 126.6, 164, NULL, 6500, 14, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(403, '海贼猪胡子', 6, 3, '威震八方的传说中的海贼。若有猪猪违抗就会毫不客气地将对方变成烤猪。唯一不可逆的是被出货的命运。', 7, 52, 1, 128.5, 218.2, NULL, 10000, 30, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[]}', '{"requirements":"获得方式：交易所需提前兑换配方；红票消耗：10","tips":null}', '["父母都戴着很华丽的帽子","好像有遗传到父母的鲁莽","好像有遗传到当领导的才能","待在海上的时间好像比较多","似乎很擅长打斗"]', 1788143395110, NULL),
(404, '猪猪武士', 5, 1, '掌管这一带的奉行官员。很喜欢假扮成游手好闲的人去跟坏人接触，然后再暴露自己其实是官吏。', 7, 53, 1, 131.6, 212, NULL, 8500, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[1,7]}', NULL, NULL, 1788143395110, NULL),
(405, '圣猪贞德', 6, 1, '传说中的圣猪。有趣闻说道，因得到拯救养猪场的天启，便率领猪猪们向着出货目的地前进以拯救经营困难。', 7, 61, 1, 131.5, 204.8, NULL, 10000, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":5,"picky":[]}', '{"requirements":"获得方式：交易所需提前兑换配方；红票消耗：10","tips":null}', '["第一眼就看得出是士兵呢","好像传承了自我牺牲之精神","继承了坚固的装备呢","似乎已顿悟了命运","好像拥有坚强的信念"]', 1788143395110, NULL),
(406, '庆祝猪', 5, 1, '庆祝养猪场MIX周年纪念的猪。很开心有这么多人一起来经营养猪场。谢谢大家。', 7, 67, 1, 128.8, 196, NULL, 8500, 24, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":2,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(407, '猪贵妃', 6, 5, '曾经有场主太过醉心于她结果猪场经营失败。猪猪之间都在流传她是一只倾国的美猪。', 7, 68, 1, 135.8, 212.7, NULL, 10000, 24, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":5,"picky":[8]}', '{"requirements":"获得方式：交易所需提前兑换配方；红票消耗：10","tips":null}', '["好像要被俘虏了","散发一股中华风的香气","没有继承到财运UP吗","继承了美貌与魅力","继承了父母的樱桃小嘴"]', 1788143395110, NULL),
(409, '仙杜瑞猪', 5, 1, '虽然过着不幸的猪生但是在某个好的时段发生了奇迹，于是就坐上了前往舞会？的卡车。', 7, 72, 1, 128.9, 187.9, NULL, 8500, 6, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(410, '灰姑娘猪', 3, 1, '多么不幸啊。长大成猪一直相信着会发生奇迹，但似乎搞错了发生奇迹的时段。', 7, 73, 1, 128.9, 187.9, NULL, 3500, 6, 0, 1, 'normal', '{"hunt":{"sites":[2]},"fail":[409],"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(411, '猪猪・亚瑟', 6, 4, '众多传说的其中之一，他拔出了只有继承养猪场王位的猪才能拔出的剑。对部下很好却常常被背叛。', 7, 78, 1, 132.5, 196.5, NULL, 10000, 25, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":5,"picky":[]}', '{"requirements":"获得方式：交易所需提前兑换配方；红票消耗：10","tips":null}', '["国家象征和父(母)很像","遗传到父(母)的统治能力","像父(母)一样很有出息的样子","好像是从不列颠来的","似乎遗传到父母的勇猛"]', 1788143395110, NULL),
(412, '石川五右卫猪', 6, 6, '传说中的大盗，专门瞄准不好好养猪却挥霍金钱玩乐的场主。出货目的地有沸腾的大锅子在等他。', 7, 87, 1, 131, 212.4, NULL, 10000, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":5,"picky":[7]}', '{"requirements":"获得方式：交易所需提前兑换配方；红票消耗：10","tips":null}', '["好像有着大胆的个性","好像来自日本","死去时似乎很壮烈","遗传到父(母)的庶民人气","父母亲都隐藏真面目"]', 1788143395110, NULL),
(413, '梦游猪场的爱丽丝', 5, 4, '想要追栅栏另一边的兔子，但是身体太大了穿不过去。如果不要吃太多的话也许就能缩小了？', 7, 90, 1, 130.7, 190.6, NULL, 9000, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(414, '梦游猪场的爱丽丝(S)', 5, 4, '原本的我好像没这么小呢。再吃多一点就会长大了吧。猪猪如是说。', 7, 91, 1, 128.9, 176.6, NULL, 9000, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"fail":[413],"specialFeeding":true}', '{"interval":1,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(415, '疯帽猪', 4, 1, '常在茶会上唱奇奇怪怪的歌，出一些没有答案的谜语。是爱惹其他猪生气的天才。', 7, 92, 1, 127.9, 180, NULL, 5000, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(416, '白兔猪', 3, 5, '各种原因上常常被人追。在猪猪小屋内频繁发生的偷吃案中担任朗读罪状的角色。', 7, 93, 1, 125.9, 170.2, NULL, 3500, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL);

INSERT INTO pigs (
  p_no, name, rare, color, description,
  atlas_type, atlas_index, atlas_visible,
  weight_small, weight_big,
  rent, price, lifespan, graze, special, status,
  acquisition, feeding, breeding_guide, hints, updated_at, updated_by
) VALUES
(417, '所罗猪王', 6, 2, '传说它用指环之力控制恶魔来建造猪猪小屋。偷偷瞒着场主纳了700头母猪为妃。', 7, 98, 1, 129.4, 231.6, NULL, 10000, 27, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[7,8]}', '{"requirements":"获得方式：交易所需提前兑换配方；红票消耗：10","tips":null}', '["似乎会控制非凡人","父(母)和未来的妻子好像是同乡","好像从神那里得到某个东西","好像会成为智慧之王","父(母)和神的使者很像呢"]', 1788143395110, NULL),
(418, '拇指猪姑娘', 5, 1, '从花朵里诞生的小小猪。梦想与花之国的王子在一起所以一直等待着前来迎接的燕子，没想到来的却是卡车。', 7, 114, 1, 131.6, 190.6, NULL, 5000, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[2,6]}', NULL, NULL, 1788143395110, NULL),
(419, '礼帽猪', 5, 1, '为了庆祝养猪场周年纪念而来的马戏团团长。华丽的甩鞭让猛兽也驯服。', 7, 127, 1, 130.7, 179.1, NULL, 5500, 30, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[3]}', NULL, NULL, 1788143395110, NULL),
(420, '竹取猪', 5, 5, '她的美貌让好多猪来向她求婚，是一只很有人气的猪。出货时会有使者从月亮来迎接她回去。', 7, 128, 1, 135.8, 230.1, NULL, 9000, 32, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[8]}', NULL, NULL, 1788143395110, NULL),
(421, '猪诺丘', 5, 3, '好奇心旺盛，天真无邪地跟着做坏事最后总是尝到苦头。说谎的话鼻子会变长。', 7, 149, 1, 131.6, 192.1, NULL, 8500, 26, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[3,4]}', NULL, NULL, 1788143395110, NULL),
(422, '猪仙子', 4, 5, '美丽的妖精猪，对于做坏事的小猪会很严格地管教。施了魔法让好孩子可以长大成为优秀的成猪。', 7, 150, 1, 131.8, 198, NULL, 7000, 24, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[7]}', NULL, NULL, 1788143395110, NULL),
(423, '杰佩托猪爷爷', 3, 1, '捡了一个圆木头雕刻了一头小猪，没想到是头不受控的小猪，为了养大它似乎费了一番苦心。', 7, 151, 1, 126.8, 163.6, NULL, 3500, 20, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":2,"picky":[1,2]}', NULL, NULL, 1788143395110, NULL),
(424, '长发猪公主', 5, 5, '拥有一头美丽长金发。会用头发代替绳子招来野生猪猪进入小屋。有点不谙世事。', 7, 164, 1, 128.9, 172.6, NULL, 4500, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":1,"picky":[2]}', NULL, NULL, 1788143395110, NULL),
(425, '乐队猪', 5, 1, '在庆祝养猪场MIX4周年的游行里，出现在乐队里的猪。不管在什么地方，都会自然而然地边演奏边走路。', 7, 186, 1, 131.6, 187.6, NULL, 8000, 20, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(426, '睡美猪', 5, 1, '受到鼻子被纺织机的针刺到而陷入沉睡的诅咒。偶尔也想自己醒来但还是想等到王子来解开诅咒。', 7, 187, 1, 134.2, 183.9, NULL, 9000, 15, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":5,"picky":[5]}', NULL, NULL, 1788143395110, NULL),
(427, '雪之女王猪', 5, 5, '为了带走小猪而四处物色落脚处最终停留在猪猪小屋。性格冷酷但据说以前其实心地善良。', 7, 211, 1, 134.4, 220.8, NULL, 8000, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[7,8]}', NULL, NULL, 1788143395110, NULL),
(428, '报恩猪猪', 4, 5, '似乎是为了对场主报恩才来到这里。常常躲起来不知道在做什么。乍看好像是一只猪…？', 7, 212, 1, 127.9, 180, NULL, 5000, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(429, '卖火柴的小猪', 3, 1, '生来贫穷所以卖火柴维生，但从来没有在猪猪小屋卖出火柴。觉得该换个地方所以坐上了卡车。', 7, 213, 1, 125.9, 170.2, NULL, 3500, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(430, '乙猪', 5, 5, '住在龙宫城的超绝世美猪。听说被这只猪招待的猪会如同进入梦境般，错过出货时期变成老猪。', 7, 239, 1, 134.4, 220.8, NULL, 8500, 24, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[7,8]}', NULL, NULL, 1788143395110, NULL),
(431, '气球猪', 5, 1, '在养猪场周年纪念里发气球的猪。要注意拿太多气球的话会漂浮飞走哦。', 7, 250, 1, 134.2, 181.6, NULL, 8000, 24, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":5,"picky":[5]}', NULL, NULL, 1788143395110, NULL),
(432, '暴龙猪', 5, 2, '很憧憬猪猪小屋的暴君这个称号。如果脱掉暴龙装就会变回一只爱哭的胆小鬼。', 7, 273, 1, 133.4, 187.6, NULL, 8500, 20, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":6,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(433, '三角龙猪', 4, 5, '很憧憬三角龙漂亮的角。虽然性格温厚但遇到紧急时刻也会守护同伴。', 7, 274, 1, 130.6, 167.7, NULL, 5500, 18, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[2]}', NULL, NULL, 1788143395110, NULL),
(434, '翼龙猪', 3, 3, '因为穿着特别的恐龙装所以想说就算不能飞至少也可以滑翔吧。正在克服惧高症当中。', 7, 275, 1, 127.7, 171.4, NULL, 3500, 14, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(435, '红发安妮猪', 5, 5, '被领养走之后发现来到的是猪猪小屋。拥有一头红发和雀斑，是一头富有想像力的猪。', 7, 294, 1, 129.8, 180.9, NULL, 7500, 11, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":2,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(436, '富士猪', 5, 2, '喜欢被人拍照，想要变成大家的拍照主题。平时很沉稳，但听说一生气就让人束手无策。', 7, 293, 1, 131.6, 175.9, NULL, 8500, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[2]}', NULL, NULL, 1788143395110, NULL),
(437, '西洋古董猪', 5, 5, '漂亮的公主罗马卷发配上一身华丽洋装宛如古董娃娃的猪。是萝莉塔猪猪们羡慕的对象。', 7, 304, 1, 133, 206.8, NULL, 8500, 22, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[5,8]}', NULL, NULL, 1788143395110, NULL),
(438, '柴郡猪', 5, 4, '穿着一个咧嘴笑的猫布偶装。神出鬼没，有时候猫布偶装还在但里面的猪却消失了。', 7, 312, 1, 131.6, 173.3, NULL, 8000, 28, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":2,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(439, '北极猪', 5, 5, '戴着北极熊的帽子想要体验一下生态系顶点的感觉。穿着保暖拖鞋就不怕冬天会冷了。', 7, 328, 1, 131.6, 164.5, NULL, 9000, 26, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":2,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(440, '海象猪', 4, 3, '很崇拜海象拥有帅气的牙齿。看似食欲旺盛，其实好像只是要维持体型而已', 7, 329, 1, 132.4, 188.2, NULL, 7500, 30, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":6,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(441, '企鹅猪', 3, 5, '不管从什么角度看都很像企鹅的猪。曾经想和企鹅一样饲料直接用吞的，结果就噎到了。', 7, 330, 1, 128.6, 173.9, NULL, 4000, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(442, '斯坦奇克小丑猪', 5, 5, '波兰宫廷的丑角猪。头脑灵活有远见，但通常会用讽刺或玩笑话来打趣', 7, 349, 1, 132.6, 216.2, NULL, 9000, 20, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[1,8]}', NULL, NULL, 1788143395110, NULL),
(443, '猪猪幸运七', 5, 2, '玩拉霸没输过的超强运猪猪。好像把赢来的钱都捐出来用作7周年纪念装饰上。', 7, 355, 1, 134.3, 188.3, NULL, 9000, 21, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":7,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(444, '剑龙猪', 5, 5, '其实是一头爱打扮的猪。有时似乎喜欢改变布偶装背上骨板的颜色。', 7, 379, 1, 132.5, 171.6, NULL, 8000, 16, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[1,2]}', NULL, NULL, 1788143395110, NULL),
(445, '甲龙猪', 4, 2, '壳看起来尖尖的，但因为是布偶装所以很软。据说他非常想变成恐龙。', 7, 380, 1, 130.6, 180, NULL, 5000, 18, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(446, '沧龙猪', 3, 4, '很会游泳的猪。想变得像沧龙一样，但因为穿着布偶装所以无法下水。', 7, 381, 1, 126.8, 170.2, NULL, 3500, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(447, '李小猪', 5, 4, '受到很多猪尊敬的功夫大师猪。非常强，被称作龙会让人害怕，但也可能不会有人害怕。', 7, 396, 1, 132.5, 184.6, NULL, 8500, 16, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(448, '成龙猪', 4, 1, '凡事都自己来的猪。平常很温和，喝了酒之后就会突然变一只猪，展现出无与伦比的力量…应该吧。', 7, 397, 1, 129.7, 175.9, NULL, 6500, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(449, '椰子猪', 5, 3, '热爱夏天的小猪，为了变成椰子，正在努力晒太阳中。用背上的甜甜果汁，为8周年干杯！', 7, 405, 1, 131.9, 216.2, NULL, 8000, 20, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[8]}', NULL, NULL, 1788143395110, NULL),
(500, '恶鬼猪', 3, 4, '每到节分，恶鬼就会跑出来啦。会把撒出去的豆子一个不剩地全部吃光光的豆子控猪猪。二月的猪。', 7, 1, 1, 126.6, 164, NULL, 3500, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[1]}', NULL, NULL, 1788143395110, NULL),
(501, '巧克力猪', 4, 3, '每到情人节就会出货满满。不知道会不会送到喜欢的那个人手上呢。二月的猪。', 7, 2, 1, 128.6, 194.2, NULL, 4000, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[8]}', NULL, NULL, 1788143395110, NULL),
(502, '女儿节猪', 4, 5, '出没于女儿节的月份。代替小猪们承受着灾祸出货了。非常喜欢吃甜米菓。三月的猪。', 7, 3, 1, 127.9, 183.5, NULL, 4000, 14, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(503, '贵族猪', 4, 5, '出没于女儿节的月份。祈祷著小猪们将来都能拥有好姻缘。女儿节猪的丈夫。三月的猪。', 7, 4, 1, 127.9, 183.5, NULL, 4000, 14, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(504, '花样猪', 3, 4, '看樱花还不如看我，很爱现的猪。在赏花宴会上很会即兴表演。四月的猪。', 7, 5, 1, 123.9, 163.1, NULL, 3500, 10, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[3]}', NULL, NULL, 1788143395110, NULL),
(505, '复活节彩猪', 3, 5, '没办法成为复活节彩蛋的猪。由于在复活节时的知名度很低所以一直不能被记住。四月的猪。', 7, 6, 1, 123.9, 175.2, NULL, 3500, 8, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(506, '猪悟空', 4, 3, '个性粗暴棘手。到处恶作剧结果一不留神就被出货了。', 7, 7, 1, 131.5, 180.5, NULL, 4000, 10, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(507, '沙悟猪', 4, 2, '猪八戒的朋友，是以前曾经在旅途上同甘共苦的伙伴。一直很在意他脸色不好。', 7, 8, 1, 130.6, 182, NULL, 3500, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(508, '巨疣猪', 6, 6, '生存于100万年前的“可怕的猪”，是疣猪的同伴。差不多像牛一样大。', 7, 9, 1, 350, 380, NULL, 10000, 40, 1, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.034926759604534},"same":{"99":0.089895}}},"specialFeeding":true}', '{"interval":2,"times":12,"picky":[2,5]}', '{"requirements":"成猪前体重限制 ≥128.0 kg","tips":"每种食物最少吃一次；一口素食MIX、其余都吃草本"}', '["好像有两种喜欢的食物呢","可能不喜欢太狭窄的地方喔","只要给牠满满的饲料就好啦","有很大的獠牙喔","好像喜欢大草原喔"]', 1788143395110, NULL),
(509, '猪猪国王', 5, 5, '爱着人民的国王。偶尔会怕老婆。每天都要修剪它的胡子。', 7, 10, 1, 136.7, 201.5, NULL, 6000, 14, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[8]}', NULL, NULL, 1788143395110, NULL),
(510, '猪猪皇后', 4, 5, '支持着国王是位很坚强的皇后。虽然在人面前是这种形象，但是私底下在国王面前似乎很爱撒娇。', 7, 11, 1, 133.3, 188.8, NULL, 4500, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[7]}', NULL, NULL, 1788143395110, NULL),
(511, '猪猪杰克', 3, 5, '很忠诚，对于年长的人很有礼貌。总是偷偷想着要出人头地的野心家。', 7, 12, 1, 124.4, 178, NULL, 3500, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[4]}', NULL, NULL, 1788143395110, NULL),
(512, '草莓猪', 3, 4, '每年会到各地采草莓。因为不知不觉沾了太多炼乳，所以就变胖了。5月的猪。', 7, 13, 1, 123.9, 163.1, NULL, 3000, 10, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(513, '鲤鱼旗猪', 4, 1, '就算长大成猪也很顽皮。祈祷著小公猪们能顺利长大。希望能长成头好壮壮的公猪。5月的猪。', 7, 14, 1, 131.2, 163.1, NULL, 3500, 14, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[1]}', NULL, NULL, 1788143395110, NULL),
(514, '卡玛普阿猪', 6, 3, '夏威夷掌管海洋的半神。平常会变身成美男子，一生气就会露出真面目，变成有八个眼睛的大猪。小心不要惹它生气喔。', 7, 15, 1, 131.2, 143.2, NULL, 10000, 32, 0, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.034926759604534},"same":{"99":0.061378571428571}}},"specialFeeding":true}', '{"interval":0,"times":8,"picky":[3]}', '{"requirements":null,"tips":"只能喂食刚好8次"}', '["好像有喜欢的食物喔","好像想要维持体型呢","似乎很神圣呢","好像是从南方的岛屿过来的","不管到哪里好像都可以生存耶"]', 1788143395110, NULL),
(515, '雨衣猪', 3, 2, '以前的猪很罕见的会怕泥土。不过有雨具就不怕了，这样就可以在泥泞中好好玩耍啦。６月的猪。', 7, 16, 1, 125.7, 176.6, NULL, 3000, 10, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(516, '蜗牛猪', 3, 1, '被蜗牛迷住了的猪。一直很小心地慢慢走路，可是到了饲料前面就不管了。６月的猪。', 7, 17, 1, 126.6, 164, NULL, 3000, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[2]}', NULL, NULL, 1788143395110, NULL),
(517, '白猪公主', 5, 5, '出于某种原因不是待在城堡而是待在猪猪小屋的公主。爱吃的红薯吃太多曾经差点被噎死。', 7, 18, 1, 132.5, 170.5, NULL, 6000, 14, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[3]}', NULL, NULL, 1788143395110, NULL),
(518, '卖苹果的猪', 4, 1, '似乎在策画坏事的魔女猪。虽然外表看起来很老，但实际上年龄不明。常常在推销可疑的苹果。', 7, 19, 1, 129.7, 180.5, NULL, 4000, 10, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(519, '猎猪', 3, 3, '技术很好的猎人，但也有反过来被人猎的经验。很容易卷入纷争而被拜托一些麻烦事。', 7, 20, 1, 125.8, 175.2, NULL, 3500, 8, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[3,4]}', NULL, NULL, 1788143395110, NULL),
(520, '牛郎猪', 4, 1, '因为太宠爱妻子，没办法兼顾事业与家庭，所以就被迫分居了。期待一年一次的约会，所以很卖力地工作。７月的猪。', 7, 21, 1, 133.3, 167.7, NULL, 4000, 14, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":7,"picky":[1]}', NULL, NULL, 1788143395110, NULL),
(521, '织女猪', 4, 5, '拥有极端的性格，只要一集中工作织布，就会变得很邋遢，但只要跟丈夫在一起，工作就会开始懒散。７月的猪。', 7, 22, 1, 133.3, 167.7, NULL, 4000, 14, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":7,"picky":[1]}', NULL, NULL, 1788143395110, NULL),
(522, '单耳猪', 6, 2, '只要被它穿过胯下，灵魂就会瞬间被吸走。即使得救也会变成没出息的人。是个很可怕的奄美妖怪。', 7, 23, 1, 127.2, 189.4, NULL, 10000, 16, 0, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.034926759604534},"same":{"99":0.07293}}},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[1,3,6]}', '{"requirements":null,"tips":"每种食物最少吃一次"}', '["爱吃的饲料好像有三种喔","似乎喜欢在夜晚出没呢","感觉到有一股妖气呢","似乎来自日本南部","很怕晒到太阳？"]', 1788143395110, NULL),
(523, '庙会猪', 4, 1, '因为太喜欢夏季祭典，忍不住就去搬神轿了。最喜欢的摊位是烤玉米。８月的猪。', 7, 24, 1, 132.5, 182, NULL, 3500, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[4]}', NULL, NULL, 1788143395110, NULL),
(524, '西瓜猪', 3, 1, '西瓜帽是自己挖的。多次差点被在沙滩打西瓜的人当作真的西瓜打。８月的猪。', 7, 25, 1, 125.7, 164.9, NULL, 3000, 14, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[2]}', NULL, NULL, 1788143395110, NULL),
(525, '猪红帽', 4, 4, '个性单纯很容易相信别人。去外婆家的途中稍微绕了一点路就被狩猎了。', 7, 26, 1, 127.9, 180.5, NULL, 3500, 10, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(526, '披着狼皮的猪', 4, 2, '为了自身安全所以才披着狼皮。狼皮怎么来的是个秘密。毛皮卖了很多钱。', 7, 27, 1, 131.5, 182, NULL, 4000, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(527, '茶杯猪', 4, 1, '英国改良的品种。看似比迷你猪小，但是也会有长大的可能。如果要养就要好好负起责任。', 7, 28, 1, 127.9, 191.1, NULL, 6000, 24, 0, 1, 'normal', '{"hunt":{"sites":[98],"prob":{"any":{"99":0.0017354389021898},"same":{"99":0.0020359413661165}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(528, '神猪', 6, 5, '于台湾传统的祭典活动中供奉的神猪。虽说是为了比赛看谁重，但也后悔自己吃了那么多。', 7, 29, 1, 390, 420, NULL, 10000, 36, 0, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.034926759604534},"same":{"99":0.061378571428571}}},"specialFeeding":true}', '{"interval":0,"times":18,"picky":[]}', '{"requirements":"成猪前体重限制 ≥148.0 kg","tips":"多喂食松露"}', '["好像不太运动","好像很神圣庄严","到底要养到多胖呀","要变得很重很重呢","好像是从台湾来的"]', 1788143395110, NULL),
(529, '艺术猪', 4, 3, '在养猪场里持续创作了很多猪猪界相遇与离别的作品之巨匠。有很多很难理解的作品。9月的猪。', 7, 30, 1, 131.1, 191.1, NULL, 5500, 24, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[7]}', NULL, NULL, 1788143395110, NULL),
(530, '菇菇猪', 3, 1, '被香菇的菌种附着变成苗床。随时随地都可以香菇吃到饱，好像还不错。9月的猪。', 7, 31, 1, 126.9, 163.1, NULL, 3000, 10, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(531, '野兽猪', 5, 0, '相信若与命中注定的母猪相遇，就可以解开诅咒摆脱野兽外貌。不过实际上他并没有受到诅咒。', 7, 32, 1, 134.3, 212, NULL, 6000, 24, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[7,8]}', NULL, NULL, 1788143395110, NULL),
(532, '美女猪', 3, 1, '喜欢的是会看内在美的人。虽然嘴上说着不能以貌取人，但还是为了与对的人相遇而打扮得很漂亮。', 7, 33, 1, 127.1, 182, NULL, 3500, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[4,5]}', NULL, NULL, 1788143395110, NULL),
(533, '杰克南瓜猪', 4, 2, '不给糖就捣蛋！没得到糖果就不肯走。因为害怕太真实的妖怪装扮反而不敢假扮。10月的猪。', 7, 34, 1, 130.6, 188.1, NULL, 3500, 20, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(534, '运动猪', 3, 3, '会参加运动会上的各种竞技。动多少也吃多少所以瘦不了，肉质加了一些油脂就变成霜降猪了。10月的猪。', 7, 35, 1, 129.6, 180.7, NULL, 3000, 16, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[3,4]}', NULL, NULL, 1788143395110, NULL),
(535, '赫尼文猪', 6, 4, '威尔士神话中带来富饶的谷物与蜜蜂的猪。也有另一种说法，尽管是猪，但也会生出狼、鹰或怪猫。', 7, 36, 1, 131, 150, NULL, 10000, 24, 1, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.034926759604534},"same":{"99":0.089895}}},"specialFeeding":true}', '{"interval":0,"times":6,"picky":[1]}', '{"requirements":"成猪前体重限制 98.0-100.0 kg","tips":"23-25kg，最好抓25kg的，只吃杂粮；四个阶段体重参照：32、54、76、98，每个阶段不能超过这个体重"}', '["好像从大不列颠岛来的","好像有最爱吃的饲料","似乎很爱到处跑","太胖好像不好呐","太瘦也不行噢"]', 1788143395110, NULL),
(536, '烤地瓜猪', 3, 3, '猪猪一靠近马上就会闻到香味。只要闻到这个味道就会让人感到暖心。11月的猪。', 7, 37, 1, 130.5, 164.9, NULL, 3000, 14, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[3]}', NULL, NULL, 1788143395110, NULL),
(537, '农夫猪', 3, 4, '收获之秋。喊著：来收成吧！结果自己就坐上出货的卡车，也算是被收获的一种。11月的猪。', 7, 38, 1, 129.6, 180.7, NULL, 3000, 16, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(538, '雪猪', 3, 5, '憧憬着白色圣诞节的猪。出乎意料地怕冷所以偷偷在身上藏了一些暖暖包。12月的猪。', 7, 42, 1, 126.6, 179.3, NULL, 3000, 14, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395110, NULL),
(539, '溜冰猪', 4, 5, '在母猪之间拥有超人气的冰上之猪。目标是往溜冰大会迈进现正训练中。擅长后外点猪跳。12月的猪。', 7, 43, 1, 130.6, 191.1, NULL, 5500, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[2,5]}', NULL, NULL, 1788143395111, NULL),
(540, '阿拉丁猪', 3, 3, '梦想可以住在城堡的穷猪。在犹豫是否要将偶然得到的神灯卖掉。还不知道神灯的秘密。', 7, 44, 1, 126.6, 178, NULL, 3000, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(541, '阿拉伯猪公主', 4, 3, '因为不想政治联姻所以从城堡离家出走的公主。向往自由恋爱所以费尽千辛万苦来到养猪场。已经回不去城堡了。', 7, 45, 1, 132.5, 194, NULL, 5500, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[5,7]}', NULL, NULL, 1788143395111, NULL),
(542, '神灯猪', 5, 2, '魔法神灯的精灵。会实现拥有神灯的猪3个愿望。因为住的地方太窄所以最近总是跑出来蹓跶。', 7, 46, 1, 137.6, 196, NULL, 9500, 24, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":7,"picky":[5]}', NULL, NULL, 1788143395111, NULL),
(543, '库雷马拉猪', 6, 1, '斯拉夫神话中家畜的守护神。掌管猪猪。从小猪出生后就开始守护小猪的健康到被做成肉品的最后一刻。', 7, 44, 1, 133.4, 210.5, NULL, 10000, 30, 1, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.034926759604534},"same":{"99":0.041164444815754}}},"specialFeeding":true}', '{"interval":0,"times":8,"picky":[1,2,4,5,7,8]}', '{"requirements":null,"tips":"每种食物最少吃一次；不吃红薯和橡子"}', '["喜欢的食物好像有6种","讨厌的食物好像有2种","好像也喜欢伏特加？","似乎对香味很讲究","好像喜欢往外跑呐"]', 1788143395111, NULL),
(544, '舞龙舞猪', 4, 4, '祝贺新年的好运猪。头被咬的话可能会招来厄运。正在摸索新风格的舞蹈。1月的猪。', 7, 45, 1, 131.5, 191.1, NULL, 5000, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":5,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(545, '暖桌猪', 3, 1, '从正月开始每天就过着吃饱睡睡饱吃的生活越来越胖。无法抵抗暖桌魔力的一只猪。１月的猪。', 7, 46, 1, 127.5, 182, NULL, 3000, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[3,4]}', NULL, NULL, 1788143395111, NULL),
(546, '猪猪小丑', 5, 1, '猪猪王国的宫廷小丑。虽然讲话毒辣，但也是唯一被国王允许想说什么就说什么的一个存在。', 7, 47, 1, 132.5, 201.1, NULL, 6000, 20, 0, 1, 'normal', '{"hunt":{"sites":[98],"prob":{"any":{"99":0.0017354389021898},"same":{"99":0.0020359413661165}}},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(547, '奇妙仙猪', 4, 4, '会出现在不想变成猪肉的猪猪身边的妖精猪。被魔法粉末洒到的话好像就会变成好吃的猪肉。', 7, 48, 1, 131.1, 186.5, NULL, 5000, 18, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[5]}', NULL, NULL, 1788143395111, NULL),
(548, '鳄鱼猪', 3, 2, '想要体验位于食物链顶端的感觉所以假扮成鳄鱼。虽然是假鳄鱼但是猪猪船长非常怕他。', 7, 49, 1, 126.6, 180.7, NULL, 3500, 16, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(549, '毕业猪', 3, 2, '“大家都在逃跑的狩猎场、好吃的红薯、舒适干净的便便扫除。今天我要从猪猪小屋毕业啦！”3月的猪。', 7, 50, 1, 126.6, 186.1, NULL, 3500, 24, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(550, '白色情人猪', 4, 5, '不管有没有收到巧克力，我都会回赠糖果给你。最适合在白色情人节回礼的3月的猪。', 7, 51, 1, 129.7, 191.1, NULL, 4000, 24, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(551, '噗公英', 3, 5, '喜欢在暖阳的日子里晒太阳。因为天气还有点冷所以戴着毛帽。4月的猪。', 7, 54, 1, 129.6, 183.4, NULL, 3500, 20, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(552, '愚人猪', 3, 1, '每天都是愚人节。说谎的话鼻孔会变大。明明喜欢吃红薯却还骗人说他不挑食。4月的猪。', 7, 55, 1, 126.9, 164, NULL, 3000, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"fail":[552],"specialFeeding":true}', '{"interval":0,"times":1,"picky":[3]}', NULL, NULL, 1788143395111, NULL),
(553, '曹操猪', 4, 3, '“猪国志”里登场的智勇双全的武将。会与周遭的猪舍有大规模的势力斗争，是非常有领导才能的暴徒。', 7, 56, 1, 131.1, 188.1, NULL, 5000, 20, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[7]}', NULL, NULL, 1788143395111, NULL),
(554, '刘备猪', 4, 1, '“猪国志”里登场的仁德武将。与邻近猪舍的战绩虽然没有很好，不过有很多猪猪都很敬仰他。。', 7, 57, 1, 131.1, 188.1, NULL, 5000, 20, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[7]}', NULL, NULL, 1788143395111, NULL),
(555, '孙权猪', 4, 5, '“猪国志”里登场的深谋远虑的武将。一直以来都与邻近猪舍做好外交生存到现在。老了要注意老猪痴呆。', 7, 58, 1, 131.1, 188.1, NULL, 5000, 20, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[7]}', NULL, NULL, 1788143395111, NULL),
(556, '猪乃馨', 3, 5, '会出现在总是施予恩惠的母猪身边。康乃馨代表了满满的感谢心意。5月的猪。', 7, 59, 1, 126.6, 183.4, NULL, 3500, 20, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(557, '猪笋', 3, 3, '若开始变温暖，时不时就会从地底探出头来。像竹子一样成长速度很快。5月的猪。', 7, 60, 1, 125.7, 162.2, NULL, 3000, 3, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[2]}', NULL, NULL, 1788143395111, NULL),
(558, '绣球花猪', 3, 4, '在持续下雨的日子里也要努力保有美丽的心情。头上的蜗牛是宠物。6月的猪。', 7, 62, 1, 123.9, 180.7, NULL, 3000, 16, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(559, '樱桃猪', 3, 1, '在去采樱桃的路上迷路，结果自己反而被采走了。身上有甜甜的新鲜香味。6月的猪。', 7, 63, 1, 123.9, 182, NULL, 3500, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(560, '雷猪', 4, 5, '听说只要敲击太鼓就会打雷，但从来没人看过他打鼓的样子。不乖的小猪都很害怕肚脐被它偷走。', 7, 64, 1, 130.6, 188.1, NULL, 5000, 20, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(561, '风猪', 4, 2, '会利用风袋吹出微风、弱、中、强、暴风。如果拿出真本事说不定连整个猪猪小屋都会被吹走。', 7, 65, 1, 130.6, 188.1, NULL, 5000, 20, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(562, '猪葛孔明', 4, 1, '辅佐“猪国志”里登场的刘备猪的天才军师。听说它去考察的食物是肉包的起源。', 7, 66, 1, 129.7, 188.1, NULL, 4500, 20, 0, 1, 'normal', '{"hunt":{"sites":[98],"prob":{"any":{"99":0.0017354389021898},"same":{"99":0.0020359413661165}}},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(563, '捕虫猪', 3, 3, '采集昆虫是他生存的意义，喜爱昆虫的热度不输夏天。期待捉到未知的昆虫于是坐上了卡车。7月的猪。', 7, 69, 1, 128.5, 182, NULL, 3500, 18, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[4]}', NULL, NULL, 1788143395111, NULL),
(564, '刨冰猪', 3, 5, '会根据当天的心情变换刨冰上的糖浆，不过大部分都是草莓口味。总是头痛。7月的猪。', 7, 70, 1, 127.5, 176.6, NULL, 3500, 10, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(565, '猪若丸', 5, 1, '身手矫健功夫很好，即使是比自己大只的猪猪也能打倒。其实为了找寻出生于武家却分离的哥哥而坐上了卡车。', 7, 74, 1, 130.7, 201.1, NULL, 5000, 20, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(566, '猪弁庆', 4, 3, '在猪猪小屋中总是很蛮横，但一踏出猪猪小屋外就变得很安分。小腿骨是他的弱点。', 7, 75, 1, 132.4, 186.5, NULL, 4500, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":6,"picky":[]}', NULL, NULL, 1788143395111, NULL);

INSERT INTO pigs (
  p_no, name, rare, color, description,
  atlas_type, atlas_index, atlas_visible,
  weight_small, weight_big,
  rent, price, lifespan, graze, special, status,
  acquisition, feeding, breeding_guide, hints, updated_at, updated_by
) VALUES
(567, '浮潜猪', 3, 3, '只要有海就想要下去潜水。潜水时不知道是在游泳还是往下沉。其实是个旱鸭子？8月的猪。', 7, 76, 1, 126.6, 178, NULL, 3000, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(568, '海军猪', 3, 4, '因为喜欢海军风所以搭上了船。只是一直记不住旗语结果常被前辈骂。8月的猪。', 7, 77, 1, 126.6, 180.7, NULL, 3000, 16, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(569, '波斯菊猪', 3, 4, '不只拥有漂亮可爱的外表还具有坚强的个性，只要日照和通风良好就能健康长大。9月的猪。', 7, 79, 1, 125.7, 164.9, NULL, 3000, 14, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[2]}', NULL, NULL, 1788143395111, NULL),
(570, '猪烤秋刀鱼', 3, 1, '长大后会变成代表秋之味觉的秋刀鱼但是怎么看都像是鲔鱼或𫚕鱼。现在正是美味的时候。9月的猪。', 7, 80, 1, 125.7, 178, NULL, 3000, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(571, '幽灵猪', 3, 2, '最喜欢吓人。传闻猪猪小屋每到秋天就会看到白色幽灵，其实就是这只猪。10月的猪。', 7, 81, 1, 128.6, 163.3, NULL, 3000, 9, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(572, '橡子猪', 3, 3, '最引人注目的就是屁股上套了“帽子”。常被误认是饲料而被伊比利亚猪咬。10月的猪。', 7, 82, 1, 128.7, 169, NULL, 3000, 10, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[6]}', NULL, NULL, 1788143395111, NULL),
(573, '白天鹅猪', 4, 5, '幻想以为被恶魔施法变成天鹅，只有在夜晚才能恢复成猪。一边跳舞一边等待王子到来。', 7, 83, 1, 129.7, 176, NULL, 4500, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(574, '黑天鹅猪', 4, 2, '幻想自己是恶魔的女儿。一直想要阻挠某只猪的恋情，因为对方一直没出现结果什么也没做。', 7, 84, 1, 130.9, 196.9, NULL, 4500, 10, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":2,"picky":[8]}', NULL, NULL, 1788143395111, NULL),
(575, '蒙布朗猪', 4, 3, '若想拿他头上的栗子就会生气。好像想和其他甜点系的猪猪成立一个甜点大会。11月的猪。', 7, 85, 1, 131.9, 181.4, NULL, 4500, 20, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[3,6]}', NULL, NULL, 1788143395111, NULL),
(576, '松球猪', 3, 3, '走在森林就会被松鼠飞扑啃咬身体，所以松鼠是天敌。可以做工艺品或食用、点火器等多种用途。11月的猪。', 7, 86, 1, 125.9, 177.5, NULL, 3000, 8, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(577, '猪杜莎', 4, 2, '听说眼神被注视到的猪猪会变成石头。原本似乎是一只美猪，为什么会变成这样是一团谜。', 7, 88, 1, 130.6, 184.1, NULL, 4500, 24, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(578, '蝴蝶猪', 3, 1, '光舔花蜜所以就变成了蝴蝶的猪。但是身体太重所以飞不起来。当然也不会游蝶式。', 7, 89, 1, 127.7, 173.9, NULL, 3500, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(579, '毛衣猪', 3, 4, '完成一次又重新编织，所以每次的花纹跟颜色都不一样。从基本款花色到复杂的花色什么都会编织。12月的猪。', 7, 94, 1, 125.9, 167.7, NULL, 3000, 8, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(580, '花圈猪', 3, 1, '似乎一时冲动就钻进藤田叔买的花圈里了。每到圣诞节就会很开心。12月的猪。', 7, 95, 1, 126.2, 169, NULL, 3000, 10, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[5]}', NULL, NULL, 1788143395111, NULL),
(581, '雪女猪', 4, 5, '呼出来的气息非常寒冷简直会让人冻僵。原本应该是可怕的美丽妖怪猪，但是在夏天会让人觉得凉爽所以人缘很好。', 7, 96, 1, 129.7, 178, NULL, 4000, 15, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(582, '雪子猪', 4, 1, '小猪样子的雪妖怪。冬天很有精神但是一到夏天就累呼呼。推荐凉爽时期再进货的猪猪No.1', 7, 97, 1, 129.7, 170.6, NULL, 4000, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[3]}', NULL, NULL, 1788143395111, NULL),
(583, '新成猪', 4, 4, '终于长大成猪了。谢谢场主细心养育我。我要穿着美美的衣服坐上卡车参加成猪式去。1月的猪。', 7, 99, 1, 132, 181.4, NULL, 4500, 20, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[5]}', NULL, NULL, 1788143395111, NULL),
(584, '连帽大衣猪', 3, 3, '喜欢打扮的猪。这次的主题是就算天气冷也要可爱又防寒。但是鼻水总是流也流不停。1月的猪。', 7, 100, 1, 127.7, 169, NULL, 3000, 10, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(585, '滑雪猪', 3, 5, '一滑雪就会被黄色能量包围，仿佛要把滑雪场融化。皮肤因为被白雪反射的阳光晒黑，好像跟本来的肤色不同。2月的猪。', 7, 101, 1, 127.7, 160, NULL, 3000, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[2]}', NULL, NULL, 1788143395111, NULL),
(586, '猪猪不倒翁', 3, 4, '祈祷未来能一帆风顺。只要相信自己一路以来累积的努力肯定就能开花结果。2月的猪。', 7, 102, 1, 125.9, 169, NULL, 3939, 10, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(587, '戴珍珠耳环的猪', 4, 4, '蓝色的头巾和大颗的珍珠最让人印象深刻。因为脸颊肉的关系无法转头。和珍猪很亲近。', 7, 103, 1, 128.8, 181.4, NULL, 4000, 20, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[2,4]}', NULL, NULL, 1788143395111, NULL),
(588, '蒙猪丽莎', 4, 3, '观光客从世界各地蜂拥而至猪猪小屋就为了看它一眼。不过本人一点也不介意地仍然笑容满面。', 7, 104, 1, 130.9, 211.8, NULL, 4500, 24, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[8]}', NULL, NULL, 1788143395111, NULL),
(589, '写乐的浮世绘猪', 4, 5, '因为脸长的很可怕所以常常让人以为是坏人，实际上是只温柔的猪。于是利用这张脸去当歌舞伎演员。', 7, 105, 1, 127.9, 172, NULL, 4000, 18, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(590, '斯芬克斯猪', 6, 3, '拥有高智商喜欢出谜题，如果答不出来就会袭击你。被场主猜中谜语所以很不甘心，于是就自己选择了出货的道路。', 7, 106, 1, 134.2, 197.8, NULL, 10000, 24, 0, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.034926759604534},"same":{"99":0.061378571428571}}},"specialFeeding":true}', '{"interval":0,"times":9,"picky":[1,1,1,1,2,2,8,8,8]}', '{"requirements":null,"tips":"必须按照顺序喂食；只能喂最多9次"}', '["「最初的要4次」的样子","「其次的要2次」的样子","「最后的要3次」的样子","好像喜欢出谜语","好像不太喜欢运动"]', 1788143395111, NULL),
(591, '喷嚏猪', 3, 1, '眼睛很痒所以喷嚏跟鼻水流不停…今年这个地狱也来到了啊。爱用高级面纸。3月的猪。', 7, 107, 1, 127.5, 173.9, NULL, 3000, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[5]}', NULL, NULL, 1788143395111, NULL),
(592, '蜜蜂猪', 3, 5, '就只会吸花蜜却不生产蜂蜜不工作的蜜蜂。身体是黄色的似乎是因为吸了太多花蜜。3月的猪。', 7, 108, 1, 126.8, 167.7, NULL, 3000, 8, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(593, '樱饼猪', 3, 4, '说到春天就想到这个和菓子。用盐腌过的樱叶代替棉被，常常一边赏樱一边晒太阳。4月的猪。', 7, 109, 1, 125.9, 167.7, NULL, 3000, 8, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(594, '采茶猪', 3, 1, '春天差不多可以开始收获茶叶了，因为想让藤田叔品尝新茶于是坐上了卡车…。4月的猪。', 7, 110, 1, 125.9, 172.7, NULL, 3000, 16, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(595, '精灵猪', 4, 5, '拥有非常美丽外表的高雅精灵猪。似乎是神射手的种族所以出货的时候要注意箭会射向你。', 7, 111, 1, 129.7, 181.4, NULL, 4000, 20, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[5,6]}', NULL, NULL, 1788143395111, NULL),
(596, '半兽猪', 4, 0, '性格凶猛如果饲料喂不够就会开始胡闹。自称是大魔王的手下。与英雄系列的猪猪不合。', 7, 112, 1, 130.6, 180, NULL, 4500, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(597, '矮猪', 4, 0, '体型矮小的种族，手很灵巧。养猪场用的铲子等一部分的器具都是他们做的样子。', 7, 113, 1, 127.9, 178.6, NULL, 4000, 16, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(598, '奇异果猪', 3, 3, '模仿奇异果的猪。鲜明的绿色看起来很鲜嫩。肉吃起来不知道是不是酸酸甜甜的。5月的猪。', 7, 115, 1, 125.9, 170.2, NULL, 3000, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(599, '端午小猪', 3, 1, '端午节祈祷小公猪都能健康成长。头上的头盔好像是借来的装饰。5月的猪。', 7, 116, 1, 130, 178.3, NULL, 3000, 25, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(600, '独角猪', 6, 5, '喜欢的类型是没有配种经验的母猪。脾气非常不好，如果有别的猪在的话就会生气不知道跑去哪里。', 7, 117, 1, 123.9, 211.4, NULL, 10000, 24, 0, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.034926759604534},"same":{"99":0.061378571428571}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', '{"requirements":null,"tips":"成猪前在场中要最少一只未配种过的母；成猪时在场中不能有公猪；成猪时不能单独"}', '["某部分好像可以用来解毒","自尊心高让牠生气的话好像很危险","好像很排斥周围的猪","好像很跟地不合的猪","占有欲很强的样子"]', 1788143395111, NULL),
(601, '双角猪', 4, 5, '公猪母猪都喜欢的八面玲珑。由于没有在当下环境实现某个传承级所追求的东西，于是它就取而代之出现了。', 7, 118, 1, 125.9, 195, NULL, 4500, 24, 0, 1, 'normal', '{"hunt":{"sites":[0]},"fail":[600],"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(602, '晴天猪猪', 3, 4, '装扮成晴天娃娃的样子但是没有放晴的能力，所以即使下雨了祈求它也不会放晴。6月的猪。', 7, 119, 1, 125.9, 169, NULL, 3000, 10, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(603, '青蛙猪', 3, 5, '在猪猪小屋内很有元气蹦蹦跳跳的一只灵活的猪。头上的叶子有雨伞的功用。6月的猪。', 7, 120, 1, 125.9, 170.2, NULL, 3000, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(604, '金太郎猪', 4, 1, '力大无穷的猪，似乎与熊相扑还获得了胜利。将来的梦想是打败坏人成为英雄。', 7, 121, 1, 130.6, 198, NULL, 4000, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[2,7]}', NULL, NULL, 1788143395111, NULL),
(605, '桃太郎猪', 4, 4, '绝不允许有伤害猪猪的东西，是只正义感满满的猪。在出货前也没有给任何人糯米团子就自己吃光了。', 7, 122, 1, 129.7, 170.6, NULL, 4000, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[3]}', NULL, NULL, 1788143395111, NULL),
(606, '猪岛太郎', 4, 3, '因为帮助了被欺负的乌龟，所以就被带到猪猪小屋来了。很在意作为回礼的玉手箱里有什么东西。', 7, 123, 1, 132.8, 211.8, NULL, 4000, 24, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[8]}', NULL, NULL, 1788143395111, NULL),
(607, '哈密瓜猪', 4, 5, '身上散发着哈密瓜的香味。为了不忘记身为猪的身份所以披了一块火腿。7月的猪。', 7, 124, 1, 133.4, 199.7, NULL, 4500, 26, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[7]}', NULL, NULL, 1788143395111, NULL),
(608, '猪猪水母', 3, 4, '因为太喜欢水母所以用来当作时尚的元素。素材很讲究做成的水母帽子堪称杰作。7月的猪。', 7, 125, 1, 126.8, 175.2, NULL, 3000, 20, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(609, '美猪鱼', 6, 1, '拥有一种力量，只要听到它美丽歌声的人就会被吸引过来。传说某些地区只要吃了它的肉就能长命百岁。', 7, 126, 1, 133.8, 179.6, NULL, 10000, 24, 1, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.034926759604534},"same":{"99":0.041164444815754}}},"specialFeeding":true}', '{"interval":0,"times":12,"picky":[]}', '{"requirements":"成猪前体重限制 ≤108.0 kg","tips":"喂食不长肉的（杂粮、素食mix）；猪仔体重建议抓35以内的，最好是二十几的"}', '["好像对喂食很有自信呢","意外地好像喜欢夜生活","好像想要充分练习发音","对船很有兴趣的样子","太胖的话移动好像会很困难"]', 1788143395111, NULL),
(610, '浴衣美猪', 3, 1, '穿着烟火图案浴衣的猪。庙会、烟火大会、盂兰盆节。今年的夏天也要穿很多浴衣。8月的猪。', 7, 129, 1, 125.9, 172.7, NULL, 3000, 16, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(611, '向日葵猪', 3, 3, '夏天朝气蓬勃的象征。饲料里没有向日葵种子很不开心。闲暇时就会追着太阳跑。8月的猪。', 7, 130, 1, 126.2, 173.9, NULL, 3000, 18, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[4]}', NULL, NULL, 1788143395111, NULL),
(612, '猪纳斯', 4, 1, '听说其实是从海中出生乘着贝壳来到这里。常常沐浴著神吹来的风，头发随风摆动。', 7, 131, 1, 128.2, 184.1, NULL, 6500, 24, 0, 1, 'normal', '{"hunt":{"sites":[98],"prob":{"any":{"99":0.0017354389021898},"same":{"99":0.0020359413661165}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[5]}', NULL, NULL, 1788143395111, NULL),
(613, '火男猪', 3, 4, '幽默的个性喜欢带给大家欢笑。特别擅长扮鬼脸，不曾输过。', 7, 132, 1, 127.7, 173.9, NULL, 3500, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(614, '阿龟猪', 3, 5, '多才多艺，很擅长跳舞。拥有独特的搞笑感，为了跳出让人捧腹大笑的舞蹈日夜练习的样子。', 7, 133, 1, 127.7, 162.7, NULL, 3500, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[1]}', NULL, NULL, 1788143395111, NULL),
(615, '吸血猪', 6, 2, '虽然很绅士却弥漫着诡异恐怖氛围的猪。猪猪小屋里的猪要小心不要被它咬到后颈。', 7, 134, 1, 126.4, 194.9, NULL, 10000, 8, 0, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.034926759604534},"same":{"99":0.07293}}},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[1,2,7]}', '{"requirements":"成猪时间限制 21:00:00-02:59:59","tips":null}', '["好像只在夜晚现身","似乎讨厌遇到强烈的东西","对一部分的饲料很执着？","好像喜欢3种饲料","好像会咬别的猪"]', 1788143395111, NULL),
(616, '葡萄猪', 3, 4, '颜色鲜艳身上挂满新鲜果实的猪。和猪一样会被加工成各种东西，所以对葡萄抱有亲近感。9月的猪。', 7, 135, 1, 125.9, 177.6, NULL, 3000, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(617, '稻草猪', 3, 2, '为了防止猪猪小屋被乌鸦骚扰所以扮成稻草人的猪。死守着饲料连其他的猪都不能随便靠近。9月的猪。', 7, 136, 1, 125.9, 162.7, NULL, 3000, 18, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[1]}', NULL, NULL, 1788143395111, NULL),
(618, '慕尼黑啤酒猪', 3, 4, '在德国盛大举办的啤酒节中运送啤酒的猪。成人・成猪之后才可以喝酒。10月的猪。', 7, 137, 1, 126.8, 175.2, NULL, 3000, 20, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[1,5]}', NULL, NULL, 1788143395111, NULL),
(619, '彼岸花猪', 3, 5, '喜欢彼岸花所以创立了“曼猪沙华”品牌的设计师。著用的单品都是自己公司的品牌。10月的猪。', 7, 138, 1, 125.9, 177.6, NULL, 3000, 24, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(620, '罗密猪', 4, 1, '为爱而生有点鲁莽。在猪猪小屋遇见真命天女。为了一起跨越出货的障碍以成就两人之间的爱情一直反抗著。', 7, 139, 1, 131.5, 184.1, NULL, 4500, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(621, '猪丽叶', 4, 4, '为了与心爱之猪逃亡，企图用毒药来一场假死计划。不知恋爱为何物的单纯猪猪意外地很有行动力。', 7, 140, 1, 131.5, 184.1, NULL, 4500, 24, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(622, '柿子猪', 3, 5, '身上的柿子虽然很涩但是果肉还是一样很好吃。上了年纪之后可能会变成柿子干。11月的猪。', 7, 141, 1, 126.8, 167.7, NULL, 3000, 8, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(623, '亡灵节猪', 3, 2, '亡灵节装扮的猪，以表达对故人的思念与祝福。擅长弹吉他炒热现场气氛。11月的猪。', 7, 142, 1, 126.8, 171.4, NULL, 3000, 14, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[1,4]}', NULL, NULL, 1788143395111, NULL),
(624, '九尾猪', 6, 4, '可怕的食人妖猪。原本想要变成美女蛊惑场主过着穷奢极欲的生活结果就被出货了。听说也是神兽。', 7, 143, 1, 137.3, 204.1, NULL, 10000, 24, 0, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.034926759604534},"same":{"99":0.089895}}},"specialFeeding":true}', '{"interval":0,"times":9,"picky":[7,8]}', '{"requirements":null,"tips":"只能喂食9次；必须在26小时后成猪；必须使用稻草地板直到够时间后取消地板即可"}', '["喜欢的饲料好像有2种","好像很浪费","好像会花一些时间","似乎擅长魅惑欺骗","似乎很神圣呢"]', 1788143395111, NULL),
(625, '妲己猪', 4, 4, '拥有美貌做尽坏事的妖女，堪称中国三大恶猪。在被场主识破真面目之前就出货了。', 7, 144, 1, 137.3, 227.8, NULL, 7000, 24, 0, 1, 'normal', '{"hunt":{"sites":[0]},"fail":[624],"specialFeeding":true}', NULL, NULL, NULL, 1788143395111, NULL),
(626, '夜鸣豚骨猪', 3, 5, '用鼻子代替唢呐噗噗叫，它来的时候就能闻到一股香喷喷的味道。帽子是手工礼物。12月的猪。', 7, 145, 1, 125.9, 170.2, NULL, 3000, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(627, '极光天使猪', 3, 2, '与极光一同出现在清澈夜空中的冬日天使。听说如果看到它在满天星空奔跑的样子就能变得很幸福。12月的猪。', 7, 146, 1, 125.9, 170.2, NULL, 3000, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(628, '猪天狗', 4, 4, '因为身体变重飞不起来所以就被出货了。会用羽毛扇引起火灾或刮风，养猪农都很怕它。', 7, 147, 1, 128.8, 168.7, NULL, 4500, 20, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":2,"picky":[3]}', NULL, NULL, 1788143395111, NULL),
(629, '猪河童', 4, 5, '如果没有定期在头上的盘子加水就会变得很没精神。喜欢相扑，一直想要与横纲较量。', 7, 148, 1, 129.7, 168.7, NULL, 4500, 20, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[2]}', NULL, NULL, 1788143395111, NULL),
(630, '羽子板猪', 3, 5, '背着阻挡灾厄的羽子板，是头很吉利的猪。烦恼是背痒的时候都抓不到。1月的猪。', 7, 152, 1, 128.6, 177.6, NULL, 3500, 24, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(631, '书法猪', 3, 3, '为了写出与新年相衬的文字所以来到猪猪小屋。但是草书写太好了无法解读。1月的猪。', 7, 153, 1, 127.9, 167.7, NULL, 4000, 8, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(632, '雪怪猪', 6, 6, '谜一般的存在，会留下足迹但却不显露真面目。认真起来的话会用两只脚走路。常常被误认为是熊。', 7, 154, 1, 165, 277.6, NULL, 10000, 20, 0, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.034926759604534},"same":{"99":0.089895}}},"specialFeeding":true}', '{"interval":0.5,"times":20,"picky":[]}', '{"requirements":"成猪前体重限制 ≥128.0 kg","tips":"建议多吃松露"}', '["好像会变成食欲旺盛的大家伙","来自山中似乎喜欢到处跑","好像不希望被人看到","毛发好像很浓密","他的足迹似乎是一团谜"]', 1788143395111, NULL),
(633, '温泉猪', 3, 4, '因为泡温泉所以气色很好的猪。泡汤的时候不知道有没有在吃涮涮锅的错觉。2月的猪。', 7, 155, 1, 125.9, 171.4, NULL, 3000, 14, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(634, '森巴猪', 3, 3, '华丽的服装在猪猪小屋显得格外醒目。一直梦想着要去发源地的里约嘉年华会跳舞。2月的猪。', 7, 156, 1, 127.7, 177.6, NULL, 3000, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(635, '穿长靴的猪', 4, 2, '如果给猪猪长靴和袋子，猪猪就会努力让场主幸福。不过或许只是想要逃避出货而已。', 7, 157, 1, 131.5, 180, NULL, 3000, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(636, '猪猪的新衣', 3, 1, '深信着只有高贵的猪才看的到他身上的衣服，其实只是一只普通猪。最后谁也没有戳破他，就这样出货去了。', 7, 158, 1, 126.6, 190.2, NULL, 3000, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[7]}', NULL, NULL, 1788143395111, NULL),
(637, '吹笛猪', 3, 1, '穿着怪异吹着笛子的猪。当他吹笛子时小屋中的小猪就会集合列队跟他走。擅长驱赶老鼠。', 7, 159, 1, 126.8, 172.1, NULL, 3000, 15, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(638, '山茶花猪', 3, 1, '喜欢鲜艳山茶花图案的怀旧风和服。教养好姿态迷人，动作举止宛如一朵花。3月的猪。', 7, 160, 1, 127.7, 177.6, NULL, 3000, 24, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(639, '洋葱猪', 3, 5, '身体表面常保持干燥，脸部则很鲜嫩。靠近他的话眼睛会被辣到眼泪流不停。3月的猪。', 7, 161, 1, 125.9, 166.5, NULL, 3000, 6, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(640, '米迦勒猪', 6, 1, '曾有疾病流行时大猪使为了拯救大家而降临的趣闻。平定兄长发起的叛乱获得胜利，但兄长也因此堕猪变成了恶魔。', 7, 162, 1, 128, 212.7, NULL, 10000, 12, 0, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.11318193277147}}},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', '{"requirements":"成猪时同场身边要有病猪；抓捕后需接种疫苗；最少4种不同饲料","tips":null}', '["似乎是大猪使的其中一人","有很多降临的趣闻呐","很在意周遭的环境呐","饲料不同好像会堕猪","数字似乎是关键"]', 1788143395111, NULL),
(641, '路西法猪', 6, 1, '前大猪使的堕猪使长。因为反叛而与四大猪使之一的弟弟对峙但败北了。堕猪后人称魔王猪旦。', 7, 163, 1, 126.7, 179.4, NULL, 10000, 12, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[6]}', '{"requirements":"成猪时同场身边要有病猪；抓捕后需接种疫苗；只能喂食3次、只吃橡子","tips":null}', '["似乎是大猪使的其中一人","有很多降临的趣闻呐","很在意周遭的环境呐","饲料不同好像会堕猪","数字似乎是关键"]', 1788143395111, NULL),
(642, '紫藤猪', 3, 4, '等到发现时藤蔓已经缠绕猪猪并开花变成这样了。如果没有晒到太阳的话，花朵和猪猪都会变得没精神。4月的猪。', 7, 165, 1, 125.9, 160, NULL, 3000, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":1,"picky":[1]}', NULL, NULL, 1788143395111, NULL),
(643, '山葵猪', 4, 5, '喜欢清澈的水和凉爽的地方。常常被自己身上的山葵呛到流眼泪。4月的猪。', 7, 166, 1, 129.7, 184.1, NULL, 3500, 24, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(644, '酒吞猪子', 5, 0, '粗暴、爱偷窃且爱喝酒的有名鬼猪。喝醉的话就会不小心将重要的事情说出来，常常一喝酒就乱事。', 7, 167, 1, 133.4, 173.7, NULL, 5500, 20, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":6,"picky":[1,3]}', NULL, NULL, 1788143395111, NULL),
(645, '猪姥', 4, 3, '慈祥的微笑背后其实会趁隙将猪和人抓住企图吃掉对方。每天晚上都会磨刀，所以她的菜刀很锋利。', 7, 168, 1, 130.6, 178.6, NULL, 4000, 16, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(646, '猪邪鬼', 3, 0, '会读人心，爱恶作剧。个性乖僻，明明喜欢吃杂粮却爱唱反调说不挑食。', 7, 169, 1, 127.7, 158.2, NULL, 4000, 8, 0, 1, 'normal', '{"hunt":{"sites":[2]},"fail":[646],"specialFeeding":true}', '{"interval":0,"times":3,"picky":[1]}', NULL, NULL, 1788143395111, NULL),
(647, '朱雀猪', 6, 2, '传说中守护着南方的猪。讲究排场很浮华，对自己通红的鸡冠与翅膀很自豪。似乎不想和凤凰混为一谈。', 7, 170, 1, 126.9, 179.2, NULL, 10000, 6, 0, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.213535}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[3]}', '{"requirements":"成猪时间09:00:00-14:59:59","tips":null}', '["似乎守护着四方","好像与古代中国思想有关","好像都有象征的颜色","好像很挑食","好像喜欢以前的时刻表"]', 1788143395111, NULL),
(648, '玄武猪', 6, 2, '传说中守护着北方的猪。掌管水，象征色是黑色。与缠绕在身上的蛇一心同体不分开。', 7, 171, 1, 127.9, 183.3, NULL, 10000, 6, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[8]}', '{"requirements":"成猪时间21:00:00-02:59:59","tips":null}', '["似乎守护着四方","好像与古代中国思想有关","好像都有象征的颜色","好像很挑食","好像喜欢以前的时刻表"]', 1788143395111, NULL),
(649, '白虎猪', 6, 2, '传说中守护着西方的猪。个性勇猛血气方刚。外表和实际年龄不符，岁数似乎很大了。', 7, 172, 1, 126.9, 179.2, NULL, 10000, 6, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[1]}', '{"requirements":"成猪时间15:00:00-20:59:59","tips":null}', '["似乎守护着四方","好像与古代中国思想有关","好像都有象征的颜色","好像很挑食","好像喜欢以前的时刻表"]', 1788143395111, NULL),
(650, '青龙猪', 6, 1, '传说中守护着东方的猪。象征色常常被认为是蓝色其实是绿色的，掌管树木植物。', 7, 173, 1, 126.9, 179.2, NULL, 10000, 6, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[2]}', '{"requirements":"成猪时间03:00:00-08:59:59","tips":null}', '["似乎守护着四方","好像与古代中国思想有关","好像都有象征的颜色","好像很挑食","好像喜欢以前的时刻表"]', 1788143395111, NULL),
(651, '玫瑰猪', 4, 4, '穿着玫瑰设计的礼服外表很华丽。特别是用玫瑰香气熟成的腹部肉最好吃。5月的猪。', 7, 174, 1, 128.2, 180.8, NULL, 3500, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[5]}', NULL, NULL, 1788143395111, NULL),
(652, '高丽菜猪', 3, 5, '层层重叠的叶子保护着身体。蓬松柔软的叶子可以代替棉被，所以常常在睡觉。5月的猪。', 7, 175, 1, 127.7, 177.6, NULL, 3000, 24, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(653, '雨伞猪', 3, 5, '穿着鲜艳的雨衣即使在雨天也要开开心心。下雨的话只要哼著歌心情就会变好。6月的猪。', 7, 176, 1, 127.7, 167.7, NULL, 3000, 8, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(654, '萤火虫猪', 4, 3, '原本性格腼腆，后来进化成借由让屁股发光与其他猪成功交流。有翅膀但不会飞。6月的猪。', 7, 177, 1, 129.5, 178.6, NULL, 4500, 16, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":2,"times":2,"picky":[4]}', NULL, NULL, 1788143395111, NULL),
(655, '茶釜猪', 5, 3, '身体是茶釜，特技会走钢索，是只多才多艺的猪。如果让他表演杂耍或许可以帮养猪场赚钱。', 7, 178, 1, 131.7, 186.1, NULL, 6500, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[4]}', NULL, NULL, 1788143395111, NULL),
(656, '地藏猪', 4, 2, '听说在外面很冷的时候善待他的话，他就会回礼给你，会将食物或钱财放在你家门口。', 7, 179, 1, 131.6, 170.6, NULL, 4500, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[1]}', NULL, NULL, 1788143395111, NULL),
(657, '一寸猪师', 4, 1, '非常小的猪。因为想知道自己成猪了为什么还是这么小，于是就踏上寻找万宝槌之旅坐上了卡车。', 7, 180, 1, 129.7, 175.2, NULL, 4000, 11, 1, 1, 'normal', '{"hunt":{"sites":[98],"prob":{"any":{"99":0.0017354389021898},"same":{"99":0.0020359413661165}}},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(658, '金鱼猪', 4, 4, '透过品种改良出生的猪。不用鳃呼吸也不会游泳。尾鳍和头上的疙瘩是它最有魅力的地方。7月的猪。', 7, 181, 1, 131.6, 211.9, NULL, 4000, 24, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[2,8]}', NULL, NULL, 1788143395111, NULL),
(659, '冰淇淋猪', 3, 5, '非常怕热，要小心头上和身体的冰会融化。想住在很大的冷冻库里。7月的猪。', 7, 182, 1, 125.9, 170.6, NULL, 3000, 13, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(660, '宙斯猪', 6, 3, '全知全能的猪。对美猪非常没辙，常常到处拈花惹草惹麻烦。哥哥是黑帝斯猪和波赛顿猪。', 7, 183, 1, 127.3, 225.7, NULL, 10000, 12, 0, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.17544857142857}}},"specialFeeding":true}', '{"interval":0.5,"times":5,"picky":[]}', '{"requirements":"成猪时上次出货末子","tips":"只能喂食5次"}', '["似乎会分歧成三兄弟","上一刻出货的猪似乎很重要","星系的位置似乎很重要","长男好像不擅长恋爱","老幺好像爱拈花惹草"]', 1788143395111, NULL),
(661, '波赛顿猪', 6, 3, '司掌海洋和地震的猪。是黑帝斯猪的弟弟，宙斯猪的哥哥。因为与猪杜莎有不见光的关系，导致她的头发变成了蛇。', 7, 184, 1, 130.2, 230.5, NULL, 10000, 12, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0.5,"times":8,"picky":[]}', '{"requirements":"成猪时上次出货次子","tips":"只能喂食8次"}', '["似乎会分歧成三兄弟","上一刻出货的猪似乎很重要","星系的位置似乎很重要","长男好像不擅长恋爱","老幺好像爱拈花惹草"]', 1788143395111, NULL),
(662, '黑帝​斯猪', 6, 3, '支配冥界的猪。是波赛顿猪和宙斯猪的哥哥。和弟弟们不同，对恋爱不熟练，强行掠夺少女当他的妻子。', 7, 185, 1, 130.7, 232.2, NULL, 10000, 12, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0.5,"times":9,"picky":[]}', '{"requirements":"成猪时上次出货长子","tips":"只能喂食9次"}', '["似乎会分歧成三兄弟","上一刻出货的猪似乎很重要","星系的位置似乎很重要","长男好像不擅长恋爱","老幺好像爱拈花惹草"]', 1788143395111, NULL),
(663, '凤梨猪', 3, 5, '有点在意人们争论是否能使用它来做成料理。肉质软嫩似乎是受到了水果成分的影响。8月的猪。', 7, 188, 1, 125.9, 167.8, NULL, 3000, 8, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(664, '救生猪', 4, 3, '为了守护岸边安全，每天都在锻炼的救命专家。猪猪们玩水时也会睁大眼睛监视着他们。8月的猪。', 7, 189, 1, 131.5, 194.5, NULL, 4500, 20, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[2,7]}', NULL, NULL, 1788143395111, NULL),
(665, '阿尔卑斯山的猪猪', 4, 1, '开朗活泼但有点小固执的猪。喜爱大自然，因为想回到自己生长的山中所以有点想家。', 7, 190, 1, 127.9, 167.1, NULL, 4500, 16, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[1,2]}', NULL, NULL, 1788143395111, NULL),
(666, '克拉拉小姐猪', 4, 5, '某个地方的大小姐猪。身体不好行动不便，因为想到猪猪小屋外面看看所以就开始复健并且慢慢可以走路了。', 7, 191, 1, 131.7, 199, NULL, 5000, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[7,8]}', NULL, NULL, 1788143395111, NULL);

INSERT INTO pigs (
  p_no, name, rare, color, description,
  atlas_type, atlas_index, atlas_visible,
  weight_small, weight_big,
  rent, price, lifespan, graze, special, status,
  acquisition, feeding, breeding_guide, hints, updated_at, updated_by
) VALUES
(667, '欧西里斯猪', 6, 4, '因为弟弟的叛乱曾经一度被出货，幸好妹妹们帮他做成木乃伊才得以复活。他是冥界的审判神，也是植物之神。', 7, 192, 1, 123.9, 183, NULL, 10000, 9, 0, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.27340333333333}}},"specialFeeding":true}', NULL, '{"requirements":"性别必须是公猪；便便数量=1","tips":"清空猪圈、就留1-2个猪，撤掉便便采集器，攒够便便数量，把其余的猪出货即可"}', '["兄弟姐妹间似乎会结婚","需要招唤神圣粪金龟吗","跟性别似乎有关","出生顺序似乎是关键","手足关系似乎很错综复杂"]', 1788143395111, NULL),
(668, '伊西斯猪', 6, 4, '四个手足中排行第二，是哥哥欧西里斯猪的妻子。为了被弟弟出货的丈夫四处奔波，拥有坚强的意志力。', 7, 193, 1, 123.9, 183, NULL, 10000, 9, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', NULL, '{"requirements":"性别必须是母猪；便便数量=2","tips":"清空猪圈、就留1-2个猪，撤掉便便采集器，攒够便便数量，把其余的猪出货即可"}', '["兄弟姐妹间似乎会结婚","需要招唤神圣粪金龟吗","跟性别似乎有关","出生顺序似乎是关键","手足关系似乎很错综复杂"]', 1788143395111, NULL),
(669, '赛特猪', 6, 4, '掌管沙漠和战争的狂暴之神。是最小妹妹奈芙蒂斯猪的丈夫。疯狂嫉妒哥哥就出货他抢夺宝座，没想到哥哥却复活了。', 7, 194, 1, 123.9, 183, NULL, 10000, 9, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', NULL, '{"requirements":"性别必须是公猪；便便数量=3","tips":"清空猪圈、就留1-2个猪，撤掉便便采集器，攒够便便数量，把其余的猪出货即可"}', '["兄弟姐妹间似乎会结婚","需要招唤神圣粪金龟吗","跟性别似乎有关","出生顺序似乎是关键","手足关系似乎很错综复杂"]', 1788143395111, NULL),
(670, '奈芙蒂斯猪', 6, 4, '最小的妹妹，是哥哥赛特猪的妻子。对欧西里斯猪有点心意。跟姐姐一起合作复活被出货的欧西里斯猪，是死者的守护神。', 7, 195, 1, 123.9, 183, NULL, 10000, 9, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', NULL, '{"requirements":"性别必须是母猪；便便数量=4","tips":"清空猪圈、就留1-2个猪，撤掉便便采集器，攒够便便数量，把其余的猪出货即可"}', '["兄弟姐妹间似乎会结婚","需要招唤神圣粪金龟吗","跟性别似乎有关","出生顺序似乎是关键","手足关系似乎很错综复杂"]', 1788143395111, NULL),
(671, '赏月猪', 4, 5, '为了庆祝饲料丰收，所以自己也扮成月亮举办赏月活动。小猪们也都很喜欢吃月见团子。9月的猪。', 7, 196, 1, 127.9, 198.8, NULL, 4500, 15, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[3,6]}', NULL, NULL, 1788143395111, NULL),
(672, '书虫猪', 3, 2, '一旦开始读书就停不下来的书虫猪猪。也会悄悄地借场主的书，每天晚上都很勤奋地读。9月的猪。', 7, 197, 1, 126.8, 173.9, NULL, 3500, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(673, '茄子猪', 3, 5, '太喜欢茄子所以扮成这模样还被烤了，自己还撒上了柴鱼和葱花觉得很好玩。10月的猪。', 7, 198, 1, 126.3, 170.2, NULL, 3500, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[4]}', NULL, NULL, 1788143395111, NULL),
(674, '枫红猪', 4, 4, '和服上的枫叶和脸颊被秋风染红了。秋天结束时就会和枫叶一起美丽地离去。10月的猪。', 7, 199, 1, 130.6, 180, NULL, 4000, 18, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(675, 'Dr.哲基尔猪', 4, 2, '个性敦厚且绅士的博士。为了试药将分离善恶之心的药混入疫苗。结果没打成宣告实验失败。', 7, 200, 1, 127.9, 181.5, NULL, 4500, 20, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(676, 'Mr.海德猪', 4, 2, '个性粗暴且危险的猪。似乎是被场主喂药之后结果只分离出恶意之心而独立存在的一个个体。', 7, 201, 1, 127.9, 181.4, NULL, 4500, 20, 0, 1, 'normal', '{"hunt":{"sites":[0]},"fail":[675],"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(677, '天照大猪', 6, 5, '因为粗暴的弟弟到处作乱而躲起来不出门，但好奇外面的祭典才因此现身的太阳神。很期待新米供品。', 7, 202, 1, 123.9, 191.4, NULL, 10000, 8, 0, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.17544857142857}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[1]}', '{"requirements":"成猪时间06:00:00-17:59:59；同场必须有6头以上的猪","tips":"只吃杂粮"}', '["出没时间好像有关连呢","好像会被周围环境影响呢","有一个喜欢的食物","好像因为父亲净身而诞生的样子","姐姐似乎不想见到弟弟"]', 1788143395111, NULL),
(678, '月读猪', 6, 5, '统治夜晚的神。引发了某事件，虽然建立起谷物的起源但也因为这样与姐姐有了距离。', 7, 203, 1, 123.9, 191.5, NULL, 10000, 8, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[1]}', '{"requirements":"成猪时间18:00:00-05:59:59；同场不能有已经其他的猪","tips":"只吃杂粮"}', '["出没时间好像有关连呢","好像会被周围环境影响呢","有一个喜欢的食物","好像因为父亲净身而诞生的样子","姐姐似乎不想见到弟弟"]', 1788143395111, NULL),
(679, '猪佐之男命', 6, 5, '太过粗暴以致被流放的神。途中遇到老夫妇拜托他消灭怪物。并娶了从危机中解救出来的稻田女神。', 7, 204, 1, 123.9, 191.3, NULL, 10000, 8, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[1]}', '{"requirements":"同场必须有1头老猪；同场必须有2头任意品种的猪","tips":"只吃杂粮"}', '["出没时间好像有关连呢","好像会被周围环境影响呢","有一个喜欢的食物","好像因为父亲净身而诞生的样子","姐姐似乎不想见到弟弟"]', 1788143395111, NULL),
(680, '肉包猪', 3, 5, '钻进蒸笼流着肉汁的汗体验三温暖的感觉。到了出货目的地或许会引起一场争夺战。11月的猪。', 7, 205, 1, 128.6, 169.7, NULL, 3500, 11, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(681, '火鸡猪', 3, 1, '为了庆祝感恩节而变成火鸡的猪。没有察觉到如果自己进入会场很有可能会被抓去整只烤。11月的猪。', 7, 206, 1, 127.1, 172.7, NULL, 3500, 16, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":2,"picky":[1,5]}', NULL, NULL, 1788143395111, NULL),
(682, '姜饼猪', 3, 3, '每到圣诞节就会浑身散发着香味来到这里。还会偷偷瞒着场主发饼干给大家。12月的猪。', 7, 207, 1, 127.5, 170.2, NULL, 3000, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[5]}', NULL, NULL, 1788143395111, NULL),
(683, '锅锅猪', 3, 5, '冬天的人气王，靠近他就暖呼呼的。最引为傲的火锅里放了讲究的蔬菜之外好像还加入了上等猪肉。12月的猪。', 7, 208, 1, 128.6, 173.9, NULL, 3000, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[2,7]}', NULL, NULL, 1788143395111, NULL),
(684, '科学怪猪', 4, 4, '以一头理想的猪被创造出来，但因为太丑陋以致被众人嫌弃的怪猪。想要去猪猪广场寻找另一半。', 7, 209, 1, 130.6, 181.4, NULL, 4000, 20, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(685, '木乃伊猪', 3, 2, '从层层缠绕的绷带缝隙露出窥看的眼睛有点恐怖。是否是真的木乃伊还有肉质如何都是个谜。对于干燥的皮肤很困扰。', 7, 210, 1, 125.9, 170.2, NULL, 3000, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(686, '奥丁猪', 6, 6, '掌管战争与死亡的猪。一边侧目看着拍卖场中互相争夺的场主们一边为要出品的小猪们提供庇护。', 7, 214, 1, 129.9, 183.5, NULL, 10000, 9, 0, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.27340333333333}}},"specialFeeding":true}', NULL, '{"requirements":"成猪前出货的猪由拍卖获得；成猪时体重数值含有9（如139.5、145.9）","tips":"最好抓一个31kg的，成猪就是129kg"}', '["似乎需要出货活祭品","各擅长的领域似乎不同","好像和北欧神殿有关","在与巨人的战斗中很活跃的样子","成猪时好像需要神秘的数字"]', 1788143395111, NULL),
(687, '索尔猪', 6, 6, '掌管雷霆与农耕的猪。力气很大性格豪爽。对猪猪们很亲切，当遇到生病或食物不足的时候好像会出手帮忙。', 7, 215, 1, 129.8, 183.8, NULL, 10000, 9, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', NULL, '{"requirements":"成猪前出货的猪必须是病猪；成猪时体重数值含有9（如139.5、145.9）","tips":"最好抓一个31kg的，成猪就是129kg"}', '["似乎需要出货活祭品","各擅长的领域似乎不同","好像和北欧神殿有关","在与巨人的战斗中很活跃的样子","成猪时好像需要神秘的数字"]', 1788143395111, NULL),
(688, '弗雷猪', 6, 6, '掌管丰饶与和平的猪。拥有异于常人的美貌。会帮忙媒合不错的配种对象，在猪猪当中很有人气。', 7, 216, 1, 130, 183.9, NULL, 10000, 9, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', NULL, '{"requirements":"成猪前出货的猪由配种获得；成猪时体重数值含有9（如139.5、145.9）","tips":"最好抓一个31kg的，成猪就是129kg"}', '["似乎需要出货活祭品","各擅长的领域似乎不同","好像和北欧神殿有关","在与巨人的战斗中很活跃的样子","成猪时好像需要神秘的数字"]', 1788143395111, NULL),
(689, '风筝猪', 3, 5, '说到新年的娱乐活动就想到这只猪。太重了当然飞不起来，所以梦想着有一天能飞上天空。1月的猪。', 7, 217, 1, 126.9, 170.3, NULL, 3000, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(690, '初梦猪', 5, 3, '集吉利于一身的猪。新年如果能梦到这只猪，接下来这一年或许就能出货满满喔。1月的猪。', 7, 218, 1, 130.7, 173.7, NULL, 5500, 20, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[1,2]}', NULL, NULL, 1788143395111, NULL),
(691, '惠方卷猪', 4, 4, '扮成立春时节吃的寿司卷的猪，据说吃了会招来好事。卡车开去的方位会是吉位吗。2月的猪。', 7, 219, 1, 129.7, 170.4, NULL, 4000, 23, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[2,3]}', NULL, NULL, 1788143395111, NULL),
(692, '冰柱猪', 3, 5, '身上的积雪融化但因身体表面又结冻的关系结果形成冰柱的猪。冰柱的最长纪录持续更新中。2月的猪。', 7, 220, 1, 125.9, 169, NULL, 3000, 10, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(693, '勇者叉烧', 4, 1, '偶然捡到圣剑就被当成英雄对待因而得意忘形。因为是捡来的，剑当然拔不出来所以只能当作秘密。', 7, 221, 1, 130.2, 203.9, NULL, 5000, 16, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":2,"picky":[7,8]}', NULL, NULL, 1788143395111, NULL),
(694, '魔导士糖醋肉', 3, 1, '因为被家人当作神童对待便自称是魔导士的猪。虽然还不会使用魔法，但觉得只要努力就会用了。', 7, 222, 1, 126.8, 170.3, NULL, 4000, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[2,4]}', NULL, NULL, 1788143395111, NULL),
(695, '战士猪排', 3, 0, '从无数的饲料争夺战中幸存下来的以体力自豪的猪。但是不擅长应付暴力，为了保护自己所以一直拿着盾牌。', 7, 223, 1, 128.6, 173.9, NULL, 4000, 18, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(696, '侯丽猪', 4, 3, '为了庆祝春天到访而从某个国家来的猪。如果和他打招呼，不管是谁他都会洒上彩色粉末。3月的猪。', 7, 224, 1, 129.7, 164.2, NULL, 4000, 11, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[2]}', NULL, NULL, 1788143395111, NULL),
(697, '圣派翠克猪', 3, 4, '全身包裹着绿色物品的派对猪。特色是就连河川的水也要染成绿色那样盛大地庆祝。3月的猪。', 7, 225, 1, 126.1, 173.3, NULL, 3500, 17, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":1,"picky":[5]}', NULL, NULL, 1788143395111, NULL),
(698, '丰臣猪吉', 6, 1, '农民出身，后来崛起成为统一全国养猪场的将军猪。爱好奢华拥有非凡的野心。', 7, 226, 1, 123.9, 182.8, NULL, 10000, 8, 0, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.11318193277147}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[1]}', '{"requirements":"成猪前周围必须有两头及以上的同色系猪（肉）","tips":"只吃杂粮；地上摆放任何食物"}', '["好像无法忘记年少时期的味道","无论如何好像都要统一周遭","似乎有成为天下下人的野心","好像想要奢侈过剩","好像想要没收刀子"]', 1788143395111, NULL),
(699, '羽柴猪吉', 4, 1, '尽管是农民出身，但凭着稳步建立的功绩成为了战国武将的猪。当正要出名的时候就被出货了。', 7, 227, 1, 120, 120, NULL, 5000, 8, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', NULL, NULL, NULL, 1788143395111, NULL),
