(900, '老猪', 1, 1, '错过了出货时机的猪。/没人知道出货卡车要开去何方。', 6, 5, 1, 123.9, 160, NULL, 0, 0, 0, 0, 'normal', '{"hunt":{"sites":[0]}}', NULL, NULL, NULL, 1788143395111, NULL),
(901, '病猪', 1, 1, '会不停地传染细菌给其他的猪。', 6, 6, 1, 123.9, 160, NULL, 0, 0, 0, 0, 'normal', '{"hunt":{"sites":[0]}}', NULL, NULL, NULL, 1788143395111, NULL),
(904, '国王猪', 5, 1, '猪场主的养成技巧已经到了极致。只会在真正的养猪大师面前出现的神猪。', 6, 13, 0, 175, 200, 18000, 20000, 40, 1, 0, 'hidden', '{"hunt":{"sites":[6],"prob":{"any":{"6":0.035714285714286},"same":{"6":1}}},"specialFeeding":true}', '{"interval":2,"times":15,"picky":[6]}', '{"requirements":"成猪前体重限制 ≥128.0 kg","tips":null}', NULL, 1788143395111, NULL),
(905, '阿尔伯特(假名)', 4, 1, '没达到真正的养猪大师所以堕落而成的猪。不再以原来的名字示人所以用假名。', 6, 14, 0, 132.5, 191.1, 7000, 8000, 24, 0, 0, 'hidden', '{"hunt":{"sites":[0]},"fail":[904],"specialFeeding":true}', '{"interval":1,"times":4,"picky":[6]}', NULL, NULL, 1788143395111, NULL),
(920, '皇后猪', 5, 1, '在一个能完美掌握品种培育的场主面前才会出现的高贵猪。对养育自己的场主很尊敬。', 6, 16, 0, 180, 205, 18000, 20000, 40, 1, 0, 'hidden', '{"hunt":{"sites":[5],"prob":{"any":{"5":0.018518518518519},"same":{"5":1}}},"specialFeeding":true}', '{"interval":2,"times":15,"picky":[]}', '{"requirements":"成猪前体重限制 ≥138.0 kg","tips":null}', NULL, 1788143395111, NULL),
(921, '伊丽莎白(假名)', 4, 1, '应该会出现在完美的场主面前，但不知道哪个环节出错而没落的猪。取了一个假名来隐藏身份。', 6, 17, 0, 132.5, 191.1, 7000, 8000, 24, 0, 0, 'hidden', '{"hunt":{"sites":[0]},"fail":[920]}', '{"interval":1,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1000, '木下猪吉郎', 3, 1, '虽是农民出身但拥有野心。想要出人头地的第一步是去侍奉武士，但还在负责帮主公暖鞋时就被出货了。', 7, 228, 1, 120, 120, NULL, 3000, 8, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[1]}', NULL, NULL, 1788143395111, NULL),
(1001, '铃兰猪', 3, 5, '最吸引人的一点就是摇曳摆动的尾巴。猪肉本身没有毒，不过与他的外表相反其实是很毒舌的一只猪。4月的猪。', 7, 229, 1, 126.8, 172.1, NULL, 3000, 15, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[1,5]}', NULL, NULL, 1788143395111, NULL),
(1002, '泼水猪', 3, 3, '泰国传统泼水节的猪。不管遇到谁他都会泼水，所以猪猪小屋内的猪猪们都与他保持着距离。4月的猪。', 7, 230, 1, 126.8, 160.3, NULL, 3000, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[1,2]}', NULL, NULL, 1788143395111, NULL),
(1003, '猪之子', 5, 1, '有很多人目击过，却没有人捕获过而且还祭出了悬赏金的传闻中的猪。最后终于在猪猪小屋被发现还被出货了。', 7, 231, 1, 129.8, 178.9, NULL, 9000, 8, 1, 1, 'normal', '{"hunt":{"sites":[98],"prob":{"any":{"99":0.0017354389021898},"same":{"99":0.0020359413661165}}},"specialFeeding":true}', '{"interval":1,"times":2,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1004, '卓柏卡布猪', 3, 0, '一心想着要成为与众不同的猪而最终也改变了外貌。被谣传说会袭击家畜还会吸血这种没有根据的传言觉得很困扰。', 7, 232, 1, 128.6, 172.8, NULL, 4000, 16, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1005, '大猪怪', 4, 0, '传闻从多次目击到的资讯来看，很可能是跟熊搞混了。为了不吓到别人所以很小心谨慎。', 7, 233, 1, 134.4, 184.1, NULL, 5000, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":6,"picky":[4]}', NULL, NULL, 1788143395111, NULL),
(1006, '瓢虫猪', 3, 4, '彻底变成象征好运瓢虫的猪。常常看到他想要飞向太阳。5月的猪。', 7, 234, 1, 125.9, 159.2, NULL, 3000, 10, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[1]}', NULL, NULL, 1788143395111, NULL),
(1007, '捡贝猪', 3, 3, '专门在退潮时捡拾贝类的猪。肤色是晒太阳晒来的。会利用敏锐的嗅觉找出贝类。5月的猪。', 7, 235, 1, 125.6, 170.2, NULL, 3000, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1008, '大卫猪王', 6, 2, '从牧羊人出身到变成大帝国第2代的国王。犯下了抢夺部下之妻的罪过。之后生了所罗猪王。', 7, 236, 1, 130.1, 179.6, NULL, 10000, 10, 0, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.213535}}},"specialFeeding":true}', '{"interval":0,"times":8,"picky":[]}', '{"requirements":"成猪前体重限制 ≤108.0 kg","tips":"最近一只出货猪体重 > 成猪前体重+20 kg；只能喂食8次"}', '["前一刻出货的猪似乎是关键","好像想要葬送比自己大的敌人","弹琴吟诗音乐很精湛的样子","好像想要保持匀称的脸和身材","好像是从牧羊人熬出头的样子"]', 1788143395111, NULL),
(1009, '战士大卫猪', 4, 2, '从牧羊人变成战士都没输过。他的好运气和人气让他被主君嫉妒，好几次差点被杀，但每次都逃过一劫。', 7, 237, 1, 120, 120, NULL, 5000, 10, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0,"times":8,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1010, '牧羊大卫猪', 3, 2, '很会弹竖琴的美少年猪。进货开始身上就散发着一股特殊的气质。有勇气对抗比自己强壮高大的猪。', 7, 238, 1, 120, 120, NULL, 3000, 10, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0,"times":8,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1011, '仲夏节猪', 4, 5, '为庆祝欧洲夏天到来的祭典猪。喜欢跳着童谣小青蛙的舞蹈和演奏乐器。6月的猪。', 7, 240, 1, 130, 184.2, NULL, 4500, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[3,5]}', NULL, NULL, 1788143395111, NULL),
(1012, '爸爸猪', 3, 3, '平时不好意思传达对爸爸的感谢，就让这只猪带个礼物帮忙传达吧。6月的猪。', 7, 241, 1, 127.7, 170.8, NULL, 3500, 13, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1013, '狗猪', 3, 3, '想要当桃太郎猪的伙伴而变成了一只狗。个性很忠诚又勇敢。因为戴着嘴套所以鼻子不管用。', 7, 242, 1, 127.7, 170.2, NULL, 3000, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1014, '猴子猪', 3, 2, '想要支持桃太郎猪而变成了一只猴子。脑筋转得很快个性机灵。但还是有猪蹄所以不灵巧。', 7, 243, 1, 127.7, 170.5, NULL, 3000, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[3,6]}', NULL, NULL, 1788143395111, NULL),
(1015, '雉鸡猪', 3, 2, '想要成为桃太郎猪的力量而变成了一只雉鸡。拥有宽广的视野和先见之明。因为是猪所以无法飞到空中。', 7, 244, 1, 127.7, 160, NULL, 3000, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[1]}', NULL, NULL, 1788143395111, NULL),
(1016, '皇帝刘邦猪', 6, 4, '从一个醉汉平民摇身一变成了大国初代皇帝的猪。很有猪望，加上柔软的政策，最终实现了统一天下的丰功伟业。', 7, 245, 1, 125.9, 182.3, NULL, 10000, 8, 1, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.27340333333333}}},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[1,3,4]}', '{"requirements":null,"tips":"一定要放牧及成猪时要在放牧场；成猪前有最少三种不同颜色的猪在旁；只吃杂粮、红薯、玉米"}', '["喜欢吃的好像有3种","似乎很喜欢酒","似乎有传闻说其实是龙之子","透过进攻北迁才出人头地的样子","会率领着乌合之众出现的样子"]', 1788143395111, NULL),
(1017, '军队长刘邦猪', 4, 4, '周围的人推举他成为率兵的领导者。集结了一些士兵正获得了不错的战果后便被左迁至偏远地方。', 7, 246, 1, 120, 120, NULL, 5000, 8, 1, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[1,3,4]}', NULL, NULL, 1788143395111, NULL),
(1018, '醉鬼刘邦猪', 3, 4, '管理这片区域的猪头目。喜欢喝酒，赊账还理所当然地欠钱不还。不可思议的是很有猪望，总是会有猪聚集在他身边。', 7, 247, 1, 120, 120, NULL, 3000, 8, 1, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[1,3,4]}', NULL, NULL, 1788143395111, NULL),
(1019, '牵牛花猪', 3, 5, '成长途中被藤蔓缠绕身体不知不觉开满花的猪。早睡早起很耐热。7月的猪。', 7, 248, 1, 126.8, 173.9, NULL, 3000, 18, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1020, '卖风铃的猪', 4, 1, '随着清澈的铃铃声沿街叫卖著风铃的猪。出货的时候也以为是要去卖风铃了。7月的猪。', 7, 249, 1, 129.5, 181.4, NULL, 4000, 20, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[4]}', NULL, NULL, 1788143395111, NULL),
(1021, '蚊子猪', 3, 2, '闷热的时候就会出现。虽然不会吸血，但一听到他的嗡嗡声就觉得很烦人，大家都对他敬而远之。8月的猪。', 7, 251, 1, 127.7, 170.2, NULL, 3000, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1022, '砂堡猪', 3, 3, '总是一个人在沙滩上玩。梦想是和朋友一起在海边堆城堡。现在正在努力结交朋友。8月的猪。', 7, 252, 1, 125.9, 172.9, NULL, 3500, 16, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1023, '爱因猪坦', 4, 5, '身为理论物理学家的猪，常发表各种理论冲击了猪界的物理学。有时会与牛顿猪互相讨论。', 7, 253, 1, 127.9, 174.6, NULL, 4000, 10, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1024, '哥伦布猪', 4, 1, '第一个发现美洲大陆的欧洲白猪。他坐上卡车，接下来的目标是印度…。', 7, 254, 1, 130.6, 171.3, NULL, 4000, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[1,3]}', NULL, NULL, 1788143395111, NULL),
(1025, '亚伯拉罕·林肯猪', 6, 5, '有一句名言是猪有、猪治、猪享。目的是创建一个全部猪猪都平等自由的猪场。', 7, 255, 1, 137.4, 206.7, NULL, 10000, 6, 1, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.17544857142857}}},"specialFeeding":true}', '{"interval":0,"times":16,"picky":[]}', '{"requirements":null,"tips":"只能喂食16次；一定要放牧；成猪时必须单独在小屋内"}', '["会到处奔走呢","想要解放猪猪们呢","数字好像是关键","有一场很吸引猪的演说呢","好像是个高个子"]', 1788143395111, NULL),
(1026, '律师林肯猪', 4, 5, '以诚信和公平著称的律师。猪猪们都很信任他。他一边学习法律，一边也想着要成为政治家。', 7, 256, 1, 120, 120, NULL, 5000, 6, 1, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0,"times":16,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1027, '农夫林肯猪', 3, 5, '会帮忙父亲种田耕农。身材高大强壮，但比起耕农他更爱将时间花在读书上。', 7, 257, 1, 120, 120, NULL, 3000, 6, 1, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0,"times":16,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1028, '牡蛎猪', 3, 5, '想要推广庆祝牡蛎解禁的牡蛎节。擅长剥牡蛎壳。像布丁一样柔软一碰到会抖动。9月的猪。', 7, 258, 1, 128.6, 161, NULL, 5000, 14, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[2]}', NULL, NULL, 1788143395111, NULL),
(1029, '和平猪', 4, 2, '想要和平解决天天爆发的饲料争夺事件的国际和平日的猪。饲料有一半都喂鸽子的样子。9月的猪。', 7, 259, 1, 127.9, 169.2, NULL, 3000, 21, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":1,"picky":[1]}', NULL, NULL, 1788143395111, NULL),
(1030, '巴科罗面具猪', 3, 3, '菲律宾的祭典猪，笑脸面具让人印象深刻。个性积极乐观，即使面对困境也不忘微笑。10月的猪。', 7, 260, 1, 126.7, 170.3, NULL, 3500, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":2,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1031, '热气球猪', 3, 2, '不懂什么原理浮起来的神秘的猪。梦想是集合同样的猪开一场热气球嘉年华。10月的猪。', 7, 261, 1, 125.9, 160.9, NULL, 3500, 14, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[1]}', NULL, NULL, 1788143395111, NULL),
(1032, '猪本武藏', 4, 3, '号称生涯无败的二刀流剑圣猪。他所著的剑术奥义的兵书因为字太丑，除了本人没人看得懂。', 7, 262, 1, 132.3, 168.7, NULL, 5000, 20, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":6,"picky":[1]}', NULL, NULL, 1788143395111, NULL),
(1033, '佐佐木猪次郎', 4, 5, '自创剑术蹄返的剑客猪。为锻炼剑术周游各地结果被带到了猪猪小屋。', 7, 263, 1, 130.5, 180, NULL, 4500, 18, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1034, '薄酒莱葡萄酒猪', 4, 5, '鼻子很灵敏的优秀侍酒师。每年都会检查薄酒莱新酒看看葡萄的收成情况。11月的猪。', 7, 264, 1, 129.7, 207.6, NULL, 5000, 20, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[2,8]}', NULL, NULL, 1788143395111, NULL),
(1035, '七五猪', 3, 1, '看起来天真无邪其实是想要千岁饴于是假装成小猪去祈福参拜七五三节的迷你猪(已成猪)。11月的猪。', 7, 265, 1, 128.7, 183.1, NULL, 3500, 15, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[5,7]}', NULL, NULL, 1788143395111, NULL),
(1036, '查士猪尼大帝', 6, 3, '贫穷农民出身的皇帝。还汇整了当时很难理解的法律。由于曾经身为劳动者，所以也有永不睡觉的帝王的称号。', 7, 266, 1, 123.9, 189.5, NULL, 10000, 6, 0, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.17544857142857}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', '{"requirements":"成猪时间限制 20:00:00-07:59:59；周围必须有病猪；成猪时周围必须有2头母猪且只能有母猪（仅限红色星星的186图鉴）","tips":null}', '["好像完成了猪猪图鉴大全","目标好像是全图鉴勋章","好像是个会忘记睡觉的劳动者","似乎有贤妻支持着他","似乎会有流行疾病"]', 1788143395111, NULL),
(1037, '近卫兵伯多禄猪', 4, 3, '身为近卫兵的舅舅收养他当养子，他勤学出色也成为了近卫队长。刚担任皇帝护卫时就被出货了。', 7, 267, 1, 120, 120, NULL, 5000, 6, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', NULL, NULL, NULL, 1788143395111, NULL),
(1038, '农民伯多禄猪', 3, 3, '出生于地方的贫穷农民。身为近卫兵的舅舅说要来收养他，结果来不及收养他就被出货了。', 7, 268, 1, 120, 120, NULL, 3000, 6, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', NULL, NULL, NULL, 1788143395111, NULL),
(1039, '冬眠猪', 3, 3, '在冬天会停止活动进入冬眠状态，可是只要靠近饲料还是会马上吃掉。食欲不会休眠。12月的猪。', 7, 269, 1, 125.9, 172.7, NULL, 3000, 16, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1040, '双板滑雪猪', 3, 4, '冬天到了要挑战滑雪的猪。虽然是个新手但还是梦想着能跟仰慕的滑雪猪一起滑雪。12月的猪。', 7, 270, 1, 125.9, 170.3, NULL, 3000, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1041, '蚂蚁猪', 3, 2, '为了过冬孜孜不倦地在地底储存饲料。个性基本上都蛮认真的只是也有少部分比较偷懒的人。', 7, 271, 1, 128.6, 171.4, NULL, 3000, 14, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1042, '蟋蟀猪', 4, 5, '当下开心就OK的乐天派。总是不事先好好考虑未来的事，常常事后才求助于人。', 7, 272, 1, 129.7, 168.7, NULL, 4000, 20, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[2]}', NULL, NULL, 1788143395111, NULL),
(1043, '洪武帝猪元璋', 6, 6, '从严酷的环境中崛起出世，成为世界闻名出类拔萃的人物。政治上很关照庶民猪，更不断进行肃清行动。', 7, 276, 1, 123.9, 189.1, NULL, 10000, 8, 0, 1, 'normal', '{"hunt":{"sites":[99],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.27340333333333}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', '{"requirements":null,"tips":"只吃杂粮1次；独立在（小屋/放牧场）成猪；最近一只出货猪需吃过松露"}', '["似乎很独裁且肃清不停歇","似乎从赤贫一路登上皇帝地位","富有的猪似乎是肃清对象","似乎害怕被肃清而孤立他","似乎从赤贫生活中保住了性命"]', 1788143395111, NULL),
(1044, '红巾军猪元璋', 4, 0, '因占卜为契机加入了红巾军。军队的领导猪因为很喜欢他于是将女儿嫁给他，但在结婚前夕就被出货了。', 7, 277, 1, 120, 120, NULL, 5000, 8, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', NULL, NULL, NULL, 1788143395111, NULL),
(1045, '化缘和尚猪重八', 3, 0, '贫民出身，因为饥饿和瘟疫他失去了他的猪亲属。后来出家成为和尚四处化缘，但仍然过着贫穷的日子终日乞讨。', 7, 278, 1, 120, 120, NULL, 3000, 8, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', NULL, NULL, NULL, 1788143395111, NULL),
(1046, '火炉猪', 3, 2, '他是冬天猪猪小屋的救世主。劈哩啪啦燃烧着的火焰能让心情放松。如何变成这样的身体构造是个谜。1月的猪。', 7, 279, 1, 120, 120, NULL, 3500, 20, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1047, '圣火节猪', 4, 4, '苏格兰出身的维京海盗猪。以为是要去参加火祭的圣火节于是坐上了卡车。1月的猪。', 7, 280, 1, 130.1, 178.7, NULL, 4500, 16, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[3,4]}', NULL, NULL, 1788143395111, NULL),
(1048, '猪州蜜柑', 3, 5, '因为剥了一层皮的关系，蜜柑酸甜的浓烈香气又更上一层楼了。和暖桌猪很合得来。2月的猪。', 7, 281, 1, 125.9, 167.8, NULL, 3000, 8, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1049, '关东煮猪', 4, 3, '将讲究的汤汁满满吸附进去的关东煮猪。猪本身会烫，碰触的时候要小心烫伤。2月的猪。', 7, 282, 1, 129.7, 170.6, NULL, 4000, 24, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[2]}', NULL, NULL, 1788143395111, NULL),
(1050, '猪川豚十郎', 4, 0, '很有人气的歌舞伎演员猪。屋号是养豚屋。被豚十郎凝视的话，说不定可保整年无病无灾平安度过。', 7, 283, 1, 133.4, 192.7, NULL, 5000, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[7]}', NULL, NULL, 1788143395111, NULL),
(1051, '世阿弥陀猪', 4, 4, '能面底下的脸满是谜团的能乐猪。能巧妙地利用阴影变化脸部神韵以表达感情。', 7, 284, 1, 130.7, 181.8, NULL, 5000, 20, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[5]}', NULL, NULL, 1788143395111, NULL),
(1052, '猪太郎冠者', 4, 1, '狡猾的仆人猪。主人说是有毒的东西，他看破发现是松露而把它吃光光然后就被出货了。', 7, 285, 1, 132.8, 202.2, NULL, 5000, 14, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[8]}', NULL, NULL, 1788143395111, NULL),
(1053, '羔羊猪', 3, 3, '金黄色的羊毛覆盖在身上像一只羊的猪。有很旺盛的冒险精神，最近想挑战的是翱翔在天空。3月的猪。', 7, 286, 1, 128.6, 160.5, NULL, 3000, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[2]}', NULL, NULL, 1788143395111, NULL),
(1054, '法雅节猪', 4, 1, '于巴伦西亚的火之祭典中身穿民族服饰的猪。捧着花束打算要去参加献花游行…。3月的猪。', 7, 287, 1, 130.6, 180.9, NULL, 4500, 19, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[5]}', NULL, NULL, 1788143395111, NULL);

INSERT INTO pigs (
  p_no, name, rare, color, description,
  atlas_type, atlas_index, atlas_visible,
  weight_small, weight_big,
  rent, price, lifespan, graze, special, status,
  acquisition, feeding, breeding_guide, hints, updated_at, updated_by
) VALUES
(1055, '翠绿巨疣猪', 6, 6, '草木丛生的巨疣猪。长期经年累月下，他巨大的身体已长出苔藓，牙齿也变为枝枒。', 7, 288, 1, 125, 228.3, NULL, 10000, 40, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', '{"requirements":"成猪时间限制 08:00:00-16:59:59；必须在放牧场独立成猪","tips":"最少早上抓捕，不要超过9点"}', '["好像喜欢大草原喔","似乎最喜欢蓝天","好像有三种喜欢的食物呢","有很大的獠牙喔","好像喜欢晒太阳"]', 1788143395111, NULL),
(1056, '金牛猪', 3, 5, '传闻说是宙斯猪变身而成的。如果有发现喜欢的猪就会想把他带到猪猪广场。4月的猪。', 7, 289, 1, 126.6, 170.2, NULL, 3000, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[2,5]}', NULL, NULL, 1788143395111, NULL),
(1057, '浴佛节猪', 4, 5, '为庆祝释迦牟尼佛诞生而扮成白象的猪。一直很想喝花车上的甘茶。4月的猪。', 7, 290, 1, 130.7, 205.4, NULL, 4000, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[4,8]}', NULL, NULL, 1788143395111, NULL),
(1058, '梅菲斯特猪', 5, 0, '被炼金术士猪浮士德猪召唤出来的恶魔。用一辈子的松露去交换的话就能帮你实现所有愿望的样子。', 7, 291, 1, 139.7, 216.2, NULL, 8000, 20, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":6,"picky":[8]}', NULL, NULL, 1788143395111, NULL),
(1059, '浮士德猪', 4, 4, '贪婪的炼金术士猪。为了实现愿望召唤了恶魔梅菲斯特猪，但终究逃不过被出货的命运。', 7, 292, 1, 132.4, 180, NULL, 4500, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":6,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1060, '双子猪', 3, 1, '一开始进货时只有一头猪，实际上是双胞胎会交替长大。传说其中一个是不死之身。5月的猪。', 7, 295, 1, 128.6, 170.3, NULL, 3000, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1061, '圣依西多禄猪', 3, 3, '原本要去马德里的圣人节庆跳舞。实际上是想去摊贩吃吃喝喝。5月的猪。', 7, 296, 1, 125.8, 169.7, NULL, 3000, 11, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1062, '无耳猪', 6, 2, '出现在奄美的妖怪，会发出很强烈的臭味。双脚交叉行走可以避免死亡。', 7, 297, 1, 125.7, 188.6, NULL, 10000, 16, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', '{"requirements":"地上需要有便便","tips":"成猪在放牧场和小屋都可"}', '["爱吃的饲料好像有三种喔","好像会发出很强烈的臭味","感觉到有一股妖气呢","似乎来自日本南部","好像会在夜晚成群跑来跑去"]', 1788143395111, NULL),
(1063, '巨蟹猪', 3, 4, '离不开大螃蟹的猪。似乎把对方当家人非常照顾他。6月的猪。', 7, 298, 1, 126.9, 170.2, NULL, 3000, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1064, '印地太阳祭猪', 4, 3, '感谢收获和祈愿丰收的秘鲁仪式中担任皇帝一角的猪。坐上了神轿结果是卡车。6月的猪。', 7, 299, 1, 130.7, 184.1, NULL, 4000, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[4]}', NULL, NULL, 1788143395111, NULL),
(1065, '阿多斯猪', 4, 3, '三剑客里的领导者。为人诚实但是个酒鬼。喝醉之后坐上卡车出货去了。', 7, 300, 1, 129.7, 177.4, NULL, 4500, 14, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1066, '阿拉密斯猪', 4, 5, '三剑客的其中一人，是个多情猪。因为失恋决定走上圣职一途于是坐上卡车出货去了。', 7, 301, 1, 129.7, 177.4, NULL, 4500, 14, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[5]}', NULL, NULL, 1788143395111, NULL),
(1067, '波尔多斯猪', 4, 4, '三剑客的其中一人，喜欢华丽，爱慕虚荣。拥有怪力，为了比力气而坐上卡车出货去了。', 7, 302, 1, 131.8, 189.2, NULL, 4500, 14, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[7]}', NULL, NULL, 1788143395111, NULL),
(1068, '达太安猪', 5, 4, '一同与三剑客活动的年轻火枪手。还算受欢迎。为了出人头地毅然决然坐上卡车出货去了。', 7, 303, 1, 130.7, 172.5, NULL, 8000, 16, 0, 1, 'normal', '{"hunt":{"sites":[98],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.27340333333333}}},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[1]}', NULL, NULL, 1788143395111, NULL),
(1069, '半神卡玛普阿猪', 6, 3, '生气的话会变成恐怖大猪的半神，平时是这个模样。是个好女色的美男子。为了隐藏背上的硬毛所以披着披风。', 7, 305, 1, 127.5, 180.7, NULL, 10000, 32, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[]}', '{"requirements":"只能喂食5次；成猪前周围需要有母猪陪伴","tips":"成猪前周围不能有公猪"}', '["好像有喜欢的食物喔","好像想要维持苗条的体型","好像有在神话中登场","好像是从南方的岛屿过来的","好像会变成花花公子"]', 1788143395111, NULL),
(1070, '狮子猪', 3, 3, '拥有像狮子一样自豪的鬃毛，在猪猪小屋中很有人气。个性积极做什么事都全力以赴。7月的猪。', 7, 306, 1, 128.6, 170.6, NULL, 3000, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1071, '扶桑猪', 3, 3, '喜欢听着海浪声过着舒畅日子的夏威夷猪。跟冲浪猪感情很好。7月的猪。', 7, 307, 1, 126.8, 163.6, NULL, 3500, 20, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":2,"picky":[3]}', NULL, NULL, 1788143395111, NULL),
(1072, '处女猪', 3, 1, '丰饶的女神，平时性格温厚，一旦生气就会引发饥饿。是宙斯猪、波赛顿猪、黑帝斯猪的姐姐。8月的猪。', 7, 308, 1, 127.9, 170.2, NULL, 3000, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[1,5]}', NULL, NULL, 1788143395111, NULL),
(1073, '玉米猪', 3, 5, '饲料中广为人知的玉米的猪。烦恼是常被其他猪误认是饲料而被啃咬。8月的猪。', 7, 309, 1, 130, 172.1, NULL, 3000, 15, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[4]}', NULL, NULL, 1788143395111, NULL),
(1074, '哈姆雷特猪', 4, 4, '一心想为死去的父亲复仇的王子。由于太过疯狂导致了一场悲剧，伤害了爱人并迫使他出货去了。', 7, 310, 1, 130.6, 178.8, NULL, 4500, 16, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1075, '奥菲莉亚猪', 4, 5, '哈姆雷特猪的爱人。被发狂的哈姆雷特猪残酷对待，于是发了疯自己坐上出货卡车了。', 7, 311, 1, 129.5, 156.8, NULL, 4500, 16, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":2,"times":2,"picky":[4]}', NULL, NULL, 1788143395111, NULL),
(1076, '母猪赫尼文', 6, 4, '会带来丰饶但也是产出灾祸源头动物的神秘母猪。为了躲避追兵坐上了卡车。', 7, 313, 1, 127.8, 147.1, NULL, 10000, 24, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', '{"requirements":"成猪前体重限制 95.0-97.0 kg；成猪前周围需要有幼猪（未成猪）陪伴","tips":null}', '["好像从大不列颠岛来的","好像有最爱吃的饲料","好像因为生过小孩所以很瘦","好像会变成有很多小孩的母猪","好像会带来丰饶与灾祸"]', 1788143395111, NULL),
(1077, '天秤猪', 3, 5, '背上的天秤好像是衡量善恶的神的天秤。最近主要都是用来测量饲料。9月的猪。', 7, 314, 1, 129.6, 191.2, NULL, 3000, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[1,8]}', NULL, NULL, 1788143395111, NULL),
(1078, '水蜜桃猪', 3, 5, '最迷人的就是他可爱的屁屁。桃子有避邪效果所以鬼系列的猪猪都很怕他。9月的猪。', 7, 315, 1, 125.7, 170.3, NULL, 3000, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1079, '天蝎猪', 3, 2, '扮成大蝎子的猪。拥有敏锐的嗅觉和感觉，对于傲慢的人会用刺戳他。10月的猪。', 7, 316, 1, 126.7, 151.7, NULL, 3000, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":2,"times":2,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1080, '蒸汽机猪', 3, 2, '庆祝铁道纪念日的猪。听闻有卡车长得像火车于是被进货到这里。10月的猪。', 7, 317, 1, 130.4, 175.2, NULL, 3500, 20, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":6,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1081, '光猪氏', 5, 1, '拥有迷人美貌的多情贵族猪。养育了一只和初恋的母猪很像的小猪，正计划要结婚时就被出货了。', 7, 318, 1, 134.1, 214, NULL, 7000, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[7,8]}', NULL, NULL, 1788143395111, NULL),
(1082, '若猪', 4, 4, '虽然还幼小但是却有光猪氏初恋的身影。被光猪氏收养，在隐瞒身份的情况下长大。', 7, 319, 1, 129.7, 174.6, NULL, 5500, 10, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1083, '猪之上', 4, 4, '光猪氏一见倾心并养育长大的最爱的母猪。但因为自己不稳定的地位所以很担心其他母猪的存在。', 7, 320, 1, 129.7, 174.6, NULL, 5500, 10, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1084, '普丽帕尔契斯猪', 6, 1, '斯拉夫神话中负责掌管小猪的家畜守护神。温柔帮助小猪断奶并将他们托付给库雷马拉猪。', 7, 321, 1, 133, 217.7, NULL, 10000, 30, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0,"times":8,"picky":[]}', '{"requirements":"成猪前出货的猪由配种获得","tips":"每种食物至少喂食一次"}', '["好像能帮助小猪断奶","好像会变成小猪守护神","好像会树立断奶的榜样","好像会为出生的小猪送行","似乎喜欢外面的样子"]', 1788143395111, NULL),
(1085, '射手猪', 3, 3, '用弓高手，下半身是马的猎人。唱歌的话会为你打拍子的善良猪。11月的猪。', 7, 322, 1, 125.7, 170.3, NULL, 3000, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1086, '花栗猪', 3, 1, '为了过冬收集很多橡子。因为很可爱，就算其他猪的橡子被拿走也不会对他生气。11月的猪。', 7, 323, 1, 131.1, 170, NULL, 3500, 10, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[6]}', NULL, NULL, 1788143395111, NULL),
(1087, '魔羯猪', 3, 5, '像山羊又像鱼的猪。猪猪小屋的猪看到他不知道会不会引起恐慌。12月的猪。', 7, 324, 1, 127.7, 170.2, NULL, 3000, 12, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1088, '可内希特·鲁普雷希特猪', 4, 0, '被叫做黑色圣诞老人，会送恐怖礼物，恐怖到连坏小猪都会改过向善的那种。12月的猪。', 7, 325, 1, 129.4, 180, NULL, 5500, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[5,6]}', NULL, NULL, 1788143395111, NULL),
(1089, '章鱼猪', 3, 4, '爱章鱼爱到停不下来的猪。喜欢吃章鱼烧，喜欢的词是章鱼脚配线。和乌贼猪关系很好。', 7, 326, 1, 126.8, 167.8, NULL, 3000, 8, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1090, '乌贼猪', 3, 5, '爱章鱼爱到停不下来的猪。喜欢吃鱿鱼圈，喜欢的颜色是乌贼墨色。和章鱼猪关系很好。', 7, 327, 1, 126.7, 169.1, NULL, 3000, 10, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1091, '茶杯神猪', 6, 5, '不想要在台湾的猪体重竞赛祭典中变大变胖所以努力让自己变小。和外表不同其实出乎意料地重。', 7, 331, 1, 370, 400, NULL, 10000, 36, 1, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0,"times":16,"picky":[]}', '{"requirements":"成猪前体重限制 ≥128.0 kg；每种食物至少吃过两遍","tips":"每个食物都喂食两次，无顺序要求"}', '["注重健康很在意体型的样子","好像很神圣庄严","到底要养到多胖呀","注意挑食会吃很多的样子","好像是从台湾来的"]', 1788143395111, NULL),
(1092, '水瓶猪', 3, 2, '掉进水瓶里的猪。觉得别人是别人，自己是自己。身体保水性高。1月的猪。', 7, 332, 1, 127.7, 170.2, NULL, 3000, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1093, '击鼓猪', 4, 4, '想要参加西班牙击鼓节的猪。一边练习打鼓一边梦想着去西班牙。1月的猪。', 7, 333, 1, 128.7, 180, NULL, 4000, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1094, '双鱼猪', 3, 4, '心想变成鱼的话就不用出货了。在最喜欢的鱼玩偶身上系上蝴蝶结到哪都在一起。2月的猪。', 7, 334, 1, 125.9, 170.4, NULL, 3000, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1095, '威尼斯面具猪', 4, 3, '为了去威尼斯嘉年华会做足了准备。没人知道神秘面具下的真容。2月的猪。', 7, 335, 1, 133.6, 212.1, NULL, 4000, 24, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[7,8]}', NULL, NULL, 1788143395111, NULL),
(1096, '摘瘤猪爷爷', 4, 3, '脸颊上的瘤日益增大，因为治不好所以放弃了。会在宴会上热闹地配合大家气氛开心跳舞。', 7, 336, 1, 127.9, 182.1, NULL, 4000, 21, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1097, '开花猪爷爷', 4, 5, '太善良因此常常失去许多东西的猪。就算这样他还是会用一种撒了会开花的灰来点缀猪猪小屋。', 7, 337, 1, 129.7, 182.1, NULL, 4000, 21, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[]}', NULL, NULL, 1788143395111, NULL),
(1098, '竹取猪爷爷', 4, 3, '养育竹取猪的长者。因为女儿回月球很伤心所以到处寻找闪著金光的竹子结果误入猪猪小屋。', 7, 338, 1, 129.5, 195.3, NULL, 4000, 21, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[1,7]}', NULL, NULL, 1788143395111, NULL),
(1099, '海蓝宝石猪', 3, 2, '不管遇到什么事都能保持冷静及智慧。额头上的宝石据说是猪鱼的眼泪。3月的猪。', 7, 339, 1, 124.5, 172.1, NULL, 3500, 15, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395112, NULL),
(1100, '驱冬节猪', 4, 4, '摇响大牛铃并用歌声驱赶冬天，庆祝春天到来。大家一起游行的样子更可爱。3月的猪。', 7, 340, 1, 127.9, 180, NULL, 4000, 15, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395112, NULL),
(1101, '猪蜜拉', 6, 2, '散发着妖冶气息的美猪。真面目是以被迷惑的母猪为目标的吸血猪。如果有身体衰弱的猪猪要小心。', 7, 341, 1, 125, 189.5, NULL, 10000, 8, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', '{"requirements":"成猪时周围必须有母猪陪伴，不能有公猪","tips":null}', '["好像只在夜晚现身","似乎不太想吃东西","好像执着于单一性别？","好像特别讨厌圣歌","好像会咬别的猪"]', 1788143395112, NULL),
(1102, '钻石猪', 3, 5, '内心强大纯净无瑕的猪。如果出现在情侣猪面前，将会许下承诺代表他们永远的羁绊。4月的猪。', 7, 342, 1, 128.6, 170.3, NULL, 3500, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395112, NULL),
(1103, '塞维利亚四月节猪', 4, 3, '原为畜牧城市塞维利亚的春祭里的一只猪。据说很会喝酒，在祭典期间唱歌跳舞喝酒到通宵。4月的猪。', 7, 343, 1, 129.7, 180.2, NULL, 4000, 18, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395112, NULL),
(1104, '爱德华王子猪', 5, 1, '过着无忧无虑生活的王子。在他富裕又拘束的日子里，他遇到了一头跟他长得一样的猪。', 7, 344, 1, 135.5, 204.7, NULL, 5500, 10, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[8]}', NULL, NULL, 1788143395112, NULL),
(1105, '汤姆乞丐猪', 3, 1, '生活非常穷困的猪，向往著能住进宫殿。在偶然的机会下，他和王子交换身份过着王子的生活。', 7, 345, 1, 125.8, 159.4, NULL, 3000, 10, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[1]}', NULL, NULL, 1788143395112, NULL),
