(1109, '月光石猪', 3, 2, '常做月光浴的神秘猪。可以让出货前太激动的猪猪镇定下来。6月的猪。', 7, 350, 1, 126.2, 170.2, NULL, 3500, 12, 0, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[5]}', NULL, NULL, 1788143395112, NULL),
(1110, '芒果猪', 3, 5, '一边飘着热带香气一边招待芒果。变红的时候就代表要出货了。6月的猪。', 7, 351, 1, 125.9, 162.1, NULL, 3000, 16, 1, 1, 'normal', '{"hunt":{"sites":[2]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[2]}', NULL, NULL, 1788143395112, NULL),
