(1142, '秘密捕吏猪', 3, 1, '为了维持猪猪小猪的治安帮忙搜查及逮捕犯人的猪。和小偷相关的猪处的不好。', 7, 387, 1, 125.7, 169.4, NULL, 3000, 10, 0, 1, 'normal', '{"hunt":{"sites":[98],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.11318193277147}}},"specialFeeding":true}', '{"interval":1,"times":1,"picky":[]}', NULL, NULL, 1788143395112, NULL),
(1143, '小偷猪', 3, 3, '从饲料到珍珠、宝石等高价的东西都非常喜爱。由于手脚不干净所以就被出货了。', 7, 388, 1, 129.6, 188.4, NULL, 3500, 9, 1, 1, 'normal', '{"hunt":{"sites":[98],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.17544857142857}}},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[7,8]}', NULL, NULL, 1788143395112, NULL),
(1144, '地球猪', 3, 5, '虽然小时候经常和其他猪发生冲突，但现在个性变得很稳定。擅长动植物的培育。3月的猪。', 7, 389, 1, 127.7, 170.2, NULL, 3000, 12, 1, 1, 'normal', '{"hunt":{"sites":[83]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395112, NULL),
(1145, '女皇猪', 5, 4, '充满慈爱母性光辉的丰盈母猪。不过有时会感情用事变得很任性。3月的猪。', 7, 390, 1, 140.3, 216.3, NULL, 6000, 20, 1, 1, 'normal', '{"hunt":{"sites":[83]},"specialFeeding":true}', '{"interval":1,"times":3,"picky":[2,8]}', NULL, NULL, 1788143395112, NULL),
(1146, '加百列猪', 6, 1, '传达神的声音的大天使。常常为了履行职责来到猪猪广场宣布受孕其实一直计划着要逃跑。', 7, 391, 1, 123.9, 201.4, NULL, 10000, 12, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', '{"requirements":"成猪时周围要有母猪；成猪时周围要有老猪；只能吃松露","tips":null}', '["好像是大猪使的其中一人","好像会来宣告受孕报喜","数字似乎是关键","好像很在意最后审判中的猪","好像会传达神的讯息"]', 1788143395112, NULL),
(1147, '火星猪', 3, 4, '外表不同，但内在被说和地球猪很像。仔细看他的身体好像有爱心符号…？4月的猪。', 7, 392, 1, 126.2, 171.8, NULL, 3000, 10, 1, 1, 'normal', '{"hunt":{"sites":[84]},"specialFeeding":true}', '{"interval":1,"times":1,"picky":[4]}', NULL, NULL, 1788143395112, NULL),
(1148, '皇帝猪', 5, 1, '威风凛凛，擅长在猪猪小屋里进行统率。偶尔也会有支配性的举止出现。4月的猪。', 7, 393, 1, 132.6, 216.7, NULL, 5500, 20, 0, 1, 'normal', '{"hunt":{"sites":[84]},"specialFeeding":true}', '{"interval":1,"times":4,"picky":[4,8]}', NULL, NULL, 1788143395112, NULL),
(1149, '愚者猪', 4, 1, '乐观主义，口头禅是船到桥头自然直。他身边的小狗常常告知他哪里有危险，但他总是不在意。', 7, 394, 1, 132.8, 170.6, NULL, 4000, 24, 1, 1, 'normal', '{"hunt":{"sites":[98],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.11318193277147}}},"specialFeeding":true}', '{"interval":0,"times":7,"picky":[1]}', NULL, NULL, 1788143395112, NULL),
(1150, '死神猪', 4, 2, '看起来不吉利，但也是宣告新开始的猪。有一匹爱马，因为无法骑乘所以将它留下。', 7, 395, 1, 130.6, 178.9, NULL, 4000, 16, 0, 1, 'normal', '{"hunt":{"sites":[98],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.213535}}},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395112, NULL),
(1151, '木星猪', 3, 3, '拥有条纹花纹的大型猪，据说奔跑时会引起地面震动。5月限定的猪只。', 7, 398, 1, 126, 170.9, NULL, 3000, 12, 1, 1, 'normal', '{"hunt":{"sites":[85],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.17544857142857}}},"specialFeeding":true}', '{"interval":1,"times":1,"picky":[5]}', NULL, NULL, 1788143395112, NULL),
(1152, '猪教主', 4, 1, '他经常对苦恼的猪们说教，但内容总是有点模糊又抽象。五月限定猪只。', 7, 399, 1, 136.2, 205.5, NULL, 4000, 18, 0, 1, 'normal', '{"hunt":{"sites":[85],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.11318193277147}}},"specialFeeding":true}', '{"interval":0,"times":5,"picky":[8]}', NULL, NULL, 1788143395112, NULL),
(1153, '猪凰', 6, 2, '传说中的灵猪，据说即使被出货也有可能复活。最讨厌被拿来跟“朱雀猪”比较，一提到就会勃然大怒。', 7, 400, 1, 123.9, 177.6, NULL, 9000, 6, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', NULL, '{"requirements":"成猪时间限制 00:00:00-05:59:59；成猪时周围要有五种颜色的猪（含此猪）；禁止喂食","tips":null}', '["五彩的花纹，是牠的特征","似乎掌握猪界的平衡","好像会在清晨啼叫","象是会出现在神话里","只喝水的样子"]', 1788143395112, NULL),
(1154, '土星猪', 3, 2, '头上的圈圈很吸睛，个性却很温驯。只是圈圈太大，常常妨碍到其他小猪。6 月的猪。', 7, 401, 1, 126.9, 170.9, NULL, 3500, 13, 1, 1, 'normal', '{"hunt":{"sites":[86]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[6]}', NULL, NULL, 1788143395112, NULL);

INSERT INTO pigs (
  p_no, name, rare, color, description,
  atlas_type, atlas_index, atlas_visible,
  weight_small, weight_big,
  rent, price, lifespan, graze, special, status,
  acquisition, feeding, breeding_guide, hints, updated_at, updated_by
) VALUES
(1155, '恋恋猪', 4, 4, '总是黏在一起的甜蜜猪情侣。吵架的时候，空气会瞬间凝结……6 月的猪。', 7, 402, 1, 130.4, 176, NULL, 4000, 12, 0, 1, 'normal', '{"hunt":{"sites":[86]},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[2,4]}', NULL, NULL, 1788143395112, NULL),
(1156, '凉猪豆腐', 3, 5, '身体冰冰凉凉，还会微微抖动。夏天里大家最爱来找它乘凉！', 7, 403, 1, 127.3, 171.2, NULL, 3000, 12, 0, 1, 'normal', '{"hunt":{"sites":[98],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.17544857142857}}},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395112, NULL),
(1157, '味噌猪', 3, 3, '身上散发浓郁的味噌香气，带点深沉的风味。越睡香气越浓，让人忍不住想靠近。', 7, 404, 1, 125, 175.2, NULL, 3000, 18, 0, 1, 'normal', '{"hunt":{"sites":[98],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.17544857142857}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395112, NULL),
(1158, '赫丝缇猪', 6, 3, '用温柔的火焰守护猪猪小屋的温馨时光，对火源特别小心。', 7, 406, 1, 123.9, 212.2, NULL, 9500, 12, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', NULL, '{"requirements":"成猪时间限制 18:00:00-05:59:59；禁止放牧、可以不喂食；成猪前出货的猪必须是宙斯猪或波塞顿猪或黑帝斯猪","tips":null}', '["看起来非常重视家人","据说是六个姊弟中的长女","上一刻出货的猪似乎很重要","似乎会往壁炉里添柴火","听说她都待在家里"]', 1788143395112, NULL),
(1159, '天王星猪', 3, 2, '最爱横著滚来滚去，思绪与行动常偏离，是只谜样的猪。7月的猪。', 7, 407, 1, 126.2, 172.8, NULL, 3500, 16, 1, 1, 'normal', '{"hunt":{"sites":[87]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[5]}', NULL, NULL, 1788143395112, NULL),
(1160, '战车猪', 4, 1, '相信胜利勇往直前，因为看不到周围，常会撞到其他猪。7月的猪。', 7, 408, 1, 130.7, 183.3, NULL, 4500, 20, 0, 1, 'normal', '{"hunt":{"sites":[87]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[4]}', NULL, NULL, 1788143395112, NULL),
(1161, '哥布林猪', 3, 2, '调皮又灵巧的小猪。据说会偷偷用工具偷吃其他猪的饲料。', 7, 409, 1, 125.9, 172.3, NULL, 3000, 6, 1, 1, 'normal', '{"hunt":{"sites":[98],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.213535}}},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[]}', NULL, NULL, 1788143395112, NULL),
(1162, '史莱姆猪', 3, 5, '滑溜溜、捉摸不定的果冻身体。看似能从围栏缝隙逃出去，却总是被肚子卡住，动弹不得。', 7, 410, 1, 126.8, 174.5, NULL, 3000, 9, 0, 1, 'normal', '{"hunt":{"sites":[98],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.17544857142857}}},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[]}', NULL, NULL, 1788143395112, NULL),
(1163, '海王星猪', 4, 2, '语气飘忽、表达模糊，像是在梦与现实之间漂浮的猪。八月限定猪。', 7, 411, 1, 127.9, 164.9, NULL, 4500, 12, 0, 1, 'normal', '{"hunt":{"sites":[88]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[1,2]}', NULL, NULL, 1788143395112, NULL),
(1164, '力量猪', 4, 5, '就算饲料被抢也不怒不吵，默默忍耐。沉稳地守护着其他猪，是拥有真正力量的猪。八月限定猪。', 7, 412, 1, 129.7, 179.6, NULL, 4000, 16, 0, 1, 'normal', '{"hunt":{"sites":[88]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395112, NULL),
(1165, '阿努比斯猪', 6, 4, '担任衡量猪灵魂重量的重要任务。据说每次出货时，天秤都会倾斜。', 7, 413, 1, 123.9, 196, NULL, 9500, 9, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', NULL, '{"requirements":"饲养期间到成猪前必须出货任意猪5头；成猪时小屋地板上不能有便便；放牧场单独成猪","tips":null}', '["兄弟姐妹间似乎会结婚","据说个性和神圣粪金龟子相反","好像能量测猪的灵魂重量","好像一出生就会被藏起来","手足关系似乎很错综复杂"]', 1788143395112, NULL),
(1166, '冥王星猪', 4, 1, '静静漂浮在远方的独行猪，存在感虽然淡薄，但不知为何总让人无法忽视。九月限定猪。', 7, 414, 1, 129.7, 176, NULL, 4000, 12, 1, 1, 'normal', '{"hunt":{"sites":[89]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395112, NULL),
(1167, '隐者猪', 3, 5, '想要追求知识而隐居山中，不知道搭上那辆货车能不能到山里去呢？九月限定猪。', 7, 415, 1, 127.3, 170.3, NULL, 3500, 8, 0, 1, 'normal', '{"hunt":{"sites":[89]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[5]}', NULL, NULL, 1788143395112, NULL),
(1168, '命运之轮猪', 4, 2, '凡事都交给命运，不去抗拒。每次旋转，都是在饲料与出货的边缘挣扎。10月的猪。', 7, 416, 1, 130.4, 195.3, NULL, 4500, 8, 0, 1, 'normal', '{"hunt":{"sites":[90]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[1,8]}', NULL, NULL, 1788143395112, NULL),
(1169, '赛德娜猪', 3, 3, '虽然近在眼前，却感觉非常遥远。散发着如同深海般氛围的神秘小猪。10月的猪。', 7, 417, 1, 126.7, 170.3, NULL, 3500, 12, 1, 1, 'normal', '{"hunt":{"sites":[90]},"specialFeeding":true}', '{"interval":0,"times":2,"picky":[]}', NULL, NULL, 1788143395112, NULL),
(1170, '剑齿虎猪', 3, 1, '锐利的獠牙是它的骄傲，但吃饲料时反而很碍事。比起狩猎，更擅长午睡。', 7, 418, 1, 127.6, 172.8, NULL, 3500, 16, 0, 1, 'normal', '{"hunt":{"sites":[98],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.11318193277147}}},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395112, NULL),
(1171, '长毛象猪', 4, 1, '一旦睡着就很难醒来。毛皮柔软蓬松，即使天冷也能暖呼呼。', 7, 419, 1, 127.1, 170.8, NULL, 5000, 24, 0, 1, 'normal', '{"hunt":{"sites":[98],"prob":{"any":{"99":0.095077708555408},"same":{"99":0.11318193277147}}},"specialFeeding":true}', '{"interval":0,"times":4,"picky":[1,2]}', NULL, NULL, 1788143395112, NULL),
(1174, '正义猪', 4, 5, '拿着正义天秤在猪界进行裁决。但遇到最爱的饲料时，判断会稍微变得宽松。11月的猪。', 7, 422, 1, 131.5, 187.7, NULL, 5500, 12, 0, 1, 'normal', '{"hunt":{"sites":[91]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[7]}', NULL, NULL, 1788143395112, NULL),
(1175, '弥玛斯猪', 3, 2, '正值在意身上陨石坑痕迹的年纪。总是跟在土星身后。11月的猪。', 7, 423, 1, 127.5, 169.9, NULL, 4000, 8, 1, 1, 'normal', '{"hunt":{"sites":[91]},"specialFeeding":true}', '{"interval":0,"times":1,"picky":[6]}', NULL, NULL, 1788143395112, NULL),
(1176, '月读命猪', 6, 5, '记载于与月读猪不同的古书中。寡言而神秘的气质正是它的魅力所在。', 7, 424, 1, 124.9, 181.2, NULL, 10000, 8, 0, 1, 'normal', '{"hunt":{"sites":[0]},"specialFeeding":true}', '{"interval":0,"times":3,"picky":[]}', '{"requirements":"成猪时间限制 18:00:00-05:59:59；必须独自成猪；只能喂食3次","tips":null}', '["有一个喜欢的食物","似乎与娥眉月有关联","似乎与出没时间有关","会受到周围环境的影响","据说是从父亲的右眼诞生的"]', 1788143395112, NULL),
(450, '雪白猪', 5, 5, NULL, 7, 0, 1, 130.5, 185.2, 0, 0, 16, 1, 1, 'normal', NULL, '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395112, NULL),
(451, '蔷薇红猪', 4, 4, NULL, 7, 0, 1, 128.5, 178.8, 0, 0, 16, 1, 1, 'normal', NULL, '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395112, NULL),
(452, '被诅咒的熊猪', 3, 3, NULL, 7, 0, 1, 126.4, 204.5, 0, 0, 24, 0, 1, 'normal', NULL, '{"interval":0,"times":1,"picky":[8]}', NULL, NULL, 1788143395112, NULL),
(453, '莱特猪兄弟·威尔伯', 5, 3, NULL, 7, 0, 1, 129.7, 184.7, 0, 0, 24, 1, 1, 'normal', NULL, '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395112, NULL),
