(1180, '咕嘻鸽邮猪', 4, 1, NULL, 7, 0, 1, 129.6, 189, 0, 0, 13, 1, 1, 'normal', NULL, '{"interval":0,"times":4,"picky":[]}', NULL, NULL, 1788143395112, NULL),
(1181, '弗莱雅猪', 6, 6, NULL, 7, 0, 1, 129.3, 184.5, 0, 0, 9, 0, 1, 'normal', NULL, NULL, '{"requirements":"成猪前出货的猪必须是野猪；成猪时体重数值含有9，如：139.5,128.9","tips":null}', '["成猪时好像需要神秘的数字","似乎需要出货活祭品","好像会让心爱的对象变身","好像和北欧神殿有关","似乎有一位双胞胎哥哥"]', 1788143395112, NULL),
