(1185, '金星猪', 3, 2, NULL, 7, 0, 1, 126.4, 160.2, 0, 0, 8, 1, 1, 'normal', NULL, '{"interval":0,"times":2,"picky":[2]}', NULL, NULL, 1788143395112, NULL),
(1186, '红茶猪', 4, 4, NULL, 7, 0, 1, 129.7, 174.6, 0, 0, 10, 0, 1, 'normal', NULL, '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395112, NULL),
(1187, '咖啡猪', 4, 2, NULL, 7, 0, 1, 129.7, 174.6, 0, 0, 10, 0, 1, 'normal', NULL, '{"interval":0,"times":3,"picky":[]}', NULL, NULL, 1788143395112, NULL),
(1188, '德川猪康', 6, 1, NULL, 7, 0, 1, 123.9, 139.9, 0, 0, 8, 0, 1, 'normal', NULL, '{"interval":0,"times":1,"picky":[]}', '{"requirements":"成猪前周围必须有三种及以上的不同色系猪（肉色不算）；最少吃一口素食MIX、喂食次数<=3；成猪前地板上不能有食物","tips":null}', '["偏爱蔬菜等简单朴素的食物","能得到各路伙伴的帮助","有着不为人知的野心","非常节俭的猪","不急不躁且非常有耐心"]', 1788143395112, NULL),
(1189, '金丝雀猪', 3, 5, NULL, 7, 0, 1, 126.2, 167.8, 0, 0, 6, 0, 1, 'normal', NULL, '{"interval":0,"times":1,"picky":[5]}', NULL, NULL, 1788143395112, NULL),
